-- ============================================================
-- 本文件为 bible_jpn_data_05.sql 的第 b 半（原文件超过 SQL Editor 体积上限，故拆分）。
-- 运行顺序：01a → 01b → 02a → 02b → … → 06b。可重复运行（冲突自动跳过）。
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '马太福音', 40, 24, 44, 'ですから、あなたがたも用心していなさい。人の子は思いがけない時に来るのです。'),
('JPN', '马太福音', 40, 24, 45, 'ですから、主人によってその家のしもべたちの上に任命され、食事時に彼らに食事を与える、忠実で賢いしもべとはいったいだれでしょう。'),
('JPN', '马太福音', 40, 24, 46, '主人が帰って来たときに、そのようにしているのを見てもらえるしもべは幸いです。'),
('JPN', '马太福音', 40, 24, 47, 'まことに、あなたがたに言います。主人はその人に自分の全財産を任せるようになります。'),
('JPN', '马太福音', 40, 24, 48, 'しかし彼が悪いしもべで、『主人の帰りは遅くなる』と心の中で思い、'),
('JPN', '马太福音', 40, 24, 49, '仲間のしもべたちをたたき始め、酒飲みたちと食べたり飲んだりしているなら、'),
('JPN', '马太福音', 40, 24, 50, 'そのしもべの主人は、予期していない日、思いがけない時に帰って来て、'),
('JPN', '马太福音', 40, 24, 51, '彼を厳しく罰し、偽善者たちと同じ報いを与えます。しもべはそこで泣いて歯ぎしりするのです。'),
('JPN', '马太福音', 40, 25, 1, 'そこで、天の御国は、それぞれともしびを持って花婿を迎えに出る、十人の娘にたとえることができます。'),
('JPN', '马太福音', 40, 25, 2, 'そのうちの五人は愚かで、五人は賢かった。'),
('JPN', '马太福音', 40, 25, 3, '愚かな娘たちは、ともしびは持っていたが、油を持って来ていなかった。'),
('JPN', '马太福音', 40, 25, 4, '賢い娘たちは自分のともしびと一緒に、入れ物に油を入れて持っていた。'),
('JPN', '马太福音', 40, 25, 5, '花婿が来るのが遅くなったので、娘たちはみな眠くなり寝入ってしまった。'),
('JPN', '马太福音', 40, 25, 6, 'ところが夜中になって、『さあ、花婿だ。迎えに出なさい』と叫ぶ声がした。'),
('JPN', '马太福音', 40, 25, 7, 'そこで娘たちはみな起きて、自分のともしびを整えた。'),
('JPN', '马太福音', 40, 25, 8, '愚かな娘たちは賢い娘たちに言った。『私たちのともしびが消えそうなので、あなたがたの油を分けてください。』'),
('JPN', '马太福音', 40, 25, 9, 'しかし、賢い娘たちは答えた。『いいえ、分けてあげるにはとても足りません。それより、店に行って自分の分を買ってください。』'),
('JPN', '马太福音', 40, 25, 10, 'そこで娘たちが買いに行くと、その間に花婿が来た。用意ができていた娘たちは彼と一緒に婚礼の祝宴に入り、戸が閉じられた。'),
('JPN', '马太福音', 40, 25, 11, 'その後で残りの娘たちも来て、『ご主人様、ご主人様、開けてください』と言った。'),
('JPN', '马太福音', 40, 25, 12, 'しかし、主人は答えた。『まことに、あなたがたに言います。私はあなたがたを知りません。』'),
('JPN', '马太福音', 40, 25, 13, 'ですから、目を覚ましていなさい。その日、その時をあなたがたは知らないのですから。'),
('JPN', '马太福音', 40, 25, 14, '天の御国は、旅に出るにあたり、自分のしもべたちを呼んで財産を預ける人のようです。'),
('JPN', '马太福音', 40, 25, 15, '彼はそれぞれその能力に応じて、一人には五タラント、一人には二タラント、もう一人には一タラントを渡して旅に出かけた。するとすぐに、'),
('JPN', '马太福音', 40, 25, 16, '五タラント預かった者は出て行って、それで商売をし、ほかに五タラントをもうけた。'),
('JPN', '马太福音', 40, 25, 17, '同じように、二タラント預かった者もほかに二タラントをもうけた。'),
('JPN', '马太福音', 40, 25, 18, '一方、一タラント預かった者は出て行って地面に穴を掘り、主人の金を隠した。'),
('JPN', '马太福音', 40, 25, 19, 'さて、かなり時がたってから、しもべたちの主人が帰って来て彼らと清算をした。'),
('JPN', '马太福音', 40, 25, 20, 'すると、五タラント預かった者が進み出て、もう五タラントを差し出して言った。『ご主人様。私に五タラント預けてくださいましたが、ご覧ください、私はほかに五タラントをもうけました。』'),
('JPN', '马太福音', 40, 25, 21, '主人は彼に言った。『よくやった。良い忠実なしもべだ。おまえはわずかな物に忠実だったから、多くの物を任せよう。主人の喜びをともに喜んでくれ。』'),
('JPN', '马太福音', 40, 25, 22, '二タラントの者も進み出て言った。『ご主人様。私に二タラント預けてくださいましたが、ご覧ください、ほかに二タラントをもうけました。』'),
('JPN', '马太福音', 40, 25, 23, '主人は彼に言った。『よくやった。良い忠実なしもべだ。おまえはわずかな物に忠実だったから、多くの物を任せよう。主人の喜びをともに喜んでくれ。』'),
('JPN', '马太福音', 40, 25, 24, '一タラント預かっていた者も進み出て言った。『ご主人様。あなた様は蒔かなかったところから刈り取り、散らさなかったところからかき集める、厳しい方だと分かっていました。'),
('JPN', '马太福音', 40, 25, 25, 'それで私は怖くなり、出て行って、あなた様の一タラントを地の中に隠しておきました。ご覧ください、これがあなた様の物です。』'),
('JPN', '马太福音', 40, 25, 26, 'しかし、主人は彼に答えた。『悪い、怠け者のしもべだ。私が蒔かなかったところから刈り取り、散らさなかったところからかき集めると分かっていたというのか。'),
('JPN', '马太福音', 40, 25, 27, 'それなら、おまえは私の金を銀行に預けておくべきだった。そうすれば、私が帰って来たとき、私の物を利息とともに返してもらえたのに。'),
('JPN', '马太福音', 40, 25, 28, 'だから、そのタラントを彼から取り上げて、十タラント持っている者に与えよ。'),
('JPN', '马太福音', 40, 25, 29, 'だれでも持っている者は与えられてもっと豊かになり、持っていない者は持っている物までも取り上げられるのだ。'),
('JPN', '马太福音', 40, 25, 30, 'この役に立たないしもべは外の暗闇に追い出せ。そこで泣いて歯ぎしりするのだ。』'),
('JPN', '马太福音', 40, 25, 31, '人の子は、その栄光を帯びてすべての御使いたちを伴って来るとき、その栄光の座に着きます。'),
('JPN', '马太福音', 40, 25, 32, 'そして、すべての国の人々が御前に集められます。人の子は、羊飼いが羊をやぎからより分けるように彼らをより分け、'),
('JPN', '马太福音', 40, 25, 33, '羊を自分の右に、やぎを左に置きます。'),
('JPN', '马太福音', 40, 25, 34, 'それから王は右にいる者たちに言います。『さあ、わたしの父に祝福された人たち。世界の基が据えられたときから、あなたがたのために備えられていた御国を受け継ぎなさい。'),
('JPN', '马太福音', 40, 25, 35, 'あなたがたはわたしが空腹であったときに食べ物を与え、渇いていたときに飲ませ、旅人であったときに宿を貸し、'),
('JPN', '马太福音', 40, 25, 36, 'わたしが裸のときに服を着せ、病気をしたときに見舞い、牢にいたときに訪ねてくれたからです。』'),
('JPN', '马太福音', 40, 25, 37, 'すると、その正しい人たちは答えます。『主よ。いつ私たちはあなたが空腹なのを見て食べさせ、渇いているのを見て飲ませて差し上げたでしょうか。'),
('JPN', '马太福音', 40, 25, 38, 'いつ、旅人であるのを見て宿を貸し、裸なのを見て着せて差し上げたでしょうか。'),
('JPN', '马太福音', 40, 25, 39, 'いつ私たちは、あなたが病気をしたり牢におられたりするのを見て、お訪ねしたでしょうか。』'),
('JPN', '马太福音', 40, 25, 40, 'すると、王は彼らに答えます。『まことに、あなたがたに言います。あなたがたが、これらのわたしの兄弟たち、それも最も小さい者たちの一人にしたことは、わたしにしたのです。』'),
('JPN', '马太福音', 40, 25, 41, 'それから、王は左にいる者たちにも言います。『のろわれた者ども。わたしから離れ、悪魔とその使いのために用意された永遠の火に入れ。'),
('JPN', '马太福音', 40, 25, 42, 'おまえたちはわたしが空腹であったときに食べ物をくれず、渇いていたときに飲ませず、'),
('JPN', '马太福音', 40, 25, 43, 'わたしが旅人であったときに宿を貸さず、裸のときに服を着せず、病気のときや牢にいたときに訪ねてくれなかった。』'),
('JPN', '马太福音', 40, 25, 44, 'すると、彼らも答えます。『主よ。いつ私たちは、あなたが空腹であったり、渇いていたり、旅人であったり、裸でいたり、病気をしていたり、牢におられたりするのを見て、お世話をしなかったでしょうか。』'),
('JPN', '马太福音', 40, 25, 45, 'すると、王は彼らに答えます。『まことに、おまえたちに言う。おまえたちがこの最も小さい者たちの一人にしなかったのは、わたしにしなかったのだ。』'),
('JPN', '马太福音', 40, 25, 46, 'こうして、この者たちは永遠の刑罰に入り、正しい人たちは永遠のいのちに入るのです。」'),
('JPN', '马太福音', 40, 26, 1, 'イエスはこれらのことばをすべて語り終えると、弟子たちに言われた。'),
('JPN', '马太福音', 40, 26, 2, '「あなたがたも知っているとおり、二日たつと過越の祭りになります。そして、人の子は十字架につけられるために引き渡されます。」'),
('JPN', '马太福音', 40, 26, 3, 'そのころ、祭司長たちや民の長老たちはカヤパという大祭司の邸宅に集まり、'),
('JPN', '马太福音', 40, 26, 4, 'イエスをだまして捕らえ、殺そうと相談した。'),
('JPN', '马太福音', 40, 26, 5, '彼らは、「祭りの間はやめておこう。民の間に騒ぎが起こるといけない」と話していた。'),
('JPN', '马太福音', 40, 26, 6, 'さて、イエスがベタニアで、ツァラアトに冒された人シモンの家におられると、'),
('JPN', '马太福音', 40, 26, 7, 'ある女の人が、非常に高価な香油の入った小さな壺を持って、みもとにやって来た。そして、食卓に着いておられたイエスの頭に香油を注いだ。'),
('JPN', '马太福音', 40, 26, 8, '弟子たちはこれを見て、憤慨して言った。「何のために、こんな無駄なことをするのか。'),
('JPN', '马太福音', 40, 26, 9, 'この香油なら高く売れて、貧しい人たちに施しができたのに。」'),
('JPN', '马太福音', 40, 26, 10, 'イエスはこれを知って彼らに言われた。「なぜこの人を困らせるのですか。わたしに良いことをしてくれました。'),
('JPN', '马太福音', 40, 26, 11, '貧しい人々はいつもあなたがたと一緒にいます。しかし、わたしはいつも一緒にいるわけではありません。'),
('JPN', '马太福音', 40, 26, 12, 'この人はこの香油をわたしのからだに注いで、わたしを埋葬する備えをしてくれたのです。'),
('JPN', '马太福音', 40, 26, 13, 'まことに、あなたがたに言います。世界中どこでも、この福音が宣べ伝えられるところでは、この人がしたことも、この人の記念として語られます。」'),
('JPN', '马太福音', 40, 26, 14, 'そのとき、十二人の一人で、イスカリオテのユダという者が、祭司長たちのところへ行って、'),
('JPN', '马太福音', 40, 26, 15, 'こう言った。「私に何をくれますか。この私が、彼をあなたがたに引き渡しましょう。」すると、彼らは銀貨三十枚を彼に支払った。'),
('JPN', '马太福音', 40, 26, 16, 'そのときから、ユダはイエスを引き渡す機会を狙っていた。'),
('JPN', '马太福音', 40, 26, 17, 'さて、種なしパンの祭りの最初の日に、弟子たちがイエスのところに来て言った。「過越の食事をなさるのに、どこに用意をしましょうか。」'),
('JPN', '马太福音', 40, 26, 18, 'イエスは言われた。「都に入り、これこれの人のところに行って言いなさい。『わたしの時が近づいた。あなたのところで弟子たちと一緒に過越を祝いたい、と先生が言っております。』」'),
('JPN', '马太福音', 40, 26, 19, '弟子たちはイエスが命じられたとおりにして、過越の用意をした。'),
('JPN', '马太福音', 40, 26, 20, '夕方になって、イエスは十二人と一緒に食卓に着かれた。'),
('JPN', '马太福音', 40, 26, 21, '皆が食事をしているとき、イエスは言われた。「まことに、あなたがたに言います。あなたがたのうちの一人がわたしを裏切ります。」'),
('JPN', '马太福音', 40, 26, 22, '弟子たちはたいへん悲しんで、一人ひとりイエスに「主よ、まさか私ではないでしょう」と言い始めた。'),
('JPN', '马太福音', 40, 26, 23, 'イエスは答えられた。「わたしと一緒に手を鉢に浸した者がわたしを裏切ります。'),
('JPN', '马太福音', 40, 26, 24, '人の子は、自分について書かれているとおりに去って行きます。しかし、人の子を裏切るその人はわざわいです。そういう人は、生まれて来なければよかったのです。」'),
('JPN', '马太福音', 40, 26, 25, 'すると、イエスを裏切ろうとしていたユダが「先生、まさか私ではないでしょう」と言った。イエスは彼に「いや、そうだ」と言われた。'),
('JPN', '马太福音', 40, 26, 26, 'また、一同が食事をしているとき、イエスはパンを取り、神をほめたたえてこれを裂き、弟子たちに与えて言われた。「取って食べなさい。これはわたしのからだです。」'),
('JPN', '马太福音', 40, 26, 27, 'また、杯を取り、感謝の祈りをささげた後、こう言って彼らにお与えになった。「みな、この杯から飲みなさい。'),
('JPN', '马太福音', 40, 26, 28, 'これは多くの人のために、罪の赦しのために流される、わたしの契約の血です。'),
('JPN', '马太福音', 40, 26, 29, 'わたしはあなたがたに言います。今から後、わたしの父の御国であなたがたと新しく飲むその日まで、わたしがぶどうの実からできた物を飲むことは決してありません。」'),
('JPN', '马太福音', 40, 26, 30, 'そして、彼らは賛美の歌を歌ってからオリーブ山へ出かけた。'),
('JPN', '马太福音', 40, 26, 31, 'そのとき、イエスは弟子たちに言われた。「あなたがたはみな、今夜わたしにつまずきます。『わたしは羊飼いを打つ。すると、羊の群れは散らされる』と書いてあるからです。'),
('JPN', '马太福音', 40, 26, 32, 'しかしわたしは、よみがえった後、あなたがたより先にガリラヤへ行きます。」'),
('JPN', '马太福音', 40, 26, 33, 'すると、ペテロがイエスに答えた。「たとえ皆があなたにつまずいても、私は決してつまずきません。」'),
('JPN', '马太福音', 40, 26, 34, 'イエスは彼に言われた。「まことに、あなたに言います。あなたは今夜、鶏が鳴く前に三度わたしを知らないと言います。」'),
('JPN', '马太福音', 40, 26, 35, 'ペテロは言った。「たとえ、あなたと一緒に死ななければならないとしても、あなたを知らないなどとは決して申しません。」弟子たちはみな同じように言った。'),
('JPN', '马太福音', 40, 26, 36, 'それから、イエスは弟子たちと一緒にゲツセマネという場所に来て、彼らに「わたしがあそこに行って祈っている間、ここに座っていなさい」と言われた。'),
('JPN', '马太福音', 40, 26, 37, 'そして、ペテロとゼベダイの子二人を一緒に連れて行かれたが、イエスは悲しみもだえ始められた。'),
('JPN', '马太福音', 40, 26, 38, 'そのとき、イエスは彼らに言われた。「わたしは悲しみのあまり死ぬほどです。ここにいて、わたしと一緒に目を覚ましていなさい。」'),
('JPN', '马太福音', 40, 26, 39, 'それからイエスは少し進んで行って、ひれ伏して祈られた。「わが父よ、できることなら、この杯をわたしから過ぎ去らせてください。しかし、わたしが望むようにではなく、あなたが望まれるままに、なさってください。」'),
('JPN', '马太福音', 40, 26, 40, 'それから、イエスは弟子たちのところに戻って来て、彼らが眠っているのを見、ペテロに言われた。「あなたがたはこのように、一時間でも、わたしとともに目を覚ましていられなかったのですか。'),
('JPN', '马太福音', 40, 26, 41, '誘惑に陥らないように、目を覚まして祈っていなさい。霊は燃えていても肉は弱いのです。」'),
('JPN', '马太福音', 40, 26, 42, 'イエスは再び二度目に離れて行って、「わが父よ。わたしが飲まなければこの杯が過ぎ去らないのであれば、あなたのみこころがなりますように」と祈られた。'),
('JPN', '马太福音', 40, 26, 43, 'イエスが再び戻ってご覧になると、弟子たちは眠っていた。まぶたが重くなっていたのである。'),
('JPN', '马太福音', 40, 26, 44, 'イエスは、彼らを残して再び離れて行き、もう一度同じことばで三度目の祈りをされた。'),
('JPN', '马太福音', 40, 26, 45, 'それから、イエスは弟子たちのところに来て言われた。「まだ眠って休んでいるのですか。見なさい。時が来ました。人の子は罪人たちの手に渡されます。'),
('JPN', '马太福音', 40, 26, 46, '立ちなさい。さあ、行こう。見なさい。わたしを裏切る者が近くに来ています。」'),
('JPN', '马太福音', 40, 26, 47, 'イエスがまだ話しておられるうちに、見よ、十二人の一人のユダがやって来た。祭司長たちや民の長老たちから差し向けられ、剣や棒を手にした大勢の群衆も一緒であった。'),
('JPN', '马太福音', 40, 26, 48, 'イエスを裏切ろうとしていた者は彼らと合図を決め、「私が口づけをするのが、その人だ。その人を捕まえるのだ」と言っておいた。'),
('JPN', '马太福音', 40, 26, 49, 'それで彼はすぐにイエスに近づき、「先生、こんばんは」と言って口づけした。'),
('JPN', '马太福音', 40, 26, 50, 'イエスは彼に「友よ、あなたがしようとしていることをしなさい」と言われた。そのとき人々は近寄り、イエスに手をかけて捕らえた。'),
('JPN', '马太福音', 40, 26, 51, 'すると、イエスと一緒にいた者たちの一人が、見よ、手を伸ばして剣を抜き、大祭司のしもべに切りかかり、その耳を切り落とした。'),
('JPN', '马太福音', 40, 26, 52, 'そのとき、イエスは彼に言われた。「剣をもとに収めなさい。剣を取る者はみな剣で滅びます。'),
('JPN', '马太福音', 40, 26, 53, 'それとも、わたしが父にお願いして、十二軍団よりも多くの御使いを、今すぐわたしの配下に置いていただくことが、できないと思うのですか。'),
('JPN', '马太福音', 40, 26, 54, 'しかし、それでは、こうならなければならないと書いてある聖書が、どのようにして成就するのでしょう。」'),
('JPN', '马太福音', 40, 26, 55, 'また、そのとき群衆に言われた。「まるで強盗にでも向かうように、剣や棒を持ってわたしを捕らえに来たのですか。わたしは毎日、宮で座って教えていたのに、あなたがたはわたしを捕らえませんでした。'),
('JPN', '马太福音', 40, 26, 56, 'しかし、このすべてのことが起こったのは、預言者たちの書が成就するためです。」そのとき、弟子たちはみなイエスを見捨てて逃げてしまった。'),
('JPN', '马太福音', 40, 26, 57, '人々はイエスを捕らえると、大祭司カヤパのところに連れて行った。そこには律法学者たち、長老たちが集まっていた。'),
('JPN', '马太福音', 40, 26, 58, 'ペテロは、遠くからイエスの後について、大祭司の家の中庭まで行った。そして中に入り、成り行きを見ようと下役たちと一緒に座った。'),
('JPN', '马太福音', 40, 26, 59, 'さて、祭司長たちと最高法院全体は、イエスを死刑にするためにイエスに不利な偽証を得ようとした。'),
('JPN', '马太福音', 40, 26, 60, '多くの偽証人が出て来たが、証拠は得られなかった。しかし、最後に二人の者が進み出て、'),
('JPN', '马太福音', 40, 26, 61, 'こう言った。「この人は、『わたしは神の神殿を壊して、それを三日で建て直すことができる』と言いました。」'),
('JPN', '马太福音', 40, 26, 62, 'そこで大祭司が立ち上がり、イエスに言った。「何も答えないのか。この人たちがおまえに不利な証言をしているのは、どういうことか。」'),
('JPN', '马太福音', 40, 26, 63, 'しかし、イエスは黙っておられた。そこで大祭司はイエスに言った。「私は生ける神によっておまえに命じる。おまえは神の子キリストなのか、答えよ。」'),
('JPN', '马太福音', 40, 26, 64, 'イエスは彼に言われた。「あなたが言ったとおりです。しかし、わたしはあなたがたに言います。あなたがたは今から後に、人の子が力ある方の右の座に着き、そして天の雲とともに来るのを見ることになります。」'),
('JPN', '马太福音', 40, 26, 65, 'すると、大祭司は自分の衣を引き裂いて言った。「この男は神を冒瀆した。なぜこれ以上、証人が必要か。なんと、あなたがたは今、神を冒瀆することばを聞いたのだ。'),
('JPN', '马太福音', 40, 26, 66, 'どう思うか。」すると彼らは「彼は死に値する」と答えた。'),
('JPN', '马太福音', 40, 26, 67, 'それから彼らはイエスの顔に唾をかけ、拳で殴った。また、ある者たちはイエスを平手で打って、'),
('JPN', '马太福音', 40, 26, 68, '「当ててみろ、キリスト。おまえを打ったのはだれだ」と言った。'),
('JPN', '马太福音', 40, 26, 69, 'ペテロは外の中庭に座っていた。すると召使いの女が一人近づいて来て言った。「あなたもガリラヤ人イエスと一緒にいましたね。」'),
('JPN', '马太福音', 40, 26, 70, 'ペテロは皆の前で否定し、「何を言っているのか、私には分からない」と言った。'),
('JPN', '马太福音', 40, 26, 71, 'そして入り口まで出て行くと、別の召使いの女が彼を見て、そこにいる人たちに言った。「この人はナザレ人イエスと一緒にいました。」'),
('JPN', '马太福音', 40, 26, 72, 'ペテロは誓って、「そんな人は知らない」と再び否定した。'),
('JPN', '马太福音', 40, 26, 73, 'しばらくすると、立っていた人たちがペテロに近寄って来て言った。「確かに、あなたもあの人たちの仲間だ。ことばのなまりで分かる。」'),
('JPN', '马太福音', 40, 26, 74, 'するとペテロは、噓ならのろわれてもよいと誓い始め、「そんな人は知らない」と言った。すると、すぐに鶏が鳴いた。'),
('JPN', '马太福音', 40, 26, 75, 'ペテロは、「鶏が鳴く前に、あなたは三度わたしを知らないと言います」と言われたイエスのことばを思い出した。そして、外に出て行って激しく泣いた。'),
('JPN', '马太福音', 40, 27, 1, 'さて夜が明けると、祭司長たちと民の長老たちは全員で、イエスを死刑にするために協議した。'),
('JPN', '马太福音', 40, 27, 2, 'そしてイエスを縛って連れ出し、総督ピラトに引き渡した。'),
('JPN', '马太福音', 40, 27, 3, 'そのころ、イエスを売ったユダはイエスが死刑に定められたのを知って後悔し、銀貨三十枚を祭司長たちと長老たちに返して、言った。'),
('JPN', '马太福音', 40, 27, 4, '「私は無実の人の血を売って罪を犯しました。」しかし、彼らは言った。「われわれの知ったことか。自分で始末することだ。」'),
('JPN', '马太福音', 40, 27, 5, 'そこで、彼は銀貨を神殿に投げ込んで立ち去った。そして出て行って首をつった。'),
('JPN', '马太福音', 40, 27, 6, '祭司長たちは銀貨を取って、言った。「これは血の代価だから、神殿の金庫に入れることは許されない。」'),
('JPN', '马太福音', 40, 27, 7, 'そこで彼らは相談し、その金で陶器師の畑を買って、異国人のための墓地にした。'),
('JPN', '马太福音', 40, 27, 8, 'このため、その畑は今日まで血の畑と呼ばれている。'),
('JPN', '马太福音', 40, 27, 9, 'そのとき、預言者エレミヤを通して語られたことが成就した。「彼らは銀貨三十枚を取った。イスラエルの子らに値積もりされた人の価である。'),
('JPN', '马太福音', 40, 27, 10, '主が私に命じられたように、彼らはその金を払って陶器師の畑を買い取った。」'),
('JPN', '马太福音', 40, 27, 11, 'さて、イエスは総督の前に立たれた。総督はイエスに尋ねた。「あなたはユダヤ人の王なのか。」イエスは言われた。「あなたがそう言っています。」'),
('JPN', '马太福音', 40, 27, 12, 'しかし、祭司長たちや長老たちが訴えている間は、何もお答えにならなかった。'),
('JPN', '马太福音', 40, 27, 13, 'そのとき、ピラトはイエスに言った。「あんなにも、あなたに不利な証言をしているのが聞こえないのか。」'),
('JPN', '马太福音', 40, 27, 14, 'それでもイエスは、どのような訴えに対しても一言もお答えにならなかった。それには総督も非常に驚いた。'),
('JPN', '马太福音', 40, 27, 15, 'ところで、総督は祭りのたびに、群衆のため彼らが望む囚人を一人釈放することにしていた。'),
('JPN', '马太福音', 40, 27, 16, 'そのころ、バラバ・イエスという、名の知れた囚人が捕らえられていた。'),
('JPN', '马太福音', 40, 27, 17, 'それで、人々が集まったとき、ピラトは言った。「おまえたちはだれを釈放してほしいのか。バラバ・イエスか、それともキリストと呼ばれているイエスか。」'),
('JPN', '马太福音', 40, 27, 18, 'ピラトは、彼らがねたみからイエスを引き渡したことを知っていたのである。'),
('JPN', '马太福音', 40, 27, 19, 'ピラトが裁判の席に着いているときに、彼の妻が彼のもとに人を遣わして言った。「あの正しい人と関わらないでください。あの人のことで、私は今日、夢でたいへん苦しい目にあいましたから。」'),
('JPN', '马太福音', 40, 27, 20, 'しかし祭司長たちと長老たちは、バラバの釈放を要求してイエスは殺すよう、群衆を説得した。'),
('JPN', '马太福音', 40, 27, 21, '総督は彼らに言った。「おまえたちは二人のうちどちらを釈放してほしいのか。」彼らは言った。「バラバだ。」'),
('JPN', '马太福音', 40, 27, 22, 'ピラトは彼らに言った。「では、キリストと呼ばれているイエスを私はどのようにしようか。」彼らはみな言った。「十字架につけろ。」'),
('JPN', '马太福音', 40, 27, 23, 'ピラトは言った。「あの人がどんな悪いことをしたのか。」しかし、彼らはますます激しく叫び続けた。「十字架につけろ。」'),
('JPN', '马太福音', 40, 27, 24, 'ピラトは、語ることが何の役にも立たず、かえって暴動になりそうなのを見て、水を取り、群衆の目の前で手を洗って言った。「この人の血について私には責任がない。おまえたちで始末するがよい。」'),
('JPN', '马太福音', 40, 27, 25, 'すると、民はみな答えた。「その人の血は私たちや私たちの子どもらの上に。」'),
('JPN', '马太福音', 40, 27, 26, 'そこでピラトは彼らのためにバラバを釈放し、イエスはむちで打ってから、十字架につけるために引き渡した。'),
('JPN', '马太福音', 40, 27, 27, 'それから、総督の兵士たちはイエスを総督官邸の中に連れて行き、イエスの周りに全部隊を集めた。'),
('JPN', '马太福音', 40, 27, 28, 'そしてイエスが着ていた物を脱がせて、緋色のマントを着せた。'),
('JPN', '马太福音', 40, 27, 29, 'それから彼らは茨で冠を編んでイエスの頭に置き、右手に葦の棒を持たせた。そしてイエスの前にひざまずき、「ユダヤ人の王様、万歳」と言って、からかった。'),
('JPN', '马太福音', 40, 27, 30, 'またイエスに唾をかけ、葦の棒を取り上げて頭をたたいた。'),
('JPN', '马太福音', 40, 27, 31, 'こうしてイエスをからかってから、マントを脱がせて元の衣を着せ、十字架につけるために連れ出した。'),
('JPN', '马太福音', 40, 27, 32, '兵士たちが出て行くと、シモンという名のクレネ人に出会った。彼らはこの人に、イエスの十字架を無理やり背負わせた。'),
('JPN', '马太福音', 40, 27, 33, 'ゴルゴタと呼ばれている場所、すなわち「どくろの場所」に来ると、'),
('JPN', '马太福音', 40, 27, 34, '彼らはイエスに、苦みを混ぜたぶどう酒を飲ませようとした。イエスはそれをなめただけで、飲もうとはされなかった。'),
('JPN', '马太福音', 40, 27, 35, '彼らはイエスを十字架につけてから、くじを引いてその衣を分けた。'),
('JPN', '马太福音', 40, 27, 36, 'それから腰を下ろし、そこでイエスを見張っていた。'),
('JPN', '马太福音', 40, 27, 37, '彼らは、「これはユダヤ人の王イエスである」と書かれた罪状書きをイエスの頭の上に掲げた。'),
('JPN', '马太福音', 40, 27, 38, 'そのとき、イエスと一緒に二人の強盗が、一人は右に、一人は左に、十字架につけられていた。'),
('JPN', '马太福音', 40, 27, 39, '通りすがりの人たちは、頭を振りながらイエスをののしった。'),
('JPN', '马太福音', 40, 27, 40, '「神殿を壊して三日で建てる人よ、もしおまえが神の子なら自分を救ってみろ。そして十字架から降りて来い。」'),
('JPN', '马太福音', 40, 27, 41, '同じように祭司長たちも、律法学者たち、長老たちと一緒にイエスを嘲って言った。'),
('JPN', '马太福音', 40, 27, 42, '「他人は救ったが、自分は救えない。彼はイスラエルの王だ。今、十字架から降りてもらおう。そうすれば信じよう。'),
('JPN', '马太福音', 40, 27, 43, '彼は神に拠り頼んでいる。神のお気に入りなら、今、救い出してもらえ。『わたしは神の子だ』と言っているのだから。」'),
('JPN', '马太福音', 40, 27, 44, 'イエスと一緒に十字架につけられた強盗たちも、同じようにイエスをののしった。'),
('JPN', '马太福音', 40, 27, 45, 'さて、十二時から午後三時まで闇が全地をおおった。'),
('JPN', '马太福音', 40, 27, 46, '三時ごろ、イエスは大声で叫ばれた。「エリ、エリ、レマ、サバクタニ。」これは、「わが神、わが神、どうしてわたしをお見捨てになったのですか」という意味である。'),
('JPN', '马太福音', 40, 27, 47, 'そこに立っていた人たちの何人かが、これを聞いて言った。「この人はエリヤを呼んでいる。」'),
('JPN', '马太福音', 40, 27, 48, 'そのうちの一人がすぐに駆け寄り、海綿を取ってそれに酸いぶどう酒を含ませ、葦の棒に付けてイエスに飲ませようとした。'),
('JPN', '马太福音', 40, 27, 49, 'ほかの者たちは「待て。エリヤが救いに来るか見てみよう」と言った。'),
('JPN', '马太福音', 40, 27, 50, 'しかし、イエスは再び大声で叫んで霊を渡された。'),
('JPN', '马太福音', 40, 27, 51, 'すると見よ、神殿の幕が上から下まで真っ二つに裂けた。地が揺れ動き、岩が裂け、'),
('JPN', '马太福音', 40, 27, 52, '墓が開いて、眠りについていた多くの聖なる人々のからだが生き返った。'),
('JPN', '马太福音', 40, 27, 53, '彼らはイエスの復活の後で、墓から出て来て聖なる都に入り、多くの人に現れた。'),
('JPN', '马太福音', 40, 27, 54, '百人隊長や一緒にイエスを見張っていた者たちは、地震やいろいろな出来事を見て、非常に恐れて言った。「この方は本当に神の子であった。」'),
('JPN', '马太福音', 40, 27, 55, 'また、そこには大勢の女たちがいて、遠くから見ていた。ガリラヤからイエスについて来て仕えていた人たちである。'),
('JPN', '马太福音', 40, 27, 56, 'その中にはマグダラのマリア、ヤコブとヨセフの母マリア、ゼベダイの子たちの母がいた。'),
('JPN', '马太福音', 40, 27, 57, '夕方になり、アリマタヤ出身で金持ちの、ヨセフという名の人が来た。彼自身もイエスの弟子になっていた。'),
('JPN', '马太福音', 40, 27, 58, 'この人がピラトのところに行って、イエスのからだの下げ渡しを願い出た。そこでピラトは渡すように命じた。'),
('JPN', '马太福音', 40, 27, 59, 'ヨセフはからだを受け取ると、きれいな亜麻布に包み、'),
('JPN', '马太福音', 40, 27, 60, '岩を掘って造った自分の新しい墓に納めた。そして墓の入り口に大きな石を転がしておいて、立ち去った。'),
('JPN', '马太福音', 40, 27, 61, 'マグダラのマリアともう一人のマリアはそこにいて、墓の方を向いて座っていた。'),
('JPN', '马太福音', 40, 27, 62, '明くる日、すなわち、備え日の翌日、祭司長たちとパリサイ人たちはピラトのところに集まって、'),
('JPN', '马太福音', 40, 27, 63, 'こう言った。「閣下。人を惑わすあの男がまだ生きていたとき、『わたしは三日後によみがえる』と言っていたのを、私たちは思い出しました。'),
('JPN', '马太福音', 40, 27, 64, 'ですから、三日目まで墓の番をするように命じてください。そうでないと弟子たちが来て、彼を盗み出し、『死人の中からよみがえった』と民に言うかもしれません。そうなると、この惑わしのほうが、前の惑わしよりもひどいものになります。」'),
('JPN', '马太福音', 40, 27, 65, 'ピラトは彼らに言った。「番兵を出してやろう。行って、できるだけしっかりと番をするがよい。」'),
('JPN', '马太福音', 40, 27, 66, 'そこで彼らは行って番兵たちとともに石に封印をし、墓の番をした。'),
('JPN', '马太福音', 40, 28, 1, 'さて、安息日が終わって週の初めの日の明け方、マグダラのマリアともう一人のマリアが墓を見に行った。'),
('JPN', '马太福音', 40, 28, 2, 'すると見よ、大きな地震が起こった。主の使いが天から降りて来て石をわきに転がし、その上に座ったからである。'),
('JPN', '马太福音', 40, 28, 3, 'その姿は稲妻のようで、衣は雪のように白かった。'),
('JPN', '马太福音', 40, 28, 4, 'その恐ろしさに番兵たちは震え上がり、死人のようになった。'),
('JPN', '马太福音', 40, 28, 5, '御使いは女たちに言った。「あなたがたは、恐れることはありません。十字架につけられたイエスを捜しているのは分かっています。'),
('JPN', '马太福音', 40, 28, 6, 'ここにはおられません。前から言っておられたとおり、よみがえられたのです。さあ、納められていた場所を見なさい。'),
('JPN', '马太福音', 40, 28, 7, 'そして、急いで行って弟子たちに伝えなさい。『イエスは死人の中からよみがえられました。そして、あなたがたより先にガリラヤに行かれます。そこでお会いできます』と。いいですか、私は確かにあなたがたに伝えました。」'),
('JPN', '马太福音', 40, 28, 8, '彼女たちは恐ろしくはあったが大いに喜んで、急いで墓から立ち去り、弟子たちに知らせようと走って行った。'),
('JPN', '马太福音', 40, 28, 9, 'すると見よ、イエスが「おはよう」と言って彼女たちの前に現れた。彼女たちは近寄ってその足を抱き、イエスを拝した。'),
('JPN', '马太福音', 40, 28, 10, 'イエスは言われた。「恐れることはありません。行って、わたしの兄弟たちに、ガリラヤに行くように言いなさい。そこでわたしに会えます。」'),
('JPN', '马太福音', 40, 28, 11, '彼女たちが行き着かないうちに、番兵たちが何人か都に戻って、起こったことをすべて祭司長たちに報告した。'),
('JPN', '马太福音', 40, 28, 12, 'そこで祭司長たちは長老たちとともに集まって協議し、兵士たちに多額の金を与えて、'),
('JPN', '马太福音', 40, 28, 13, 'こう言った。「『弟子たちが夜やって来て、われわれが眠っている間にイエスを盗んで行った』と言いなさい。'),
('JPN', '马太福音', 40, 28, 14, 'もしこのことが総督の耳に入っても、私たちがうまく説得して、あなたがたには心配をかけないようにするから。」'),
('JPN', '马太福音', 40, 28, 15, 'そこで、彼らは金をもらって、言われたとおりにした。それで、この話は今日までユダヤ人の間に広まっている。'),
('JPN', '马太福音', 40, 28, 16, 'さて、十一人の弟子たちはガリラヤに行き、イエスが指示された山に登った。'),
('JPN', '马太福音', 40, 28, 17, 'そしてイエスに会って礼拝した。ただし、疑う者たちもいた。'),
('JPN', '马太福音', 40, 28, 18, 'イエスは近づいて来て、彼らにこう言われた。「わたしには天においても地においても、すべての権威が与えられています。'),
('JPN', '马太福音', 40, 28, 19, 'ですから、あなたがたは行って、あらゆる国の人々を弟子としなさい。父、子、聖霊の名において彼らにバプテスマを授け、'),
('JPN', '马太福音', 40, 28, 20, 'わたしがあなたがたに命じておいた、すべてのことを守るように教えなさい。見よ。わたしは世の終わりまで、いつもあなたがたとともにいます。」'),
('JPN', '马可福音', 41, 1, 1, '神の子、イエス・キリストの福音のはじめ。'),
('JPN', '马可福音', 41, 1, 2, '預言者イザヤの書にこのように書かれている。「見よ。わたしは、わたしの使いをあなたの前に遣わす。彼はあなたの道を備える。'),
('JPN', '马可福音', 41, 1, 3, '荒野で叫ぶ者の声がする。『主の道を用意せよ。主の通られる道をまっすぐにせよ。』」そのとおりに、'),
('JPN', '马可福音', 41, 1, 4, 'バプテスマのヨハネが荒野に現れ、罪の赦しに導く悔い改めのバプテスマを宣べ伝えた。'),
('JPN', '马可福音', 41, 1, 5, 'ユダヤ地方の全域とエルサレムの住民はみな、ヨハネのもとにやって来て、自分の罪を告白し、ヨルダン川で彼からバプテスマを受けていた。'),
('JPN', '马可福音', 41, 1, 6, 'ヨハネはらくだの毛の衣を着て、腰に革の帯を締め、いなごと野蜜を食べていた。'),
('JPN', '马可福音', 41, 1, 7, 'ヨハネはこう宣べ伝えた。「私よりも力のある方が私の後に来られます。私には、かがんでその方の履き物のひもを解く資格もありません。'),
('JPN', '马可福音', 41, 1, 8, '私はあなたがたに水でバプテスマを授けましたが、この方は聖霊によってバプテスマをお授けになります。」'),
('JPN', '马可福音', 41, 1, 9, 'そのころ、イエスはガリラヤのナザレからやって来て、ヨルダン川でヨハネからバプテスマを受けられた。'),
('JPN', '马可福音', 41, 1, 10, 'イエスは、水の中から上がるとすぐに、天が裂けて御霊が鳩のようにご自分に降って来るのをご覧になった。'),
('JPN', '马可福音', 41, 1, 11, 'すると天から声がした。「あなたはわたしの愛する子。わたしはあなたを喜ぶ。」'),
('JPN', '马可福音', 41, 1, 12, 'それからすぐに、御霊はイエスを荒野に追いやられた。'),
('JPN', '马可福音', 41, 1, 13, 'イエスは四十日間荒野にいて、サタンの試みを受けられた。イエスは野の獣とともにおられ、御使いたちが仕えていた。'),
('JPN', '马可福音', 41, 1, 14, 'ヨハネが捕らえられた後、イエスはガリラヤに行き、神の福音を宣べ伝えて言われた。'),
('JPN', '马可福音', 41, 1, 15, '「時が満ち、神の国が近づいた。悔い改めて福音を信じなさい。」'),
('JPN', '马可福音', 41, 1, 16, 'イエスはガリラヤ湖のほとりを通り、シモンとシモンの兄弟アンデレが、湖で網を打っているのをご覧になった。彼らは漁師であった。'),
('JPN', '马可福音', 41, 1, 17, 'イエスは彼らに言われた。「わたしについて来なさい。人間をとる漁師にしてあげよう。」'),
('JPN', '马可福音', 41, 1, 18, 'すると、彼らはすぐに網を捨てて、イエスに従った。'),
('JPN', '马可福音', 41, 1, 19, 'また少し先に行き、ゼベダイの子ヤコブと、その兄弟ヨハネをご覧になった。彼らは舟の中で網を繕っていた。'),
('JPN', '马可福音', 41, 1, 20, 'イエスはすぐに彼らをお呼びになった。すると彼らは、父ゼベダイを雇い人たちとともに舟に残して、イエスの後について行った。'),
('JPN', '马可福音', 41, 1, 21, 'それから、一行はカペナウムに入った。イエスはさっそく、安息日に会堂に入って教えられた。'),
('JPN', '马可福音', 41, 1, 22, '人々はその教えに驚いた。イエスが、律法学者たちのようにではなく、権威ある者として教えられたからである。'),
('JPN', '马可福音', 41, 1, 23, 'ちょうどそのとき、汚れた霊につかれた人がその会堂にいて、こう叫んだ。'),
('JPN', '马可福音', 41, 1, 24, '「ナザレの人イエスよ、私たちと何の関係があるのですか。私たちを滅ぼしに来たのですか。私はあなたがどなたなのか知っています。神の聖者です。」'),
('JPN', '马可福音', 41, 1, 25, 'イエスは彼を叱って、「黙れ。この人から出て行け」と言われた。'),
('JPN', '马可福音', 41, 1, 26, 'すると、汚れた霊はその人を引きつけさせ、大声をあげて、その人から出て行った。'),
('JPN', '马可福音', 41, 1, 27, '人々はみな驚いて、互いに論じ合った。「これは何だ。権威ある新しい教えだ。この方が汚れた霊にお命じになると、彼らは従うのだ。」'),
('JPN', '马可福音', 41, 1, 28, 'こうして、イエスの評判はすぐに、ガリラヤ周辺の全域、いたるところに広まった。'),
('JPN', '马可福音', 41, 1, 29, '一行は会堂を出るとすぐに、シモンとアンデレの家に入った。ヤコブとヨハネも一緒であった。'),
('JPN', '马可福音', 41, 1, 30, 'シモンの姑が熱を出して横になっていたので、人々はさっそく、彼女のことをイエスに知らせた。'),
('JPN', '马可福音', 41, 1, 31, 'イエスはそばに近寄り、手を取って起こされた。すると熱がひいた。彼女は人々をもてなした。'),
('JPN', '马可福音', 41, 1, 32, '夕方になり日が沈むと、人々は病人や悪霊につかれた人をみな、イエスのもとに連れて来た。'),
('JPN', '马可福音', 41, 1, 33, 'こうして町中の人が戸口に集まって来た。'),
('JPN', '马可福音', 41, 1, 34, 'イエスは、様々な病気にかかっている多くの人を癒やされた。また、多くの悪霊を追い出し、悪霊どもがものを言うのをお許しにならなかった。彼らがイエスのことを知っていたからである。'),
('JPN', '马可福音', 41, 1, 35, 'さて、イエスは朝早く、まだ暗いうちに起きて寂しいところに出かけて行き、そこで祈っておられた。'),
('JPN', '马可福音', 41, 1, 36, 'すると、シモンとその仲間たちがイエスの後を追って来て、'),
('JPN', '马可福音', 41, 1, 37, '彼を見つけ、「皆があなたを捜しています」と言った。'),
('JPN', '马可福音', 41, 1, 38, 'イエスは彼らに言われた。「さあ、近くにある別の町や村へ行こう。わたしはそこでも福音を伝えよう。そのために、わたしは出て来たのだから。」'),
('JPN', '马可福音', 41, 1, 39, 'こうしてイエスは、ガリラヤ全域にわたって、彼らの会堂で宣べ伝え、悪霊を追い出しておられた。'),
('JPN', '马可福音', 41, 1, 40, 'さて、ツァラアトに冒された人がイエスのもとに来て、ひざまずいて懇願した。「お心一つで、私をきよくすることがおできになります。」'),
('JPN', '马可福音', 41, 1, 41, 'イエスは深くあわれみ、手を伸ばして彼にさわり、「わたしの心だ。きよくなれ」と言われた。'),
('JPN', '马可福音', 41, 1, 42, 'すると、すぐにツァラアトが消えて、その人はきよくなった。'),
('JPN', '马可福音', 41, 1, 43, 'イエスは彼を厳しく戒めて、すぐに立ち去らせた。'),
('JPN', '马可福音', 41, 1, 44, 'そのとき彼にこう言われた。「だれにも何も話さないように気をつけなさい。ただ行って、自分を祭司に見せなさい。そして、人々への証しのために、モーセが命じた物をもって、あなたのきよめのささげ物をしなさい。」'),
('JPN', '马可福音', 41, 1, 45, 'ところが、彼は出て行ってふれ回り、この出来事を言い広め始めた。そのため、イエスはもはや表立って町に入ることができず、町の外の寂しいところにおられた。しかし、人々はいたるところからイエスのもとにやって来た。'),
('JPN', '马可福音', 41, 2, 1, '数日たって、イエスが再びカペナウムに来られると、家におられることが知れ渡った。'),
('JPN', '马可福音', 41, 2, 2, 'それで多くの人が集まったため、戸口のところまで隙間もないほどになった。イエスは、この人たちにみことばを話しておられた。'),
('JPN', '马可福音', 41, 2, 3, 'すると、人々が一人の中風の人を、みもとに連れて来た。彼は四人の人に担がれていた。'),
('JPN', '马可福音', 41, 2, 4, '彼らは群衆のためにイエスに近づくことができなかったので、イエスがおられるあたりの屋根をはがし、穴を開けて、中風の人が寝ている寝床をつり降ろした。'),
('JPN', '马可福音', 41, 2, 5, 'イエスは彼らの信仰を見て、中風の人に「子よ、あなたの罪は赦された」と言われた。'),
('JPN', '马可福音', 41, 2, 6, 'ところが、律法学者が何人かそこに座っていて、心の中であれこれと考えた。'),
('JPN', '马可福音', 41, 2, 7, '「この人は、なぜこのようなことを言うのか。神を冒瀆している。神おひとりのほかに、だれが罪を赦すことができるだろうか。」'),
('JPN', '马可福音', 41, 2, 8, '彼らが心のうちでこのようにあれこれと考えているのを、イエスはすぐにご自分の霊で見抜いて言われた。「なぜ、あなたがたは心の中でそんなことを考えているのか。'),
('JPN', '马可福音', 41, 2, 9, '中風の人に『あなたの罪は赦された』と言うのと、『起きて、寝床をたたんで歩け』と言うのと、どちらが易しいか。'),
('JPN', '马可福音', 41, 2, 10, 'しかし、人の子が地上で罪を赦す権威を持っていることを、あなたがたが知るために──。」そう言って、中風の人に言われた。'),
('JPN', '马可福音', 41, 2, 11, '「あなたに言う。起きなさい。寝床を担いで、家に帰りなさい。」'),
('JPN', '马可福音', 41, 2, 12, 'すると彼は立ち上がり、すぐに寝床を担ぎ、皆の前を出て行った。それで皆は驚き、「こんなことは、いまだかつて見たことがない」と言って神をあがめた。'),
('JPN', '马可福音', 41, 2, 13, 'イエスはまた湖のほとりへ出て行かれた。すると群衆がみな、みもとにやって来たので、彼らに教えられた。'),
('JPN', '马可福音', 41, 2, 14, 'イエスは道を通りながら、アルパヨの子レビが収税所に座っているのを見て、「わたしについて来なさい」と言われた。すると、彼は立ち上がってイエスに従った。'),
('JPN', '马可福音', 41, 2, 15, 'それからイエスは、レビの家で食卓に着かれた。取税人たちや罪人たちも大勢、イエスや弟子たちとともに食卓に着いていた。大勢の人々がいて、イエスに従っていたのである。'),
('JPN', '马可福音', 41, 2, 16, 'パリサイ派の律法学者たちは、イエスが罪人や取税人たちと一緒に食事をしているのを見て、弟子たちに言った。「なぜ、あの人は取税人や罪人たちと一緒に食事をするのですか。」'),
('JPN', '马可福音', 41, 2, 17, 'これを聞いて、イエスは彼らにこう言われた。「医者を必要とするのは、丈夫な人ではなく病人です。わたしが来たのは、正しい人を招くためではなく、罪人を招くためです。」'),
('JPN', '马可福音', 41, 2, 18, 'さて、ヨハネの弟子たちとパリサイ人たちは、断食をしていた。そこで、人々はイエスのもとに来て言った。「ヨハネの弟子たちやパリサイ人の弟子たちは断食をしているのに、なぜあなたの弟子たちは断食をしないのですか。」'),
('JPN', '马可福音', 41, 2, 19, 'イエスは彼らに言われた。「花婿に付き添う友人たちは、花婿が一緒にいる間、断食できるでしょうか。花婿が一緒にいる間は、断食できないのです。'),
('JPN', '马可福音', 41, 2, 20, 'しかし、彼らから花婿が取り去られる日が来ます。その日には断食をします。'),
('JPN', '马可福音', 41, 2, 21, 'だれも、真新しい布切れで古い衣に継ぎを当てたりはしません。そんなことをすれば、継ぎ切れが衣を、新しいものが古いものを引き裂き、破れはもっとひどくなります。'),
('JPN', '马可福音', 41, 2, 22, 'まただれも、新しいぶどう酒を古い皮袋に入れたりはしません。そんなことをすれば、ぶどう酒は皮袋を裂き、ぶどう酒も皮袋もだめになります。新しいぶどう酒は新しい皮袋に入れるものです。」'),
('JPN', '马可福音', 41, 2, 23, 'ある安息日に、イエスが麦畑を通っておられたときのことである。弟子たちは、道を進みながら穂を摘み始めた。'),
('JPN', '马可福音', 41, 2, 24, 'すると、パリサイ人たちがイエスに言った。「ご覧なさい。なぜ彼らは、安息日にしてはならないことをするのですか。」'),
('JPN', '马可福音', 41, 2, 25, 'イエスは言われた。「ダビデと供の者たちが食べ物がなくて空腹になったとき、ダビデが何をしたか、読んだことがないのですか。'),
('JPN', '马可福音', 41, 2, 26, '大祭司エブヤタルのころ、どのようにして、ダビデが神の家に入り、祭司以外の人が食べてはならない臨在のパンを食べて、一緒にいた人たちにも与えたか、読んだことがないのですか。」'),
('JPN', '马可福音', 41, 2, 27, 'そして言われた。「安息日は人のために設けられたのです。人が安息日のために造られたのではありません。'),
('JPN', '马可福音', 41, 2, 28, 'ですから、人の子は安息日にも主です。」'),
('JPN', '马可福音', 41, 3, 1, 'イエスは再び会堂に入られた。そこに片手の萎えた人がいた。'),
('JPN', '马可福音', 41, 3, 2, '人々は、イエスがこの人を安息日に治すかどうか、じっと見ていた。イエスを訴えるためであった。'),
('JPN', '马可福音', 41, 3, 3, 'イエスは、片手の萎えたその人に言われた。「真ん中に立ちなさい。」'),
('JPN', '马可福音', 41, 3, 4, 'それから彼らに言われた。「安息日に律法にかなっているのは、善を行うことですか、それとも悪を行うことですか。いのちを救うことですか、それとも殺すことですか。」彼らは黙っていた。'),
('JPN', '马可福音', 41, 3, 5, 'イエスは怒って彼らを見回し、その心の頑なさを嘆き悲しみながら、その人に「手を伸ばしなさい」と言われた。彼が手を伸ばすと、手は元どおりになった。'),
('JPN', '马可福音', 41, 3, 6, 'パリサイ人たちは出て行ってすぐに、ヘロデ党の者たちと一緒に、どうやってイエスを殺そうかと相談し始めた。'),
('JPN', '马可福音', 41, 3, 7, 'それから、イエスは弟子たちとともに湖の方に退かれた。すると、ガリラヤから出て来た非常に大勢の人々がついて来た。また、ユダヤから、'),
('JPN', '马可福音', 41, 3, 8, 'エルサレムから、イドマヤから、ヨルダンの川向こうや、ツロ、シドンのあたりからも、非常に大勢の人々が、イエスが行っておられることを聞いて、みもとにやって来た。'),
('JPN', '马可福音', 41, 3, 9, 'イエスは、群衆が押し寄せて来ないように、ご自分のために小舟を用意しておくよう、弟子たちに言われた。'),
('JPN', '马可福音', 41, 3, 10, 'イエスが多くの人を癒やされたので、病気に悩む人たちがみな、イエスにさわろうとして、みもとに押し寄せて来たのである。'),
('JPN', '马可福音', 41, 3, 11, '汚れた霊どもは、イエスを見るたびに御前にひれ伏して「あなたは神の子です」と叫んだ。'),
('JPN', '马可福音', 41, 3, 12, 'イエスはご自分のことを知らせないよう、彼らを厳しく戒められた。'),
('JPN', '马可福音', 41, 3, 13, 'さて、イエスが山に登り、ご自分が望む者たちを呼び寄せられると、彼らはみもとに来た。'),
('JPN', '马可福音', 41, 3, 14, 'イエスは十二人を任命し、彼らを使徒と呼ばれた。それは、彼らをご自分のそばに置くため、また彼らを遣わして宣教をさせ、'),
('JPN', '马可福音', 41, 3, 15, '彼らに悪霊を追い出す権威を持たせるためであった。'),
('JPN', '马可福音', 41, 3, 16, 'こうしてイエスは十二人を任命された。シモンにはペテロという名をつけ、'),
('JPN', '马可福音', 41, 3, 17, 'ゼベダイの子ヤコブと、ヤコブの兄弟ヨハネ、この二人にはボアネルゲ、すなわち、雷の子という名をつけられた。'),
('JPN', '马可福音', 41, 3, 18, 'さらに、アンデレ、ピリポ、バルトロマイ、マタイ、トマス、アルパヨの子ヤコブ、タダイ、熱心党のシモン、'),
('JPN', '马可福音', 41, 3, 19, 'イスカリオテのユダを任命された。このユダがイエスを裏切ったのである。'),
('JPN', '马可福音', 41, 3, 20, 'さて、イエスは家に戻られた。すると群衆が再び集まって来たので、イエスと弟子たちは食事をする暇もなかった。'),
('JPN', '马可福音', 41, 3, 21, 'これを聞いて、イエスの身内の者たちはイエスを連れ戻しに出かけた。人々が「イエスはおかしくなった」と言っていたからである。'),
('JPN', '马可福音', 41, 3, 22, 'また、エルサレムから下って来た律法学者たちも、「彼はベルゼブルにつかれている」とか、「悪霊どものかしらによって、悪霊どもを追い出している」と言っていた。'),
('JPN', '马可福音', 41, 3, 23, 'そこでイエスは彼らを呼び寄せて、たとえで語られた。「どうしてサタンがサタンを追い出せるのですか。'),
('JPN', '马可福音', 41, 3, 24, 'もし国が内部で分裂したら、その国は立ち行きません。'),
('JPN', '马可福音', 41, 3, 25, 'もし家が内部で分裂したら、その家は立ち行きません。'),
('JPN', '马可福音', 41, 3, 26, 'もし、サタンが自らに敵対して立ち、分裂したら、立ち行かずに滅んでしまいます。'),
('JPN', '马可福音', 41, 3, 27, 'まず強い者を縛り上げなければ、だれも、強い者の家に入って、家財を略奪することはできません。縛り上げれば、その家を略奪できます。'),
('JPN', '马可福音', 41, 3, 28, 'まことに、あなたがたに言います。人の子らは、どんな罪も赦していただけます。また、どれほど神を冒瀆することを言っても、赦していただけます。'),
('JPN', '马可福音', 41, 3, 29, 'しかし聖霊を冒瀆する者は、だれも永遠に赦されず、永遠の罪に定められます。」'),
('JPN', '马可福音', 41, 3, 30, 'このように言われたのは、彼らが、「イエスは汚れた霊につかれている」と言っていたからである。'),
('JPN', '马可福音', 41, 3, 31, 'さて、イエスの母と兄弟たちがやって来て、外に立ち、人を送ってイエスを呼んだ。'),
('JPN', '马可福音', 41, 3, 32, '大勢の人がイエスを囲んで座っていた。彼らは「ご覧ください。あなたの母上と兄弟姉妹方が、あなたを捜して外に来ておられます」と言った。'),
('JPN', '马可福音', 41, 3, 33, 'すると、イエスは彼らに答えて「わたしの母、わたしの兄弟とはだれでしょうか」と言われた。'),
('JPN', '马可福音', 41, 3, 34, 'そして、ご自分の周りに座っている人たちを見回して言われた。「ご覧なさい。わたしの母、わたしの兄弟です。'),
('JPN', '马可福音', 41, 3, 35, 'だれでも神のみこころを行う人、その人がわたしの兄弟、姉妹、母なのです。」'),
('JPN', '马可福音', 41, 4, 1, 'イエスは、再び湖のほとりで教え始められた。非常に多くの群衆がみもとに集まったので、イエスは湖で、舟に乗って腰を下ろされた。群衆はみな、湖の近くの陸地にいた。'),
('JPN', '马可福音', 41, 4, 2, 'イエスは、多くのことをたとえによって教えられた。その教えの中でこう言われた。'),
('JPN', '马可福音', 41, 4, 3, '「よく聞きなさい。種を蒔く人が種蒔きに出かけた。'),
('JPN', '马可福音', 41, 4, 4, '蒔いていると、ある種が道端に落ちた。すると、鳥が来て食べてしまった。'),
('JPN', '马可福音', 41, 4, 5, 'また、別の種は土の薄い岩地に落ちた。土が深くなかったのですぐに芽を出したが、'),
('JPN', '马可福音', 41, 4, 6, '日が昇るとしおれ、根づかずに枯れてしまった。'),
('JPN', '马可福音', 41, 4, 7, 'また、別の種は茨の中に落ちた。すると、茨が伸びてふさいでしまったので、実を結ばなかった。'),
('JPN', '马可福音', 41, 4, 8, 'また、別の種は良い地に落ちた。すると芽生え、育って実を結び、三十倍、六十倍、百倍になった。」'),
('JPN', '马可福音', 41, 4, 9, 'そしてイエスは言われた。「聞く耳のある者は聞きなさい。」'),
('JPN', '马可福音', 41, 4, 10, 'さて、イエスだけになったとき、イエスの周りにいた人たちが、十二人とともに、これらのたとえのことを尋ねた。'),
('JPN', '马可福音', 41, 4, 11, 'そこで、イエスは言われた。「あなたがたには神の国の奥義が与えられていますが、外の人たちには、すべてがたとえで語られるのです。'),
('JPN', '马可福音', 41, 4, 12, 'それはこうあるからです。『彼らは、見るには見るが知ることはなく、聞くには聞くが悟ることはない。彼らが立ち返って赦されることのないように。』」'),
('JPN', '马可福音', 41, 4, 13, 'そして、彼らにこう言われた。「このたとえが分からないのですか。そんなことで、どうしてすべてのたとえが理解できるでしょうか。'),
('JPN', '马可福音', 41, 4, 14, '種蒔く人は、みことばを蒔くのです。'),
('JPN', '马可福音', 41, 4, 15, '道端に蒔かれたものとは、こういう人たちのことです。みことばが蒔かれて彼らが聞くと、すぐにサタンが来て、彼らに蒔かれたみことばを取り去ります。'),
('JPN', '马可福音', 41, 4, 16, '岩地に蒔かれたものとは、こういう人たちのことです。みことばを聞くと、すぐに喜んで受け入れますが、'),
('JPN', '马可福音', 41, 4, 17, '自分の中に根がなく、しばらく続くだけです。後で、みことばのために困難や迫害が起こると、すぐにつまずいてしまいます。'),
('JPN', '马可福音', 41, 4, 18, 'もう一つの、茨の中に蒔かれたものとは、こういう人たちのことです。みことばを聞いたのに、'),
('JPN', '马可福音', 41, 4, 19, 'この世の思い煩いや、富の惑わし、そのほかいろいろな欲望が入り込んでみことばをふさぐので、実を結ぶことができません。'),
('JPN', '马可福音', 41, 4, 20, '良い地に蒔かれたものとは、みことばを聞いて受け入れ、三十倍、六十倍、百倍の実を結ぶ人たちのことです。」'),
('JPN', '马可福音', 41, 4, 21, 'イエスはまた彼らに言われた。「明かりを持って来るのは、升の下や寝台の下に置くためでしょうか。燭台の上に置くためではありませんか。'),
('JPN', '马可福音', 41, 4, 22, '隠れているもので、あらわにされないものはなく、秘められたもので、明らかにされないものはありません。'),
('JPN', '马可福音', 41, 4, 23, '聞く耳があるなら、聞きなさい。」'),
('JPN', '马可福音', 41, 4, 24, 'また彼らに言われた。「聞いていることに注意しなさい。あなたがたは、自分が量るその秤で自分にも量り与えられ、その上に増し加えられます。'),
('JPN', '马可福音', 41, 4, 25, '持っている人はさらに与えられ、持っていない人は、持っているものまで取り上げられてしまうからです。」'),
('JPN', '马可福音', 41, 4, 26, 'またイエスは言われた。「神の国はこのようなものです。人が地に種を蒔くと、'),
('JPN', '马可福音', 41, 4, 27, '夜昼、寝たり起きたりしているうちに種は芽を出して育ちますが、どのようにしてそうなるのか、その人は知りません。'),
('JPN', '马可福音', 41, 4, 28, '地はひとりでに実をならせ、初めに苗、次に穂、次に多くの実が穂にできます。'),
('JPN', '马可福音', 41, 4, 29, '実が熟すと、すぐに鎌を入れます。収穫の時が来たからです。」'),
('JPN', '马可福音', 41, 4, 30, 'またイエスは言われた。「神の国はどのようにたとえたらよいでしょうか。どんなたとえで説明できるでしょうか。'),
('JPN', '马可福音', 41, 4, 31, 'それはからし種のようなものです。地に蒔かれるときは、地の上のどんな種よりも小さいのですが、'),
('JPN', '马可福音', 41, 4, 32, '蒔かれると、生長してどんな野菜よりも大きくなり、大きな枝を張って、その陰に空の鳥が巣を作れるほどになります。」'),
('JPN', '马可福音', 41, 4, 33, 'イエスは、このような多くのたとえをもって、彼らの聞く力に応じてみことばを話された。'),
('JPN', '马可福音', 41, 4, 34, 'たとえを使わずに話されることはなかった。ただ、ご自分の弟子たちには、彼らだけがいるときに、すべてのことを解き明かされた。'),
('JPN', '马可福音', 41, 4, 35, 'さてその日、夕方になって、イエスは弟子たちに「向こう岸へ渡ろう」と言われた。'),
('JPN', '马可福音', 41, 4, 36, 'そこで弟子たちは群衆を後に残して、イエスを舟に乗せたままお連れした。ほかの舟も一緒に行った。'),
('JPN', '马可福音', 41, 4, 37, 'すると、激しい突風が起こって波が舟の中にまで入り、舟は水でいっぱいになった。'),
('JPN', '马可福音', 41, 4, 38, 'ところがイエスは、船尾で枕をして眠っておられた。弟子たちはイエスを起こして、「先生。私たちが死んでも、かまわないのですか」と言った。'),
('JPN', '马可福音', 41, 4, 39, 'イエスは起き上がって風を叱りつけ、湖に「黙れ、静まれ」と言われた。すると風はやみ、すっかり凪になった。'),
('JPN', '马可福音', 41, 4, 40, 'イエスは彼らに言われた。「どうして怖がるのですか。まだ信仰がないのですか。」'),
('JPN', '马可福音', 41, 4, 41, '彼らは非常に恐れて、互いに言った。「風や湖までが言うことを聞くとは、いったいこの方はどなたなのだろうか。」'),
('JPN', '马可福音', 41, 5, 1, 'こうして一行は、湖の向こう岸、ゲラサ人の地に着いた。'),
('JPN', '马可福音', 41, 5, 2, 'イエスが舟から上がられるとすぐに、汚れた霊につかれた人が、墓場から出て来てイエスを迎えた。'),
('JPN', '马可福音', 41, 5, 3, 'この人は墓場に住みついていて、もはやだれも、鎖を使ってでも、彼を縛っておくことができなかった。'),
('JPN', '马可福音', 41, 5, 4, '彼はたびたび足かせと鎖でつながれたが、鎖を引きちぎり、足かせも砕いてしまい、だれにも彼を押さえることはできなかった。'),
('JPN', '马可福音', 41, 5, 5, 'それで、夜も昼も墓場や山で叫び続け、石で自分のからだを傷つけていたのである。'),
('JPN', '马可福音', 41, 5, 6, '彼は遠くからイエスを見つけ、走って来て拝した。'),
('JPN', '马可福音', 41, 5, 7, 'そして大声で叫んで言った。「いと高き神の子イエスよ、私とあなたに何の関係があるのですか。神によってお願いします。私を苦しめないでください。」'),
('JPN', '马可福音', 41, 5, 8, 'イエスが、「汚れた霊よ、この人から出て行け」と言われたからである。'),
('JPN', '马可福音', 41, 5, 9, 'イエスが「おまえの名は何か」とお尋ねになると、彼は「私の名はレギオンです。私たちは大勢ですから」と言った。'),
('JPN', '马可福音', 41, 5, 10, 'そして、自分たちをこの地方から追い出さないでください、と懇願した。'),
('JPN', '马可福音', 41, 5, 11, 'ところで、そこの山腹では、おびただしい豚の群れが飼われていた。'),
('JPN', '马可福音', 41, 5, 12, '彼らはイエスに懇願して言った。「私たちが豚に入れるように、豚の中に送ってください。」'),
('JPN', '马可福音', 41, 5, 13, 'イエスはそれを許された。そこで、汚れた霊どもは出て行って豚に入った。すると、二千匹ほどの豚の群れが崖を下って湖へなだれ込み、その湖でおぼれて死んだ。'),
('JPN', '马可福音', 41, 5, 14, '豚を飼っていた人たちは逃げ出して、町や里でこのことを伝えた。人々は、何が起こったのかを見ようとやって来た。'),
('JPN', '马可福音', 41, 5, 15, 'そしてイエスのところに来ると、悪霊につかれていた人、すなわち、レギオンを宿していた人が服を着て、正気に返って座っているのを見て、恐ろしくなった。'),
('JPN', '马可福音', 41, 5, 16, '見ていた人たちは、悪霊につかれていた人に起こったことや豚のことを、人々に詳しく話して聞かせた。'),
('JPN', '马可福音', 41, 5, 17, 'すると人々はイエスに、この地方から出て行ってほしいと懇願した。'),
('JPN', '马可福音', 41, 5, 18, 'イエスが舟に乗ろうとされると、悪霊につかれていた人がお供させてほしいとイエスに願った。'),
('JPN', '马可福音', 41, 5, 19, 'しかし、イエスはお許しにならず、彼にこう言われた。「あなたの家、あなたの家族のところに帰りなさい。そして、主があなたに、どんなに大きなことをしてくださったか、どんなにあわれんでくださったかを知らせなさい。」'),
('JPN', '马可福音', 41, 5, 20, 'それで彼は立ち去り、イエスが自分にどれほど大きなことをしてくださったかを、デカポリス地方で言い広め始めた。人々はみな驚いた。'),
('JPN', '马可福音', 41, 5, 21, 'イエスが再び舟で向こう岸に渡られると、大勢の群衆がみもとに集まって来た。イエスは湖のほとりにおられた。'),
('JPN', '马可福音', 41, 5, 22, 'すると、会堂司の一人でヤイロという人が来て、イエスを見るとその足もとにひれ伏して、'),
('JPN', '马可福音', 41, 5, 23, 'こう懇願した。「私の小さい娘が死にかけています。娘が救われて生きられるように、どうかおいでになって、娘の上に手を置いてやってください。」'),
('JPN', '马可福音', 41, 5, 24, 'そこで、イエスはヤイロと一緒に行かれた。すると大勢の群衆がイエスについて来て、イエスに押し迫った。'),
('JPN', '马可福音', 41, 5, 25, 'そこに、十二年の間、長血をわずらっている女の人がいた。'),
('JPN', '马可福音', 41, 5, 26, '彼女は多くの医者からひどい目にあわされて、持っている物をすべて使い果たしたが、何のかいもなく、むしろもっと悪くなっていた。'),
('JPN', '马可福音', 41, 5, 27, '彼女はイエスのことを聞き、群衆とともにやって来て、うしろからイエスの衣に触れた。'),
('JPN', '马可福音', 41, 5, 28, '「あの方の衣にでも触れれば、私は救われる」と思っていたからである。'),
('JPN', '马可福音', 41, 5, 29, 'すると、すぐに血の源が乾いて、病気が癒やされたことをからだに感じた。'),
('JPN', '马可福音', 41, 5, 30, 'イエスも、自分のうちから力が出て行ったことにすぐ気がつき、群衆の中で振り向いて言われた。「だれがわたしの衣にさわったのですか。」'),
('JPN', '马可福音', 41, 5, 31, 'すると弟子たちはイエスに言った。「ご覧のとおり、群衆があなたに押し迫っています。それでも『だれがわたしにさわったのか』とおっしゃるのですか。」'),
('JPN', '马可福音', 41, 5, 32, 'しかし、イエスは周囲を見回して、だれがさわったのかを知ろうとされた。'),
('JPN', '马可福音', 41, 5, 33, '彼女は自分の身に起こったことを知り、恐れおののきながら進み出て、イエスの前にひれ伏し、真実をすべて話した。'),
('JPN', '马可福音', 41, 5, 34, 'イエスは彼女に言われた。「娘よ、あなたの信仰があなたを救ったのです。安心して行きなさい。苦しむことなく、健やかでいなさい。」'),
('JPN', '马可福音', 41, 5, 35, 'イエスがまだ話しておられるとき、会堂司の家から人々が来て言った。「お嬢さんは亡くなりました。これ以上、先生を煩わすことがあるでしょうか。」'),
('JPN', '马可福音', 41, 5, 36, 'イエスはその話をそばで聞き、会堂司に言われた。「恐れないで、ただ信じていなさい。」'),
('JPN', '马可福音', 41, 5, 37, 'イエスは、ペテロとヤコブ、ヤコブの兄弟ヨハネのほかは、だれも自分と一緒に行くのをお許しにならなかった。'),
('JPN', '马可福音', 41, 5, 38, '彼らは会堂司の家に着いた。イエスは、人々が取り乱して、大声で泣いたりわめいたりしているのを見て、'),
('JPN', '马可福音', 41, 5, 39, '中に入って、彼らにこう言われた。「どうして取り乱したり、泣いたりしているのですか。その子は死んだのではありません。眠っているのです。」'),
('JPN', '马可福音', 41, 5, 40, '人々はイエスをあざ笑った。しかし、イエスは皆を外に出し、子どもの父と母と、ご自分の供の者たちだけを連れて、その子のいるところに入って行かれた。'),
('JPN', '马可福音', 41, 5, 41, 'そして、子どもの手を取って言われた。「タリタ、クム。」訳すと、「少女よ、あなたに言う。起きなさい」という意味である。'),
('JPN', '马可福音', 41, 5, 42, 'すると、少女はすぐに起き上がり、歩き始めた。彼女は十二歳であった。それを見るや、人々は口もきけないほどに驚いた。'),
('JPN', '马可福音', 41, 5, 43, 'イエスは、このことをだれにも知らせないようにと厳しくお命じになり、また、少女に食べ物を与えるように言われた。'),
('JPN', '马可福音', 41, 6, 1, 'イエスはそこを去って郷里に行かれた。弟子たちもついて行った。'),
('JPN', '马可福音', 41, 6, 2, '安息日になって、イエスは会堂で教え始められた。それを聞いた多くの人々は驚いて言った。「この人は、こういうことをどこから得たのだろう。この人に与えられた知恵や、その手で行われるこのような力あるわざは、いったい何なのだろう。'),
('JPN', '马可福音', 41, 6, 3, 'この人は大工ではないか。マリアの子で、ヤコブ、ヨセ、ユダ、シモンの兄ではないか。その妹たちも、ここで私たちと一緒にいるではないか。」こうして彼らはイエスにつまずいた。'),
('JPN', '马可福音', 41, 6, 4, 'イエスは彼らに言われた。「預言者が敬われないのは、自分の郷里、親族、家族の間だけです。」'),
('JPN', '马可福音', 41, 6, 5, 'それで、何人かの病人に手を置いて癒やされたほかは、そこでは、何も力あるわざを行うことができなかった。'),
('JPN', '马可福音', 41, 6, 6, 'イエスは彼らの不信仰に驚かれた。それからイエスは、近くの村々を巡って教えられた。'),
('JPN', '马可福音', 41, 6, 7, 'また、十二人を呼び、二人ずつ遣わし始めて、彼らに汚れた霊を制する権威をお授けになった。'),
('JPN', '马可福音', 41, 6, 8, 'そして、旅のためには、杖一本のほか何も持たないように、パンも、袋も、胴巻の小銭も持って行かないように、'),
('JPN', '马可福音', 41, 6, 9, '履き物ははくように、しかし、下着は二枚着ないようにと命じられた。'),
('JPN', '马可福音', 41, 6, 10, 'また、彼らに言われた。「どこででも一軒の家に入ったら、そこの土地から出て行くまでは、その家にとどまりなさい。'),
('JPN', '马可福音', 41, 6, 11, 'あなたがたを受け入れず、あなたがたの言うことを聞かない場所があったなら、そこから出て行くときに、彼らに対する証言として、足の裏のちりを払い落としなさい。」'),
('JPN', '马可福音', 41, 6, 12, 'こうして十二人は出て行って、人々が悔い改めるように宣べ伝え、'),
('JPN', '马可福音', 41, 6, 13, '多くの悪霊を追い出し、油を塗って多くの病人を癒やした。'),
('JPN', '马可福音', 41, 6, 14, 'さて、イエスの名が知れ渡ったので、ヘロデ王の耳にも入った。人々は言っていた。「バプテスマのヨハネが死人の中からよみがえったのだ。だから、奇跡を行う力が彼のうちに働いているのだ。」'),
('JPN', '马可福音', 41, 6, 15, 'ほかの人々は、「彼はエリヤだ」と言い、さらにほかの人々は、「昔の預言者たちの一人のような預言者だ」と言っていた。'),
('JPN', '马可福音', 41, 6, 16, 'しかし、ヘロデはこれを聞いて言った。「私が首をはねた、あのヨハネがよみがえったのだ。」'),
('JPN', '马可福音', 41, 6, 17, '実は、以前このヘロデは、自分がめとった、兄弟ピリポの妻ヘロディアのことで、人を遣わしてヨハネを捕らえ、牢につないでいた。'),
('JPN', '马可福音', 41, 6, 18, 'これは、ヨハネがヘロデに、「あなたが兄弟の妻を自分のものにするのは、律法にかなっていない」と言い続けたからである。'),
('JPN', '马可福音', 41, 6, 19, 'ヘロディアはヨハネを恨み、彼を殺したいと思いながら、できずにいた。'),
('JPN', '马可福音', 41, 6, 20, 'それは、ヨハネが正しい聖なる人だと知っていたヘロデが、彼を恐れて保護し、その教えを聞いて非常に当惑しながらも、喜んで耳を傾けていたからである。'),
('JPN', '马可福音', 41, 6, 21, 'ところが、良い機会が訪れた。ヘロデが自分の誕生日に、重臣や千人隊長、ガリラヤのおもだった人たちを招いて、祝宴を設けたときのことであった。'),
('JPN', '马可福音', 41, 6, 22, 'ヘロディアの娘が入って来て踊りを踊り、ヘロデや列席の人々を喜ばせた。そこで王は少女に、「何でも欲しい物を求めなさい。おまえにあげよう」と言った。'),
('JPN', '马可福音', 41, 6, 23, 'そして、「おまえが願う物なら、私の国の半分でも与えよう」と堅く誓った。'),
('JPN', '马可福音', 41, 6, 24, 'そこで少女は出て行って、母親に言った。「何を願いましょうか。」すると母親は言った。「バプテスマのヨハネの首を。」'),
('JPN', '马可福音', 41, 6, 25, '少女はすぐに、王のところに急いで行って願った。「今すぐに、バプテスマのヨハネの首を盆に載せて、いただきとうございます。」'),
('JPN', '马可福音', 41, 6, 26, '王は非常に心を痛めたが、自分が誓ったことであり、列席の人たちの手前もあって、少女の願いを退けたくなかった。'),
('JPN', '马可福音', 41, 6, 27, 'そこで、すぐに護衛兵を遣わして、ヨハネの首を持って来るように命じた。護衛兵は行って、牢の中でヨハネの首をはね、'),
('JPN', '马可福音', 41, 6, 28, 'その首を盆に載せて持って来て、少女に渡した。少女はそれを母親に渡した。'),
('JPN', '马可福音', 41, 6, 29, 'このことを聞いたヨハネの弟子たちは、やって来て遺体を引き取り、墓に納めたのであった。'),
('JPN', '马可福音', 41, 6, 30, 'さて、使徒たちはイエスのもとに集まり、自分たちがしたこと、教えたことを、残らずイエスに報告した。'),
('JPN', '马可福音', 41, 6, 31, 'するとイエスは彼らに言われた。「さあ、あなたがただけで、寂しいところへ行って、しばらく休みなさい。」出入りする人が多くて、食事をとる時間さえなかったからである。'),
('JPN', '马可福音', 41, 6, 32, 'そこで彼らは、自分たちだけで舟に乗り、寂しいところに行った。'),
('JPN', '马可福音', 41, 6, 33, 'ところが、多くの人々が、彼らが出て行くのを見てそれと気づき、どの町からもそこへ徒歩で駆けつけて、彼らよりも先に着いた。'),
('JPN', '马可福音', 41, 6, 34, 'イエスは舟から上がって、大勢の群衆をご覧になった。彼らが羊飼いのいない羊の群れのようであったので、イエスは彼らを深くあわれみ、多くのことを教え始められた。'),
('JPN', '马可福音', 41, 6, 35, 'そのうちに、すでに遅い時刻になったので、弟子たちはイエスのところに来て言った。「ここは人里離れたところで、もう遅い時刻になりました。'),
('JPN', '马可福音', 41, 6, 36, '皆を解散させてください。そうすれば、周りの里や村に行って、自分たちで食べる物を買うことができるでしょう。」'),
('JPN', '马可福音', 41, 6, 37, 'すると、イエスは答えられた。「あなたがたが、あの人たちに食べる物をあげなさい。」弟子たちは言った。「私たちが出かけて行って、二百デナリのパンを買い、彼らに食べさせるのですか。」'),
('JPN', '马可福音', 41, 6, 38, 'イエスは彼らに言われた。「パンはいくつありますか。行って見て来なさい。」彼らは確かめて来て言った。「五つです。それに魚が二匹あります。」'),
('JPN', '马可福音', 41, 6, 39, 'するとイエスは、皆を組に分けて青草の上に座らせるように、弟子たちに命じられた。'),
('JPN', '马可福音', 41, 6, 40, '人々は、百人ずつ、あるいは五十人ずつまとまって座った。'),
('JPN', '马可福音', 41, 6, 41, 'イエスは五つのパンと二匹の魚を取り、天を見上げて神をほめたたえ、パンを裂き、そして人々に配るように弟子たちにお与えになった。また、二匹の魚も皆に分けられた。'),
('JPN', '马可福音', 41, 6, 42, '彼らはみな、食べて満腹した。'),
('JPN', '马可福音', 41, 6, 43, 'そして、パン切れを十二のかごいっぱいに集め、魚の残りも集めた。'),
('JPN', '马可福音', 41, 6, 44, 'パンを食べたのは、男が五千人であった。'),
('JPN', '马可福音', 41, 6, 45, 'それからすぐに、イエスは弟子たちを無理やり舟に乗り込ませ、向こう岸のベツサイダに先に行かせて、その間に、ご自分は群衆を解散させておられた。'),
('JPN', '马可福音', 41, 6, 46, 'そして彼らに別れを告げると、祈るために山に向かわれた。'),
('JPN', '马可福音', 41, 6, 47, '夕方になったとき、舟は湖の真ん中にあり、イエスだけが陸地におられた。'),
('JPN', '马可福音', 41, 6, 48, 'イエスは、弟子たちが向かい風のために漕ぎあぐねているのを見て、夜明けが近づいたころ、湖の上を歩いて彼らのところへ行かれた。そばを通り過ぎるおつもりであった。'),
('JPN', '马可福音', 41, 6, 49, 'しかし、イエスが湖の上を歩いておられるのを見た弟子たちは、幽霊だと思い、叫び声をあげた。'),
('JPN', '马可福音', 41, 6, 50, 'みなイエスを見ておびえてしまったのである。そこで、イエスはすぐに彼らに話しかけ、「しっかりしなさい。わたしだ。恐れることはない」と言われた。'),
('JPN', '马可福音', 41, 6, 51, 'そして、彼らのいる舟に乗り込まれると、風はやんだ。弟子たちは心の中で非常に驚いた。'),
('JPN', '马可福音', 41, 6, 52, '彼らはパンのことを理解せず、その心が頑なになっていたからである。'),
('JPN', '马可福音', 41, 6, 53, 'それから、彼らは湖を渡ってゲネサレの地に着き、舟をつないだ。'),
('JPN', '马可福音', 41, 6, 54, '彼らが舟から上がると、人々はすぐにイエスだと気がついた。'),
('JPN', '马可福音', 41, 6, 55, 'そしてその地方の中を走り回り、どこでもイエスがおられると聞いた場所へ、病人を床に載せて運び始めた。'),
('JPN', '马可福音', 41, 6, 56, '村でも町でも里でも、イエスが入って行かれると、人々は病人たちを広場に寝かせ、せめて、衣の房にでもさわらせてやってくださいと懇願した。そして、さわった人たちはみな癒やされた。'),
('JPN', '马可福音', 41, 7, 1, 'さて、パリサイ人たちと、エルサレムから来た何人かの律法学者たちが、イエスのもとに集まった。'),
('JPN', '马可福音', 41, 7, 2, '彼らは、イエスの弟子のうちのある者たちが、汚れた手で、すなわち、洗っていない手でパンを食べているのを見た。'),
('JPN', '马可福音', 41, 7, 3, 'パリサイ人をはじめユダヤ人はみな、昔の人たちの言い伝えを堅く守って、手をよく洗わずに食事をすることはなく、'),
('JPN', '马可福音', 41, 7, 4, '市場から戻ったときは、からだをきよめてからでないと食べることをしなかった。ほかにも、杯、水差し、銅器や寝台を洗いきよめることなど、受け継いで堅く守っていることが、たくさんあったのである。'),
('JPN', '马可福音', 41, 7, 5, 'パリサイ人たちと律法学者たちはイエスに尋ねた。「なぜ、あなたの弟子たちは、昔の人たちの言い伝えによって歩まず、汚れた手でパンを食べるのですか。」'),
('JPN', '马可福音', 41, 7, 6, 'イエスは彼らに言われた。「イザヤは、あなたがた偽善者について見事に預言し、こう書いています。『この民は口先でわたしを敬うが、その心はわたしから遠く離れている。'),
('JPN', '马可福音', 41, 7, 7, '彼らがわたしを礼拝しても、むなしい。人間の命令を、教えとして教えるのだから。』'),
('JPN', '马可福音', 41, 7, 8, 'あなたがたは神の戒めを捨てて、人間の言い伝えを堅く守っているのです。」'),
('JPN', '马可福音', 41, 7, 9, 'またイエスは言われた。「あなたがたは、自分たちの言い伝えを保つために、見事に神の戒めをないがしろにしています。'),
('JPN', '马可福音', 41, 7, 10, 'モーセは、『あなたの父と母を敬え』、また『父や母をののしる者は、必ず殺されなければならない』と言いました。'),
('JPN', '马可福音', 41, 7, 11, 'それなのに、あなたがたは、『もし人が、父または母に向かって、私からあなたに差し上げるはずの物は、コルバン（すなわち、ささげ物）です、と言うなら──』と言って、'),
('JPN', '马可福音', 41, 7, 12, 'その人が、父または母のために、何もしないようにさせています。'),
('JPN', '马可福音', 41, 7, 13, 'このようにしてあなたがたは、自分たちに伝えられた言い伝えによって、神のことばを無にしています。そして、これと同じようなことを、たくさん行っているのです。」'),
('JPN', '马可福音', 41, 7, 14, 'イエスは再び群衆を呼び寄せて言われた。「みな、わたしの言うことを聞いて、悟りなさい。'),
('JPN', '马可福音', 41, 7, 15, '外から入って、人を汚すことのできるものは何もありません。人の中から出て来るものが、人を汚すのです。」'),
('JPN', '马可福音', 41, 7, 17, 'イエスが群衆を離れて家に入られると、弟子たちは、このたとえについて尋ねた。'),
('JPN', '马可福音', 41, 7, 18, 'イエスは彼らに言われた。「あなたがたまで、そんなにも物分かりが悪いのですか。分からないのですか。外から人に入って来るどんなものも、人を汚すことはできません。'),
('JPN', '马可福音', 41, 7, 19, 'それは人の心には入らず、腹に入り排泄されます。」こうしてイエスは、すべての食物をきよいとされた。'),
('JPN', '马可福音', 41, 7, 20, 'イエスはまた言われた。「人から出て来るもの、それが人を汚すのです。'),
('JPN', '马可福音', 41, 7, 21, '内側から、すなわち人の心の中から、悪い考えが出て来ます。淫らな行い、盗み、殺人、'),
('JPN', '马可福音', 41, 7, 22, '姦淫、貪欲、悪行、欺き、好色、ねたみ、ののしり、高慢、愚かさで、'),
('JPN', '马可福音', 41, 7, 23, 'これらの悪は、みな内側から出て来て、人を汚すのです。」'),
('JPN', '马可福音', 41, 7, 24, 'イエスは立ち上がり、そこからツロの地方へ行かれた。家に入って、だれにも知られたくないと思っておられたが、隠れていることはできなかった。'),
('JPN', '马可福音', 41, 7, 25, 'ある女の人が、すぐにイエスのことを聞き、やって来てその足もとにひれ伏した。彼女の幼い娘は、汚れた霊につかれていた。'),
('JPN', '马可福音', 41, 7, 26, '彼女はギリシア人で、シリア・フェニキアの生まれであったが、自分の娘から悪霊を追い出してくださるようイエスに願った。'),
('JPN', '马可福音', 41, 7, 27, 'するとイエスは言われた。「まず子どもたちを満腹にさせなければなりません。子どもたちのパンを取り上げて、小犬に投げてやるのは良くないことです。」'),
('JPN', '马可福音', 41, 7, 28, '彼女は答えた。「主よ。食卓の下の小犬でも、子どもたちのパン屑はいただきます。」'),
('JPN', '马可福音', 41, 7, 29, 'そこでイエスは言われた。「そこまで言うのなら、家に帰りなさい。悪霊はあなたの娘から出て行きました。」'),
('JPN', '马可福音', 41, 7, 30, '彼女が家に帰ると、その子は床の上に伏していたが、悪霊はすでに出ていた。'),
('JPN', '马可福音', 41, 7, 31, 'イエスは再びツロの地方を出て、シドンを通り、デカポリス地方を通り抜けて、ガリラヤ湖に来られた。'),
('JPN', '马可福音', 41, 7, 32, '人々は、耳が聞こえず口のきけない人を連れて来て、彼の上に手を置いてくださいと懇願した。'),
('JPN', '马可福音', 41, 7, 33, 'そこで、イエスはその人だけを群衆の中から連れ出し、ご自分の指を彼の両耳に入れ、それから唾を付けてその舌にさわられた。'),
('JPN', '马可福音', 41, 7, 34, 'そして天を見上げ、深く息をして、その人に「エパタ」、すなわち「開け」と言われた。'),
('JPN', '马可福音', 41, 7, 35, 'すると、すぐに彼の耳が開き、舌のもつれが解け、はっきりと話せるようになった。'),
('JPN', '马可福音', 41, 7, 36, 'イエスは、このことをだれにも言ってはならないと人々に命じられた。しかし、彼らは口止めされればされるほど、かえってますます言い広めた。'),
('JPN', '马可福音', 41, 7, 37, '人々は非常に驚いて言った。「この方のなさったことは、みなすばらしい。耳の聞こえない人たちを聞こえるようにし、口のきけない人たちを話せるようにされた。」'),
('JPN', '马可福音', 41, 8, 1, 'そのころ、再び大勢の群衆が集まっていた。食べる物がなかったので、イエスは弟子たちを呼んで言われた。'),
('JPN', '马可福音', 41, 8, 2, '「かわいそうに、この群衆はすでに三日間わたしとともにいて、食べる物を持っていないのです。'),
('JPN', '马可福音', 41, 8, 3, '空腹のまま家に帰らせたら、途中で動けなくなります。遠くから来ている人もいます。」'),
('JPN', '马可福音', 41, 8, 4, '弟子たちは答えた。「こんな人里離れたところで、どこからパンを手に入れて、この人たちに十分食べさせることができるでしょう。」'),
('JPN', '马可福音', 41, 8, 5, 'すると、イエスはお尋ねになった。「パンはいくつありますか。」弟子たちは「七つあります」と答えた。'),
('JPN', '马可福音', 41, 8, 6, 'すると、イエスは群衆に地面に座るように命じられた。それから七つのパンを取り、感謝の祈りをささげてからそれを裂き、配るようにと弟子たちにお与えになった。弟子たちはそれを群衆に配った。'),
('JPN', '马可福音', 41, 8, 7, 'また、小魚が少しあったので、それについて神をほめたたえてから、これも配るように言われた。'),
('JPN', '马可福音', 41, 8, 8, '群衆は食べて満腹した。そして余りのパン切れを取り集めると、七つのかごになった。'),
('JPN', '马可福音', 41, 8, 9, 'そこには、およそ四千人の人々がいた。それからイエスは彼らを解散させ、'),
('JPN', '马可福音', 41, 8, 10, 'すぐに弟子たちとともに舟に乗り、ダルマヌタ地方に行かれた。'),
('JPN', '马可福音', 41, 8, 11, 'すると、パリサイ人たちがやって来てイエスと議論を始めた。彼らは天からのしるしを求め、イエスを試みようとしたのである。'),
('JPN', '马可福音', 41, 8, 12, 'イエスは、心の中で深くため息をついて、こう言われた。「この時代はなぜ、しるしを求めるのか。まことに、あなたがたに言います。今の時代には、どんなしるしも与えられません。」'),
('JPN', '马可福音', 41, 8, 13, 'イエスは彼らから離れ、再び舟に乗って向こう岸へ行かれた。'),
('JPN', '马可福音', 41, 8, 14, '弟子たちは、パンを持って来るのを忘れ、一つのパンのほかは、舟の中に持ち合わせがなかった。'),
('JPN', '马可福音', 41, 8, 15, 'そのとき、イエスは彼らに命じられた。「パリサイ人のパン種とヘロデのパン種には、くれぐれも気をつけなさい。」'),
('JPN', '马可福音', 41, 8, 16, 'すると弟子たちは、自分たちがパンを持っていないことについて、互いに議論し始めた。'),
('JPN', '马可福音', 41, 8, 17, 'イエスはそれに気がついて言われた。「なぜ、パンを持っていないことについて議論しているのですか。まだ分からないのですか、悟らないのですか。心を頑なにしているのですか。'),
('JPN', '马可福音', 41, 8, 18, '目があっても見ないのですか。耳があっても聞かないのですか。あなたがたは、覚えていないのですか。'),
('JPN', '马可福音', 41, 8, 19, 'わたしが五千人のために五つのパンを裂いたとき、パン切れを集めて、いくつのかごがいっぱいになりましたか。」彼らは答えた。「十二です。」'),
('JPN', '马可福音', 41, 8, 20, '「四千人のために七つのパンを裂いたときは、パン切れを集めて、いくつのかごがいっぱいになりましたか。」彼らは答えた。「七つです。」'),
('JPN', '马可福音', 41, 8, 21, 'イエスは言われた。「まだ悟らないのですか。」'),
('JPN', '马可福音', 41, 8, 22, '彼らはベツサイダに着いた。すると人々が目の見えない人を連れて来て、彼にさわってくださいとイエスに懇願した。'),
('JPN', '马可福音', 41, 8, 23, 'イエスは、その人の手を取って村の外に連れて行かれた。そして彼の両目に唾をつけ、その上に両手を当てて、「何か見えますか」と聞かれた。'),
('JPN', '马可福音', 41, 8, 24, 'すると、彼は見えるようになって、「人が見えます。木のようですが、歩いているのが見えます」と言った。'),
('JPN', '马可福音', 41, 8, 25, 'それから、イエスは再び両手を彼の両目に当てられた。彼がじっと見ていると、目がすっかり治り、すべてのものがはっきりと見えるようになった。'),
('JPN', '马可福音', 41, 8, 26, 'そこでイエスは、彼を家に帰らせ、「村には入って行かないように」と言われた。'),
('JPN', '马可福音', 41, 8, 27, 'さて、イエスは弟子たちとピリポ・カイサリアの村々に出かけられた。その途中、イエスは弟子たちにお尋ねになった。「人々はわたしをだれだと言っていますか。」'),
('JPN', '马可福音', 41, 8, 28, '彼らは答えた。「バプテスマのヨハネだと言っています。エリヤだと言う人たちや、預言者の一人だと言う人たちもいます。」'),
('JPN', '马可福音', 41, 8, 29, 'するとイエスは、彼らにお尋ねになった。「あなたがたは、わたしをだれだと言いますか。」ペテロがイエスに答えた。「あなたはキリストです。」'),
('JPN', '马可福音', 41, 8, 30, 'するとイエスは、自分のことをだれにも言わないように、彼らを戒められた。'),
('JPN', '马可福音', 41, 8, 31, 'それからイエスは、人の子は多くの苦しみを受け、長老たち、祭司長たち、律法学者たちに捨てられ、殺され、三日後によみがえらなければならないと、弟子たちに教え始められた。'),
('JPN', '马可福音', 41, 8, 32, 'イエスはこのことをはっきりと話された。するとペテロは、イエスをわきにお連れして、いさめ始めた。'),
('JPN', '马可福音', 41, 8, 33, 'しかし、イエスは振り向いて弟子たちを見ながら、ペテロを叱って言われた。「下がれ、サタン。あなたは神のことを思わないで、人のことを思っている。」'),
('JPN', '马可福音', 41, 8, 34, 'それから、群衆を弟子たちと一緒に呼び寄せて、彼らに言われた。「だれでもわたしに従って来たければ、自分を捨て、自分の十字架を負って、わたしに従って来なさい。'),
('JPN', '马可福音', 41, 8, 35, '自分のいのちを救おうと思う者はそれを失い、わたしと福音のためにいのちを失う者は、それを救うのです。'),
('JPN', '马可福音', 41, 8, 36, '人は、たとえ全世界を手に入れても、自分のいのちを失ったら、何の益があるでしょうか。'),
('JPN', '马可福音', 41, 8, 37, '自分のいのちを買い戻すのに、人はいったい何を差し出せばよいのでしょうか。'),
('JPN', '马可福音', 41, 8, 38, 'だれでも、このような姦淫と罪の時代にあって、わたしとわたしのことばを恥じるなら、人の子も、父の栄光を帯びて聖なる御使いたちとともに来るとき、その人を恥じます。」'),
('JPN', '马可福音', 41, 9, 1, 'またイエスは彼らに言われた。「まことに、あなたがたに言います。ここに立っている人たちの中には、神の国が力をもって到来しているのを見るまで、決して死を味わわない人たちがいます。」'),
('JPN', '马可福音', 41, 9, 2, 'それから六日目に、イエスはペテロとヤコブとヨハネだけを連れて、高い山に登られた。すると、彼らの目の前でその御姿が変わった。'),
('JPN', '马可福音', 41, 9, 3, 'その衣は非常に白く輝き、この世の職人には、とてもなし得ないほどの白さであった。'),
('JPN', '马可福音', 41, 9, 4, 'また、エリヤがモーセとともに彼らの前に現れ、イエスと語り合っていた。'),
('JPN', '马可福音', 41, 9, 5, 'ペテロがイエスに言った。「先生。私たちがここにいることはすばらしいことです。幕屋を三つ造りましょう。あなたのために一つ、モーセのために一つ、エリヤのために一つ。」'),
('JPN', '马可福音', 41, 9, 6, 'ペテロは、何を言ったらよいのか分からなかったのである。彼らは恐怖に打たれていた。'),
('JPN', '马可福音', 41, 9, 7, 'そのとき、雲がわき起こって彼らをおおい、雲の中から声がした。「これはわたしの愛する子。彼の言うことを聞け。」'),
('JPN', '马可福音', 41, 9, 8, '彼らが急いであたりを見回すと、自分たちと一緒にいるのはイエスだけで、もはやだれも見えなかった。'),
('JPN', '马可福音', 41, 9, 9, 'さて、山を下りながら、イエスは弟子たちに、人の子が死人の中からよみがえる時までは、今見たことをだれにも話してはならない、と命じられた。'),
('JPN', '马可福音', 41, 9, 10, '彼らはこのことばを胸に納め、死人の中からよみがえると言われたのはどういう意味か、互いに論じ合った。'),
('JPN', '马可福音', 41, 9, 11, 'また弟子たちは、イエスに尋ねた。「なぜ、律法学者たちは、まずエリヤが来るはずだと言っているのですか。」'),
('JPN', '马可福音', 41, 9, 12, 'イエスは彼らに言われた。「エリヤがまず来て、すべてを立て直すのです。それではどうして、人の子について、多くの苦しみを受け、蔑まれると書いてあるのですか。'),
('JPN', '马可福音', 41, 9, 13, 'わたしはあなたがたに言います。エリヤはもう来ています。そして人々は、彼について書かれているとおり、彼に好き勝手なことをしました。」'),
('JPN', '马可福音', 41, 9, 14, 'さて、彼らがほかの弟子たちのところに戻ると、大勢の群衆がその弟子たちを囲んで、律法学者たちが彼らと論じ合っているのが見えた。'),
('JPN', '马可福音', 41, 9, 15, '群衆はみな、すぐにイエスを見つけると非常に驚き、駆け寄って来てあいさつをした。'),
('JPN', '马可福音', 41, 9, 16, 'イエスは彼らに、「あなたがたは弟子たちと何を論じ合っているのですか」とお尋ねになった。'),
('JPN', '马可福音', 41, 9, 17, 'すると群衆の一人が答えた。「先生。口をきけなくする霊につかれた私の息子を、あなたのところに連れて来ました。'),
('JPN', '马可福音', 41, 9, 18, 'その霊が息子に取りつくと、ところかまわず倒します。息子は泡を吹き、歯ぎしりして、からだをこわばらせます。それであなたのお弟子たちに、霊を追い出してくださいとお願いしたのですが、できませんでした。」'),
('JPN', '马可福音', 41, 9, 19, 'イエスは彼らに言われた。「ああ、不信仰な時代だ。いつまで、わたしはあなたがたと一緒にいなければならないのか。いつまで、あなたがたに我慢しなければならないのか。その子をわたしのところに連れて来なさい。」'),
('JPN', '马可福音', 41, 9, 20, 'そこで、人々はその子をイエスのもとに連れて来た。イエスを見ると、霊がすぐ彼に引きつけを起こさせたので、彼は地面に倒れ、泡を吹きながら転げ回った。'),
('JPN', '马可福音', 41, 9, 21, 'イエスは父親にお尋ねになった。「この子にこのようなことが起こるようになってから、どのくらいたちますか。」父親は答えた。「幼い時からです。'),
('JPN', '马可福音', 41, 9, 22, '霊は息子を殺そうとして、何度も火の中や水の中に投げ込みました。しかし、おできになるなら、私たちをあわれんでお助けください。」'),
('JPN', '马可福音', 41, 9, 23, 'イエスは言われた。「できるなら、と言うのですか。信じる者には、どんなことでもできるのです。」'),
('JPN', '马可福音', 41, 9, 24, 'するとすぐに、その子の父親は叫んで言った。「信じます。不信仰な私をお助けください。」'),
('JPN', '马可福音', 41, 9, 25, 'イエスは、群衆が駆け寄って来るのを見ると、汚れた霊を叱って言われた。「口をきけなくし、耳を聞こえなくする霊。わたしはおまえに命じる。この子から出て行け。二度とこの子に入るな。」'),
('JPN', '马可福音', 41, 9, 26, 'すると霊は叫び声をあげ、その子を激しく引きつけさせて出て行った。するとその子が死んだようになったので、多くの人たちは「この子は死んでしまった」と言った。'),
('JPN', '马可福音', 41, 9, 27, 'しかし、イエスが手を取って起こされると、その子は立ち上がった。'),
('JPN', '马可福音', 41, 9, 28, 'イエスが家に入られると、弟子たちがそっと尋ねた。「私たちが霊を追い出せなかったのは、なぜですか。」'),
('JPN', '马可福音', 41, 9, 29, 'すると、イエスは言われた。「この種のものは、祈りによらなければ、何によっても追い出すことができません。」'),
('JPN', '马可福音', 41, 9, 30, 'さて、一行はそこを去り、ガリラヤを通って行った。イエスは、人に知られたくないと思われた。'),
('JPN', '马可福音', 41, 9, 31, 'それは、イエスが弟子たちに教えて「人の子は人々の手に引き渡され、殺される。しかし、殺されて三日後によみがえる」と言っておられたからである。'),
('JPN', '马可福音', 41, 9, 32, 'しかし、弟子たちにはこのことばが理解できなかった。また、イエスに尋ねるのを恐れていた。'),
('JPN', '马可福音', 41, 9, 33, '一行はカペナウムに着いた。イエスは家に入ってから、弟子たちにお尋ねになった。「来る途中、何を論じ合っていたのですか。」'),
('JPN', '马可福音', 41, 9, 34, '彼らは黙っていた。来る途中、だれが一番偉いか論じ合っていたからである。'),
('JPN', '马可福音', 41, 9, 35, 'イエスは腰を下ろすと、十二人を呼んで言われた。「だれでも先頭に立ちたいと思う者は、皆の後になり、皆に仕える者になりなさい。」'),
('JPN', '马可福音', 41, 9, 36, 'それから、イエスは一人の子どもの手を取って、彼らの真ん中に立たせ、腕に抱いて彼らに言われた。'),
('JPN', '马可福音', 41, 9, 37, '「だれでも、このような子どもたちの一人を、わたしの名のゆえに受け入れる人は、わたしを受け入れるのです。また、だれでもわたしを受け入れる人は、わたしではなく、わたしを遣わされた方を受け入れるのです。」'),
('JPN', '马可福音', 41, 9, 38, 'ヨハネがイエスに言った。「先生。あなたの名によって悪霊を追い出している人を見たので、やめさせようとしました。その人が私たちについて来なかったからです。」'),
('JPN', '马可福音', 41, 9, 39, 'しかし、イエスは言われた。「やめさせてはいけません。わたしの名を唱えて力あるわざを行い、そのすぐ後に、わたしを悪く言える人はいません。'),
('JPN', '马可福音', 41, 9, 40, 'わたしたちに反対しない人は、わたしたちの味方です。'),
('JPN', '马可福音', 41, 9, 41, 'まことに、あなたがたに言います。あなたがたがキリストに属する者だということで、あなたがたに一杯の水を飲ませてくれる人は、決して報いを失うことがありません。'),
('JPN', '马可福音', 41, 9, 42, 'また、わたしを信じるこの小さい者たちの一人をつまずかせる者は、むしろ、大きな石臼を首に結び付けられて、海に投げ込まれてしまうほうがよいのです。'),
('JPN', '马可福音', 41, 9, 43, 'もし、あなたの手があなたをつまずかせるなら、それを切り捨てなさい。両手がそろっていて、ゲヘナに、その消えない火の中に落ちるより、片手でいのちに入るほうがよいのです。'),
('JPN', '马可福音', 41, 9, 45, 'もし、あなたの足があなたをつまずかせるなら、それを切り捨てなさい。両足がそろっていてゲヘナに投げ込まれるより、片足でいのちに入るほうがよいのです。'),
('JPN', '马可福音', 41, 9, 47, 'もし、あなたの目があなたをつまずかせるなら、それをえぐり出しなさい。両目がそろっていてゲヘナに投げ込まれるより、片目で神の国に入るほうがよいのです。'),
('JPN', '马可福音', 41, 9, 48, 'ゲヘナでは、彼らを食らううじ虫が尽きることがなく、火も消えることがありません。'),
('JPN', '马可福音', 41, 9, 49, '人はみな、火によって塩気をつけられます。'),
('JPN', '马可福音', 41, 9, 50, '塩は良いものです。しかし、塩に塩気がなくなったら、あなたがたは何によってそれに味をつけるでしょうか。あなたがたは自分自身のうちに塩気を保ち、互いに平和に過ごしなさい。」'),
('JPN', '马可福音', 41, 10, 1, 'イエスは立ち上がり、そこからユダヤ地方とヨルダンの川向こうに行かれた。群衆がまたイエスのもとに集まって来たので、再びいつものように彼らを教え始められた。'),
('JPN', '马可福音', 41, 10, 2, 'すると、パリサイ人たちがやって来て、イエスを試みるために、夫が妻を離縁することは律法にかなっているかどうかと質問した。'),
('JPN', '马可福音', 41, 10, 3, 'イエスは答えられた。「モーセはあなたがたに何と命じていますか。」'),
('JPN', '马可福音', 41, 10, 4, '彼らは言った。「モーセは、離縁状を書いて妻を離縁することを許しました。」'),
('JPN', '马可福音', 41, 10, 5, 'イエスは言われた。「モーセは、あなたがたの心が頑ななので、この戒めをあなたがたに書いたのです。'),
('JPN', '马可福音', 41, 10, 6, 'しかし、創造のはじめから、神は彼らを男と女に造られました。'),
('JPN', '马可福音', 41, 10, 7, '『それゆえ、男は父と母を離れ、その妻と結ばれ、'),
('JPN', '马可福音', 41, 10, 8, 'ふたりは一体となる』のです。ですから、彼らはもはやふたりではなく、一体なのです。'),
('JPN', '马可福音', 41, 10, 9, 'こういうわけで、神が結び合わせたものを、人が引き離してはなりません。」'),
('JPN', '马可福音', 41, 10, 10, '家に入ると、弟子たちは再びこの問題についてイエスに尋ねた。'),
('JPN', '马可福音', 41, 10, 11, 'イエスは彼らに言われた。「だれでも、自分の妻を離縁し、別の女を妻にする者は、妻に対して姦淫を犯すのです。'),
('JPN', '马可福音', 41, 10, 12, '妻も、夫を離縁して別の男に嫁ぐなら、姦淫を犯すのです。」'),
('JPN', '马可福音', 41, 10, 13, 'さて、イエスに触れていただこうと、人々が子どもたちを連れて来た。ところが弟子たちは彼らを叱った。'),
('JPN', '马可福音', 41, 10, 14, 'イエスはそれを見て、憤って弟子たちに言われた。「子どもたちを、わたしのところに来させなさい。邪魔してはいけません。神の国はこのような者たちのものなのです。'),
('JPN', '马可福音', 41, 10, 15, 'まことに、あなたがたに言います。子どものように神の国を受け入れる者でなければ、決してそこに入ることはできません。」'),
('JPN', '马可福音', 41, 10, 16, 'そしてイエスは子どもたちを抱き、彼らの上に手を置いて祝福された。'),
('JPN', '马可福音', 41, 10, 17, 'イエスが道に出て行かれると、一人の人が駆け寄り、御前にひざまずいて尋ねた。「良い先生。永遠のいのちを受け継ぐためには、何をしたらよいでしょうか。」'),
('JPN', '马可福音', 41, 10, 18, 'イエスは彼に言われた。「なぜ、わたしを『良い』と言うのですか。良い方は神おひとりのほか、だれもいません。'),
('JPN', '马可福音', 41, 10, 19, '戒めはあなたも知っているはずです。『殺してはならない。姦淫してはならない。盗んではならない。偽りの証言をしてはならない。だまし取ってはならない。あなたの父と母を敬え。』」'),
('JPN', '马可福音', 41, 10, 20, 'その人はイエスに言った。「先生。私は少年のころから、それらすべてを守ってきました。」'),
('JPN', '马可福音', 41, 10, 21, 'イエスは彼を見つめ、いつくしんで言われた。「あなたに欠けていることが一つあります。帰って、あなたが持っている物をすべて売り払い、貧しい人たちに与えなさい。そうすれば、あなたは天に宝を持つことになります。そのうえで、わたしに従って来なさい。」'),
('JPN', '马可福音', 41, 10, 22, 'すると彼は、このことばに顔を曇らせ、悲しみながら立ち去った。多くの財産を持っていたからである。'),
('JPN', '马可福音', 41, 10, 23, 'イエスは、周囲を見回して、弟子たちに言われた。「富を持つ者が神の国に入るのは、なんと難しいことでしょう。」'),
('JPN', '马可福音', 41, 10, 24, '弟子たちはイエスのことばに驚いた。しかし、イエスは重ねて彼らに言われた。「子たちよ。神の国に入ることは、なんと難しいことでしょう。'),
('JPN', '马可福音', 41, 10, 25, '金持ちが神の国に入るよりは、らくだが針の穴を通るほうが易しいのです。」'),
('JPN', '马可福音', 41, 10, 26, '弟子たちは、ますます驚いて互いに言った。「それでは、だれが救われることができるでしょう。」'),
('JPN', '马可福音', 41, 10, 27, 'イエスは彼らをじっと見て言われた。「それは人にはできないことです。しかし、神は違います。神にはどんなことでもできるのです。」'),
('JPN', '马可福音', 41, 10, 28, 'ペテロがイエスにこう言い出した。「ご覧ください。私たちはすべてを捨てて、あなたに従って来ました。」'),
('JPN', '马可福音', 41, 10, 29, 'イエスは言われた。「まことに、あなたがたに言います。わたしのために、また福音のために、家、兄弟、姉妹、母、父、子ども、畑を捨てた者は、'),
('JPN', '马可福音', 41, 10, 30, '今この世で、迫害とともに、家、兄弟、姉妹、母、子ども、畑を百倍受け、来たるべき世で永遠のいのちを受けます。'),
('JPN', '马可福音', 41, 10, 31, 'しかし、先にいる多くの者が後になり、後にいる多くの者が先になります。」'),
('JPN', '马可福音', 41, 10, 32, 'さて、一行はエルサレムに上る途上にあった。イエスは弟子たちの先に立って行かれた。弟子たちは驚き、ついて行く人たちは恐れを覚えた。すると、イエスは再び十二人をそばに呼んで、ご自分に起ころうとしていることを話し始められた。'),
('JPN', '马可福音', 41, 10, 33, '「ご覧なさい。わたしたちはエルサレムに上って行きます。そして、人の子は、祭司長たちや律法学者たちに引き渡されます。彼らは人の子を死刑に定め、異邦人に引き渡します。'),
('JPN', '马可福音', 41, 10, 34, '異邦人は人の子を嘲り、唾をかけ、むちで打ち、殺します。しかし、人の子は三日後によみがえります。」'),
('JPN', '马可福音', 41, 10, 35, 'ゼベダイの息子たち、ヤコブとヨハネが、イエスのところに来て言った。「先生。私たちが願うことをかなえていただきたいのです。」'),
('JPN', '马可福音', 41, 10, 36, 'イエスは彼らに言われた。「何をしてほしいのですか。」'),
('JPN', '马可福音', 41, 10, 37, '彼らは言った。「あなたが栄光をお受けになるとき、一人があなたの右に、もう一人が左に座るようにしてください。」'),
('JPN', '马可福音', 41, 10, 38, 'しかし、イエスは彼らに言われた。「あなたがたは、自分が何を求めているのか分かっていません。わたしが飲む杯を飲み、わたしが受けるバプテスマを受けることができますか。」'),
('JPN', '马可福音', 41, 10, 39, '彼らは「できます」と言った。そこで、イエスは言われた。「確かにあなたがたは、わたしが飲む杯を飲み、わたしが受けるバプテスマを受けることになります。'),
('JPN', '马可福音', 41, 10, 40, 'しかし、わたしの右と左に座ることは、わたしが許すことではありません。それは備えられた人たちに与えられるのです。」'),
('JPN', '马可福音', 41, 10, 41, 'ほかの十人はこれを聞いて、ヤコブとヨハネに腹を立て始めた。'),
('JPN', '马可福音', 41, 10, 42, 'そこで、イエスは彼らを呼び寄せて言われた。「あなたがたも知っているとおり、異邦人の支配者と認められている者たちは、人々に対して横柄にふるまい、偉い人たちは人々の上に権力をふるっています。'),
('JPN', '马可福音', 41, 10, 43, 'しかし、あなたがたの間では、そうであってはなりません。あなたがたの間で偉くなりたいと思う者は、皆に仕える者になりなさい。'),
('JPN', '马可福音', 41, 10, 44, 'あなたがたの間で先頭に立ちたいと思う者は、皆のしもべになりなさい。'),
('JPN', '马可福音', 41, 10, 45, '人の子も、仕えられるためではなく仕えるために、また多くの人のための贖いの代価として、自分のいのちを与えるために来たのです。」'),
('JPN', '马可福音', 41, 10, 46, 'さて、一行はエリコに着いた。そしてイエスが、弟子たちや多くの群衆と一緒にエリコを出て行かれると、ティマイの子のバルティマイという目の見えない物乞いが、道端に座っていた。'),
('JPN', '马可福音', 41, 10, 47, '彼は、ナザレのイエスがおられると聞いて、「ダビデの子のイエス様、私をあわれんでください」と叫び始めた。'),
('JPN', '马可福音', 41, 10, 48, '多くの人たちが彼を黙らせようとたしなめたが、「ダビデの子よ、私をあわれんでください」と、ますます叫んだ。'),
('JPN', '马可福音', 41, 10, 49, 'イエスは立ち止まって、「あの人を呼んで来なさい」と言われた。そこで、彼らはその目の見えない人を呼んで、「心配しないでよい。さあ、立ちなさい。あなたを呼んでおられる」と言った。'),
('JPN', '马可福音', 41, 10, 50, 'その人は上着を脱ぎ捨て、躍り上がってイエスのところに来た。'),
('JPN', '马可福音', 41, 10, 51, 'イエスは彼に言われた。「わたしに何をしてほしいのですか。」すると、その目の見えない人は言った。「先生、目が見えるようにしてください。」'),
('JPN', '马可福音', 41, 10, 52, 'そこでイエスは言われた。「さあ、行きなさい。あなたの信仰があなたを救いました。」すると、すぐに彼は見えるようになり、道を進むイエスについて行った。'),
('JPN', '马可福音', 41, 11, 1, 'さて、一行がエルサレムに近づき、オリーブ山のふもとのベテパゲとベタニアに来たとき、イエスはこう言って二人の弟子を遣わされた。'),
('JPN', '马可福音', 41, 11, 2, '「向こうの村へ行きなさい。村に入るとすぐ、まだだれも乗ったことのない子ろばが、つながれているのに気がつくでしょう。それをほどいて、引いて来なさい。'),
('JPN', '马可福音', 41, 11, 3, 'もしだれかが、『なぜそんなことをするのか』と言ったら、『主がお入り用なのです。すぐに、またここにお返しします』と言いなさい。」'),
('JPN', '马可福音', 41, 11, 4, '弟子たちは出かけて行き、表通りにある家の戸口に、子ろばがつながれているのを見つけたので、それをほどいた。'),
('JPN', '马可福音', 41, 11, 5, 'すると、そこに立っていた何人かが言った。「子ろばをほどいたりして、どうするのか。」'),
('JPN', '马可福音', 41, 11, 6, '弟子たちが、イエスの言われたとおりに話すと、彼らは許してくれた。'),
('JPN', '马可福音', 41, 11, 7, 'それで、子ろばをイエスのところに引いて行き、自分たちの上着をその上に掛けた。イエスはそれに乗られた。'),
('JPN', '马可福音', 41, 11, 8, 'すると、多くの人たちが自分たちの上着を道に敷き、ほかの人たちは葉の付いた枝を野から切って来て敷いた。'),
('JPN', '马可福音', 41, 11, 9, 'そして、前を行く人たちも、後に続く人たちも叫んだ。「ホサナ。祝福あれ、主の御名によって来られる方に。'),
('JPN', '马可福音', 41, 11, 10, '祝福あれ、われらの父ダビデの、来たるべき国に。ホサナ、いと高き所に。」'),
('JPN', '马可福音', 41, 11, 11, 'こうしてイエスはエルサレムに着き、宮に入られた。そして、すべてを見て回った後、すでに夕方になっていたので、十二人と一緒にベタニアに出て行かれた。'),
('JPN', '马可福音', 41, 11, 12, '翌日、彼らがベタニアを出たとき、イエスは空腹を覚えられた。'),
('JPN', '马可福音', 41, 11, 13, '葉の茂ったいちじくの木が遠くに見えたので、その木に何かあるかどうか見に行かれたが、そこに来てみると、葉のほかには何も見つからなかった。いちじくのなる季節ではなかったからである。'),
('JPN', '马可福音', 41, 11, 14, 'するとイエスは、その木に向かって言われた。「今後いつまでも、だれもおまえの実を食べることがないように。」弟子たちはこれを聞いていた。'),
('JPN', '马可福音', 41, 11, 15, 'こうして彼らはエルサレムに着いた。イエスは宮に入り、その中で売り買いしている者たちを追い出し始め、両替人の台や、鳩を売る者たちの腰掛けを倒された。'),
('JPN', '马可福音', 41, 11, 16, 'また、だれにも、宮を通って物を運ぶことをお許しにならなかった。'),
('JPN', '马可福音', 41, 11, 17, 'そして、人々に教えて言われた。「『わたしの家は、あらゆる民の祈りの家と呼ばれる』と書いてあるではないか。それなのに、おまえたちはそれを『強盗の巣』にしてしまった。」'),
('JPN', '马可福音', 41, 11, 18, '祭司長たちや律法学者たちはこれを聞いて、どのようにしてイエスを殺そうかと相談した。群衆がみなその教えに驚嘆していたため、彼らはイエスを恐れていたのである。'),
('JPN', '马可福音', 41, 11, 19, '夕方になると、イエスと弟子たちは都の外に出て行った。'),
('JPN', '马可福音', 41, 11, 20, 'さて、朝早く、彼らが通りがかりにいちじくの木を見ると、それは根元から枯れていた。'),
('JPN', '马可福音', 41, 11, 21, 'ペテロは思い出して、イエスに言った。「先生、ご覧ください。あなたがのろわれた、いちじくの木が枯れています。」'),
('JPN', '马可福音', 41, 11, 22, 'イエスは弟子たちに答えられた。「神を信じなさい。'),
('JPN', '马可福音', 41, 11, 23, 'まことに、あなたがたに言います。この山に向かい、『立ち上がって、海に入れ』と言い、心の中で疑わずに、自分の言ったとおりになると信じる者には、そのとおりになります。'),
('JPN', '马可福音', 41, 11, 24, 'ですから、あなたがたに言います。あなたがたが祈り求めるものは何でも、すでに得たと信じなさい。そうすれば、そのとおりになります。'),
('JPN', '马可福音', 41, 11, 25, 'また、祈るために立ち上がるとき、だれかに対し恨んでいることがあるなら、赦しなさい。そうすれば、天におられるあなたがたの父も、あなたがたの過ちを赦してくださいます。」'),
('JPN', '马可福音', 41, 11, 27, '彼らは再びエルサレムに来た。イエスが宮の中を歩いておられると、祭司長たち、律法学者たち、長老たちがやって来て、'),
('JPN', '马可福音', 41, 11, 28, 'こう言った。「何の権威によって、これらのことをしているのですか。だれがあなたに、これらのことをする権威を授けたのですか。」'),
('JPN', '马可福音', 41, 11, 29, 'イエスは彼らに言われた。「わたしも一言尋ねましょう。それに答えなさい。そうしたら、何の権威によってこれらのことをしているのか、わたしも言いましょう。'),
('JPN', '马可福音', 41, 11, 30, 'ヨハネのバプテスマは、天から来たのですか、それとも人から出たのですか。わたしに答えなさい。」'),
('JPN', '马可福音', 41, 11, 31, 'すると、彼らは論じ合った。「もし、天から来たと言えば、それならなぜ、ヨハネを信じなかったのかと言うだろう。'),
('JPN', '马可福音', 41, 11, 32, 'だが、人から出たと言えば──。」彼らは群衆を恐れていた。人々がみな、ヨハネは確かに預言者だと思っていたからである。'),
('JPN', '马可福音', 41, 11, 33, 'そこで、彼らはイエスに、「分かりません」と答えた。するとイエスは彼らに言われた。「わたしも、何の権威によってこれらのことをするのか、あなたがたに言いません。」'),
('JPN', '马可福音', 41, 12, 1, 'それからイエスは、たとえで彼らに話し始められた。「ある人がぶどう園を造った。垣根を巡らし、踏み場を掘り、見張りやぐらを建て、それを農夫たちに貸して旅に出た。'),
('JPN', '马可福音', 41, 12, 2, '収穫の時になったので、ぶどう園の収穫の一部を受け取るため、農夫たちのところにしもべを遣わした。'),
('JPN', '马可福音', 41, 12, 3, 'ところが、彼らはそのしもべを捕らえて打ちたたき、何も持たせないで送り返した。'),
('JPN', '马可福音', 41, 12, 4, 'そこで、主人は再び別のしもべを遣わしたが、農夫たちはその頭を殴り、辱めた。'),
('JPN', '马可福音', 41, 12, 5, 'また別のしもべを遣わしたが、これを殺してしまった。さらに、多くのしもべを遣わしたが、打ちたたいたり、殺したりした。'),
('JPN', '马可福音', 41, 12, 6, 'しかし、主人にはもう一人、愛する息子がいた。彼は『私の息子なら敬ってくれるだろう』と言って、最後に、息子を彼らのところに遣わした。'),
('JPN', '马可福音', 41, 12, 7, 'すると、農夫たちは話し合った。『あれは跡取りだ。さあ、殺してしまおう。そうすれば、相続財産は自分たちのものになる。』'),
('JPN', '马可福音', 41, 12, 8, 'そして、彼を捕らえて殺し、ぶどう園の外に投げ捨てた。'),
('JPN', '马可福音', 41, 12, 9, 'ぶどう園の主人はどうするでしょうか。やって来て、農夫たちを殺し、ぶどう園をほかの人たちに与えるでしょう。'),
('JPN', '马可福音', 41, 12, 10, 'あなたがたは、次の聖書のことばを読んだことがないのですか。『家を建てる者たちが捨てた石、それが要の石となった。'),
('JPN', '马可福音', 41, 12, 11, 'これは主がなさったこと。私たちの目には不思議なことだ。』」'),
('JPN', '马可福音', 41, 12, 12, '彼らは、このたとえ話が自分たちを指して語られたことに気づいたので、イエスを捕らえようと思ったが、群衆を恐れた。それでイエスを残して立ち去った。'),
('JPN', '马可福音', 41, 12, 13, 'さて、彼らはイエスのことばじりをとらえようとして、パリサイ人とヘロデ党の者を数人、イエスのところに遣わした。'),
('JPN', '马可福音', 41, 12, 14, 'その人たちはやって来てイエスに言った。「先生。私たちは、あなたが真実な方で、だれにも遠慮しない方だと知っております。人の顔色を見ず、真理に基づいて神の道を教えておられるからです。ところで、カエサルに税金を納めることは、律法にかなっているでしょうか、いないでしょうか。納めるべきでしょうか、納めるべきでないでしょうか。」'),
('JPN', '马可福音', 41, 12, 15, 'イエスは彼らの欺瞞を見抜いて言われた。「なぜわたしを試すのですか。デナリ銀貨を持って来て見せなさい。」'),
('JPN', '马可福音', 41, 12, 16, '彼らが持って来ると、イエスは言われた。「これは、だれの肖像と銘ですか。」彼らは、「カエサルのです」と言った。'),
('JPN', '马可福音', 41, 12, 17, 'するとイエスは言われた。「カエサルのものはカエサルに、神のものは神に返しなさい。」彼らはイエスのことばに驚嘆した。'),
('JPN', '马可福音', 41, 12, 18, 'また、復活はないと言っているサドカイ人たちが、イエスのところに来て質問した。'),
('JPN', '马可福音', 41, 12, 19, '「先生、モーセは私たちのためにこう書いています。『もし、ある人の兄が死んで妻を後に残し、子を残さなかった場合、その弟が兄嫁を妻にして、兄のために子孫を起こさなければならない。』'),
('JPN', '马可福音', 41, 12, 20, 'さて、七人の兄弟がいました。長男が妻を迎えましたが、死んで子孫を残しませんでした。'),
('JPN', '马可福音', 41, 12, 21, '次男が兄嫁を妻にしましたが、やはり死んで子孫を残しませんでした。三男も同様でした。'),
('JPN', '马可福音', 41, 12, 22, 'こうして、七人とも子孫を残しませんでした。最後に、その妻も死にました。'),
('JPN', '马可福音', 41, 12, 23, '復活の際、彼らがよみがえるとき、彼女は彼らのうちのだれの妻になるのでしょうか。七人とも彼女を妻にしたのですが。」'),
('JPN', '马可福音', 41, 12, 24, 'イエスは彼らに言われた。「あなたがたは、聖書も神の力も知らないので、そのために思い違いをしているのではありませんか。'),
('JPN', '马可福音', 41, 12, 25, '死人の中からよみがえるときには、人はめとることも嫁ぐこともなく、天の御使いたちのようです。'),
('JPN', '马可福音', 41, 12, 26, '死人がよみがえることについては、モーセの書にある柴の箇所で、神がモーセにどう語られたか、あなたがたは読んだことがないのですか。『わたしはアブラハムの神、イサクの神、ヤコブの神である』とあります。'),
('JPN', '马可福音', 41, 12, 27, '神は死んだ者の神ではなく、生きている者の神です。あなたがたは大変な思い違いをしています。」'),
('JPN', '马可福音', 41, 12, 28, '律法学者の一人が来て、彼らが議論するのを聞いていたが、イエスが見事に答えられたのを見て、イエスに尋ねた。「すべての中で、どれが第一の戒めですか。」'),
('JPN', '马可福音', 41, 12, 29, 'イエスは答えられた。「第一の戒めはこれです。『聞け、イスラエルよ。主は私たちの神。主は唯一である。'),
('JPN', '马可福音', 41, 12, 30, 'あなたは心を尽くし、いのちを尽くし、知性を尽くし、力を尽くして、あなたの神、主を愛しなさい。』'),
('JPN', '马可福音', 41, 12, 31, '第二の戒めはこれです。『あなたの隣人を自分自身のように愛しなさい。』これらよりも重要な命令は、ほかにありません。」'),
('JPN', '马可福音', 41, 12, 32, '律法学者はイエスに言った。「先生、そのとおりです。主は唯一であって、そのほかに主はいない、とあなたが言われたことは、まさにそのとおりです。'),
('JPN', '马可福音', 41, 12, 33, 'そして、心を尽くし、知恵を尽くし、力を尽くして主を愛すること、また、隣人を自分自身のように愛することは、どんな全焼のささげ物やいけにえよりもはるかにすぐれています。」'),
('JPN', '马可福音', 41, 12, 34, 'イエスは、彼が賢く答えたのを見て言われた。「あなたは神の国から遠くない。」それから後は、だれもイエスにあえて尋ねる者はいなかった。'),
('JPN', '马可福音', 41, 12, 35, 'イエスは宮で教えていたとき、こう言われた。「どうして律法学者たちは、キリストをダビデの子だと言うのですか。'),
('JPN', '马可福音', 41, 12, 36, 'ダビデ自身が、聖霊によって、こう言っています。『主は、私の主に言われた。「あなたは、わたしの右の座に着いていなさい。わたしがあなたの敵をあなたの足台とするまで。」』'),
('JPN', '马可福音', 41, 12, 37, 'ダビデ自身がキリストを主と呼んでいるのに、どうしてキリストがダビデの子なのでしょう。」大勢の群衆が、イエスの言われることを喜んで聞いていた。'),
('JPN', '马可福音', 41, 12, 38, 'イエスはその教えの中でこう言われた。「律法学者たちに気をつけなさい。彼らが願うのは、長い衣を着て歩き回ること、広場であいさつされること、'),
('JPN', '马可福音', 41, 12, 39, '会堂で上席に、宴会で上座に座ることです。'),
('JPN', '马可福音', 41, 12, 40, 'また、やもめたちの家を食い尽くし、見栄を張って長く祈ります。こういう人たちは、より厳しい罰を受けます。」'),
('JPN', '马可福音', 41, 12, 41, 'それから、イエスは献金箱の向かい側に座り、群衆がお金を献金箱へ投げ入れる様子を見ておられた。多くの金持ちがたくさん投げ入れていた。'),
('JPN', '马可福音', 41, 12, 42, 'そこに一人の貧しいやもめが来て、レプタ銅貨二枚を投げ入れた。それは一コドラントに当たる。'),
('JPN', '马可福音', 41, 12, 43, 'イエスは弟子たちを呼んで言われた。「まことに、あなたがたに言います。この貧しいやもめは、献金箱に投げ入れている人々の中で、だれよりも多くを投げ入れました。'),
('JPN', '马可福音', 41, 12, 44, '皆はあり余る中から投げ入れたのに、この人は乏しい中から、持っているすべてを、生きる手立てのすべてを投げ入れたのですから。」'),
('JPN', '马可福音', 41, 13, 1, 'イエスが宮から出て行かれるとき、弟子の一人がイエスに言った。「先生、ご覧ください。なんとすばらしい石、なんとすばらしい建物でしょう。」'),
('JPN', '马可福音', 41, 13, 2, 'すると、イエスは彼に言われた。「この大きな建物を見ているのですか。ここで、どの石も崩されずに、ほかの石の上に残ることは決してありません。」'),
('JPN', '马可福音', 41, 13, 3, 'イエスがオリーブ山で宮に向かって座っておられると、ペテロ、ヤコブ、ヨハネ、アンデレが、ひそかにイエスに尋ねた。'),
('JPN', '马可福音', 41, 13, 4, '「お話しください。いつ、そのようなことが起こるのですか。また、それらがすべて終わりに近づくときのしるしは、どのようなものですか。」'),
('JPN', '马可福音', 41, 13, 5, 'それで、イエスは彼らに話し始められた。「人に惑わされないように気をつけなさい。'),
('JPN', '马可福音', 41, 13, 6, 'わたしの名を名乗る者が大勢現れ、『私こそ、その者だ』と言って、多くの人を惑わします。'),
('JPN', '马可福音', 41, 13, 7, 'また、戦争や戦争のうわさを聞いても、うろたえてはいけません。そういうことは必ず起こりますが、まだ終わりではありません。'),
('JPN', '马可福音', 41, 13, 8, '民族は民族に、国は国に敵対して立ち上がり、あちこちで地震があり、飢饉も起こるからです。これらのことは産みの苦しみの始まりです。'),
('JPN', '马可福音', 41, 13, 9, 'あなたがたは用心していなさい。人々はあなたがたを地方法院に引き渡します。あなたがたは、会堂で打ちたたかれ、わたしのために、総督たちや王たちの前に立たされます。そのようにして彼らに証しするのです。'),
('JPN', '马可福音', 41, 13, 10, 'まず福音が、すべての民族に宣べ伝えられなければなりません。'),
('JPN', '马可福音', 41, 13, 11, '人々があなたがたを捕らえて引き渡すとき、何を話そうかと、前もって心配するのはやめなさい。ただ、そのときあなたがたに与えられることを話しなさい。話すのはあなたがたではなく、聖霊です。'),
('JPN', '马可福音', 41, 13, 12, 'また、兄弟は兄弟を、父は子を死に渡し、子どもたちは両親に逆らって立ち、死に至らせます。'),
('JPN', '马可福音', 41, 13, 13, 'また、わたしの名のために、あなたがたはすべての人に憎まれます。しかし、最後まで耐え忍ぶ人は救われます。'),
('JPN', '马可福音', 41, 13, 14, '『荒らす忌まわしいもの』が、立ってはならない所に立っているのを見たら──読者はよく理解せよ──ユダヤにいる人たちは山へ逃げなさい。'),
('JPN', '马可福音', 41, 13, 15, '屋上にいる人は、家から何かを持ち出そうと、下に降りたり、中に入ったりしてはいけません。'),
('JPN', '马可福音', 41, 13, 16, '畑にいる人は、上着を取りに戻ってはいけません。'),
('JPN', '马可福音', 41, 13, 17, 'それらの日、身重の女たちと乳飲み子を持つ女たちは哀れです。'),
('JPN', '马可福音', 41, 13, 18, 'このことが冬に起こらないように祈りなさい。'),
('JPN', '马可福音', 41, 13, 19, 'それらの日には、神が創造された被造世界のはじめから今に至るまでなかったような、また、今後も決してないような苦難が起こるからです。'),
('JPN', '马可福音', 41, 13, 20, 'もし主が、その日数を少なくしてくださらなかったら、一人も救われないでしょう。しかし、主は、ご自分が選んだ人たちのために、その日数を少なくしてくださいました。'),
('JPN', '马可福音', 41, 13, 21, 'そのときに、だれかが、『ご覧なさい。ここにキリストがいる』とか、『あそこにいる』とか言っても、信じてはいけません。'),
('JPN', '马可福音', 41, 13, 22, '偽キリストたち、偽預言者たちが現れて、できれば選ばれた者たちを惑わそうと、しるしや不思議を行います。'),
('JPN', '马可福音', 41, 13, 23, 'あなたがたは、気をつけていなさい。わたしは、すべてのことを前もって話しました。'),
('JPN', '马可福音', 41, 13, 24, 'しかしその日、これらの苦難に続いて、太陽は暗くなり、月は光を放たなくなり、'),
('JPN', '马可福音', 41, 13, 25, '星は天から落ち、天にあるもろもろの力は揺り動かされます。'),
('JPN', '马可福音', 41, 13, 26, 'そのとき人々は、人の子が雲のうちに、偉大な力と栄光とともに来るのを見ます。'),
('JPN', '马可福音', 41, 13, 27, 'そのとき、人の子は御使いたちを遣わし、地の果てから天の果てまで、選ばれた者たちを四方から集めます。'),
('JPN', '马可福音', 41, 13, 28, 'いちじくの木から教訓を学びなさい。枝が柔らかくなって葉が出て来ると、夏が近いことが分かります。'),
('JPN', '马可福音', 41, 13, 29, '同じように、これらのことが起こるのを見たら、あなたがたは、人の子が戸口まで近づいていることを知りなさい。'),
('JPN', '马可福音', 41, 13, 30, 'まことに、あなたがたに言います。これらのことがすべて起こるまでは、この時代が過ぎ去ることは決してありません。'),
('JPN', '马可福音', 41, 13, 31, '天地は消え去ります。しかし、わたしのことばは決して消え去ることがありません。'),
('JPN', '马可福音', 41, 13, 32, 'ただし、その日、その時がいつなのかは、だれも知りません。天の御使いたちも子も知りません。父だけが知っておられます。'),
('JPN', '马可福音', 41, 13, 33, '気をつけて、目を覚ましていなさい。その時がいつなのか、あなたがたは知らないからです。'),
('JPN', '马可福音', 41, 13, 34, 'それはちょうど、旅に出る人のようです。家を離れるとき、しもべたちそれぞれに、仕事を割り当てて責任を持たせ、門番には目を覚ましているように命じます。'),
('JPN', '马可福音', 41, 13, 35, 'ですから、目を覚ましていなさい。家の主人がいつ帰って来るのか、夕方なのか、夜中なのか、鶏の鳴くころなのか、明け方なのか、分からないからです。'),
('JPN', '马可福音', 41, 13, 36, '主人が突然帰って来て、あなたがたが眠っているのを見ることがないようにしなさい。'),
('JPN', '马可福音', 41, 13, 37, 'わたしがあなたがたに言っていることは、すべての人に言っているのです。目を覚ましていなさい。」'),
('JPN', '马可福音', 41, 14, 1, '過越の祭り、すなわち種なしパンの祭りが二日後に迫っていた。祭司長たちと律法学者たちは、イエスをだまして捕らえ、殺すための良い方法を探していた。'),
('JPN', '马可福音', 41, 14, 2, '彼らは、「祭りの間はやめておこう。民が騒ぎを起こすといけない」と話していた。'),
('JPN', '马可福音', 41, 14, 3, 'さて、イエスがベタニアで、ツァラアトに冒された人シモンの家におられたときのことである。食事をしておられると、ある女の人が、純粋で非常に高価なナルド油の入った小さな壺を持って来て、その壺を割り、イエスの頭に注いだ。'),
('JPN', '马可福音', 41, 14, 4, 'すると、何人かの者が憤慨して互いに言った。「何のために、香油をこんなに無駄にしたのか。'),
('JPN', '马可福音', 41, 14, 5, 'この香油なら、三百デナリ以上に売れて、貧しい人たちに施しができたのに。」そして、彼女を厳しく責めた。'),
('JPN', '马可福音', 41, 14, 6, 'すると、イエスは言われた。「彼女を、するままにさせておきなさい。なぜ困らせるのですか。わたしのために、良いことをしてくれたのです。'),
('JPN', '马可福音', 41, 14, 7, '貧しい人々は、いつもあなたがたと一緒にいます。あなたがたは望むとき、いつでも彼らに良いことをしてあげられます。しかし、わたしは、いつもあなたがたと一緒にいるわけではありません。'),
('JPN', '马可福音', 41, 14, 8, '彼女は、自分にできることをしたのです。埋葬に備えて、わたしのからだに、前もって香油を塗ってくれました。'),
('JPN', '马可福音', 41, 14, 9, 'まことに、あなたがたに言います。世界中どこでも、福音が宣べ伝えられるところでは、この人がしたことも、この人の記念として語られます。」'),
('JPN', '马可福音', 41, 14, 10, 'さて、十二人の一人であるイスカリオテのユダは、祭司長たちのところへ行った。イエスを引き渡すためであった。'),
('JPN', '马可福音', 41, 14, 11, '彼らはそれを聞いて喜び、金を与える約束をした。そこでユダは、どうすればイエスをうまく引き渡せるかと、その機をうかがっていた。'),
('JPN', '马可福音', 41, 14, 12, '種なしパンの祭りの最初の日、すなわち、過越の子羊を屠る日、弟子たちはイエスに言った。「過越の食事ができるように、私たちは、どこへ行って用意をしましょうか。」'),
('JPN', '马可福音', 41, 14, 13, 'イエスは、こう言って弟子のうち二人を遣わされた。「都に入りなさい。すると、水がめを運んでいる人に出会います。その人について行きなさい。'),
('JPN', '马可福音', 41, 14, 14, 'そして、彼が入って行く家の主人に、『弟子たちと一緒に過越の食事をする、わたしの客間はどこかと先生が言っております』と言いなさい。'),
('JPN', '马可福音', 41, 14, 15, 'すると、その主人自ら、席が整えられて用意のできた二階の大広間を見せてくれます。そこでわたしたちのために用意をしなさい。」'),
('JPN', '马可福音', 41, 14, 16, '弟子たちが出かけて行って都に入ると、イエスが彼らに言われたとおりであった。それで、彼らは過越の用意をした。'),
('JPN', '马可福音', 41, 14, 17, '夕方になって、イエスは十二人と一緒にそこに来られた。'),
('JPN', '马可福音', 41, 14, 18, 'そして、彼らが席に着いて食事をしているとき、イエスは言われた。「まことに、あなたがたに言います。あなたがたのうちの一人で、わたしと一緒に食事をしている者が、わたしを裏切ります。」'),
('JPN', '马可福音', 41, 14, 19, '弟子たちは悲しくなり、次々にイエスに言い始めた。「まさか私ではないでしょう。」'),
('JPN', '马可福音', 41, 14, 20, 'イエスは言われた。「十二人の一人で、わたしと一緒に手を鉢に浸している者です。'),
('JPN', '马可福音', 41, 14, 21, '人の子は、自分について書かれているとおり、去って行きます。しかし、人の子を裏切るその人はわざわいです。そういう人は、生まれて来なければよかったのです。」'),
('JPN', '马可福音', 41, 14, 22, 'さて、一同が食事をしているとき、イエスはパンを取り、神をほめたたえてこれを裂き、弟子たちに与えて言われた。「取りなさい。これはわたしのからだです。」'),
('JPN', '马可福音', 41, 14, 23, 'また、杯を取り、感謝の祈りをささげた後、彼らにお与えになった。彼らはみなその杯から飲んだ。'),
('JPN', '马可福音', 41, 14, 24, 'イエスは彼らに言われた。「これは、多くの人のために流される、わたしの契約の血です。'),
('JPN', '马可福音', 41, 14, 25, 'まことに、あなたがたに言います。神の国で新しく飲むその日まで、わたしがぶどうの実からできた物を飲むことは、もはや決してありません。」'),
('JPN', '马可福音', 41, 14, 26, 'そして、賛美の歌を歌ってから、皆でオリーブ山へ出かけた。'),
('JPN', '马可福音', 41, 14, 27, 'イエスは弟子たちに言われた。「あなたがたはみな、つまずきます。『わたしは羊飼いを打つ。すると、羊は散らされる』と書いてあるからです。'),
('JPN', '马可福音', 41, 14, 28, 'しかしわたしは、よみがえった後、あなたがたより先にガリラヤへ行きます。」'),
('JPN', '马可福音', 41, 14, 29, 'すると、ペテロがイエスに言った。「たとえ皆がつまずいても、私はつまずきません。」'),
('JPN', '马可福音', 41, 14, 30, 'イエスは彼に言われた。「まことに、あなたに言います。まさに今夜、鶏が二度鳴く前に、あなたは三度わたしを知らないと言います。」'),
('JPN', '马可福音', 41, 14, 31, 'ペテロは力を込めて言い張った。「たとえ、ご一緒に死ななければならないとしても、あなたを知らないなどとは決して申しません。」皆も同じように言った。'),
('JPN', '马可福音', 41, 14, 32, 'さて、彼らはゲツセマネという場所に来た。イエスは弟子たちに言われた。「わたしが祈っている間、ここに座っていなさい。」'),
('JPN', '马可福音', 41, 14, 33, 'そして、ペテロ、ヤコブ、ヨハネを一緒に連れて行かれた。イエスは深く悩み、もだえ始め、'),
('JPN', '马可福音', 41, 14, 34, '彼らに言われた。「わたしは悲しみのあまり死ぬほどです。ここにいて、目を覚ましていなさい。」'),
('JPN', '马可福音', 41, 14, 35, 'それからイエスは少し進んで行って、地面にひれ伏し、できることなら、この時が自分から過ぎ去るようにと祈られた。'),
('JPN', '马可福音', 41, 14, 36, 'そしてこう言われた。「アバ、父よ、あなたは何でもおできになります。どうか、この杯をわたしから取り去ってください。しかし、わたしの望むことではなく、あなたがお望みになることが行われますように。」'),
('JPN', '马可福音', 41, 14, 37, 'イエスは戻り、彼らが眠っているのを見て、ペテロに言われた。「シモン、眠っているのですか。一時間でも、目を覚ましていられなかったのですか。'),
('JPN', '马可福音', 41, 14, 38, '誘惑に陥らないように、目を覚まして祈っていなさい。霊は燃えていても肉は弱いのです。」'),
('JPN', '马可福音', 41, 14, 39, 'イエスは再び離れて行き、前と同じことばで祈られた。'),
('JPN', '马可福音', 41, 14, 40, 'そして再び戻って来てご覧になると、弟子たちは眠っていた。まぶたがとても重くなっていたのである。彼らは、イエスに何と言ってよいか、分からなかった。'),
('JPN', '马可福音', 41, 14, 41, 'イエスは三度目に戻って来ると、彼らに言われた。「まだ眠って休んでいるのですか。もう十分です。時が来ました。見なさい。人の子は罪人たちの手に渡されます。'),
('JPN', '马可福音', 41, 14, 42, '立ちなさい。さあ、行こう。見なさい。わたしを裏切る者が近くに来ています。」'),
('JPN', '马可福音', 41, 14, 43, 'そしてすぐ、イエスがまだ話しておられるうちに、十二人の一人のユダが現れた。祭司長たち、律法学者たち、長老たちから差し向けられ、剣や棒を手にした群衆も一緒であった。'),
('JPN', '马可福音', 41, 14, 44, 'イエスを裏切ろうとしていた者は、彼らと合図を決め、「私が口づけをするのが、その人だ。その人を捕まえて、しっかりと引いて行くのだ」と言っておいた。'),
('JPN', '马可福音', 41, 14, 45, 'ユダはやって来るとすぐ、イエスに近づき、「先生」と言って口づけした。'),
('JPN', '马可福音', 41, 14, 46, '人々は、イエスに手をかけて捕らえた。'),
('JPN', '马可福音', 41, 14, 47, 'そのとき、そばに立っていた一人が、剣を抜いて大祭司のしもべに切りかかり、その耳を切り落とした。'),
('JPN', '马可福音', 41, 14, 48, 'イエスは彼らに向かって言われた。「まるで強盗にでも向かうように、剣や棒を持ってわたしを捕らえに来たのですか。'),
('JPN', '马可福音', 41, 14, 49, 'わたしは毎日、宮であなたがたと一緒にいて教えていたのに、あなたがたは、わたしを捕らえませんでした。しかし、こうなったのは聖書が成就するためです。」'),
('JPN', '马可福音', 41, 14, 50, '皆は、イエスを見捨てて逃げてしまった。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '马可福音', 41, 14, 51, 'ある青年が、からだに亜麻布を一枚まとっただけでイエスについて行ったところ、人々が彼を捕らえようとした。'),
('JPN', '马可福音', 41, 14, 52, 'すると、彼は亜麻布を脱ぎ捨てて、裸で逃げた。'),
('JPN', '马可福音', 41, 14, 53, '人々がイエスを大祭司のところに連れて行くと、祭司長たち、長老たち、律法学者たちがみな集まって来た。'),
('JPN', '马可福音', 41, 14, 54, 'ペテロは、遠くからイエスの後について、大祭司の家の庭の中にまで入って行った。そして、下役たちと一緒に座って、火に当たっていた。'),
('JPN', '马可福音', 41, 14, 55, 'さて、祭司長たちと最高法院全体は、イエスを死刑にするため、彼に不利な証言を得ようとしたが、何も見つからなかった。'),
('JPN', '马可福音', 41, 14, 56, '多くの者たちがイエスに不利な偽証をしたが、それらの証言が一致しなかったのである。'),
('JPN', '马可福音', 41, 14, 57, 'すると、何人かが立ち上がり、こう言って、イエスに不利な偽証をした。'),
('JPN', '马可福音', 41, 14, 58, '「『わたしは人の手で造られたこの神殿を壊し、人の手で造られたのではない別の神殿を三日で建てる』とこの人が言うのを、私たちは聞きました。」'),
('JPN', '马可福音', 41, 14, 59, 'しかし、この点でも、証言は一致しなかった。'),
('JPN', '马可福音', 41, 14, 60, 'そこで、大祭司が立ち上がり、真ん中に進み出て、イエスに尋ねた。「何も答えないのか。この人たちがおまえに不利な証言をしているが、どういうことか。」'),
('JPN', '马可福音', 41, 14, 61, 'しかし、イエスは黙ったまま、何もお答えにならなかった。大祭司は再びイエスに尋ねた。「おまえは、ほむべき方の子キリストなのか。」'),
('JPN', '马可福音', 41, 14, 62, 'そこでイエスは言われた。「わたしが、それです。あなたがたは、人の子が力ある方の右の座に着き、そして天の雲とともに来るのを見ることになります。」'),
('JPN', '马可福音', 41, 14, 63, 'すると、大祭司は自分の衣を引き裂いて言った。「なぜこれ以上、証人が必要か。'),
('JPN', '马可福音', 41, 14, 64, 'あなたがたは、神を冒瀆することばを聞いたのだ。どう考えるか。」すると彼らは全員で、イエスは死に値すると決めた。'),
('JPN', '马可福音', 41, 14, 65, 'そして、ある者たちはイエスに唾をかけ、顔に目隠しをして拳で殴り、「当ててみろ」と言い始めた。また、下役たちはイエスを平手で打った。'),
('JPN', '马可福音', 41, 14, 66, 'ペテロが下の中庭にいると、大祭司の召使いの女の一人がやって来た。'),
('JPN', '马可福音', 41, 14, 67, 'ペテロが火に当たっているのを見かけると、彼をじっと見つめて言った。「あなたも、ナザレ人イエスと一緒にいましたね。」'),
('JPN', '马可福音', 41, 14, 68, 'ペテロはそれを否定して、「何を言っているのか分からない。理解できない」と言って、前庭の方に出て行った。すると鶏が鳴いた。'),
('JPN', '马可福音', 41, 14, 69, '召使いの女はペテロを見て、そばに立っていた人たちに再び言い始めた。「この人はあの人たちの仲間です。」'),
('JPN', '马可福音', 41, 14, 70, 'すると、ペテロは再び否定した。しばらくすると、そばに立っていた人たちが、またペテロに言った。「確かに、あなたはあの人たちの仲間だ。ガリラヤ人だから。」'),
('JPN', '马可福音', 41, 14, 71, 'するとペテロは、噓ならのろわれてもよいと誓い始め、「私は、あなたがたが話しているその人を知らない」と言った。'),
('JPN', '马可福音', 41, 14, 72, 'するとすぐに、鶏がもう一度鳴いた。ペテロは、「鶏が二度鳴く前に、あなたは三度わたしを知らないと言います」と、イエスが自分に話されたことを思い出した。そして彼は泣き崩れた。'),
('JPN', '马可福音', 41, 15, 1, '夜が明けるとすぐに、祭司長たちは、長老たちや律法学者たちと最高法院全体で協議を行ってから、イエスを縛って連れ出し、ピラトに引き渡した。'),
('JPN', '马可福音', 41, 15, 2, 'ピラトはイエスに尋ねた。「あなたはユダヤ人の王なのか。」イエスは答えられた。「あなたがそう言っています。」'),
('JPN', '马可福音', 41, 15, 3, 'そこで祭司長たちは、多くのことでイエスを訴えた。'),
('JPN', '马可福音', 41, 15, 4, 'ピラトは再びイエスに尋ねた。「何も答えないのか。見なさい。彼らはあんなにまであなたを訴えているが。」'),
('JPN', '马可福音', 41, 15, 5, 'しかし、イエスはもはや何も答えようとされなかった。それにはピラトも驚いた。'),
('JPN', '马可福音', 41, 15, 6, 'ところで、ピラトは祭りのたびに、人々の願う囚人一人を釈放していた。'),
('JPN', '马可福音', 41, 15, 7, 'そこに、バラバという者がいて、暴動で人殺しをした暴徒たちとともに牢につながれていた。'),
('JPN', '马可福音', 41, 15, 8, '群衆が上って来て、いつものようにしてもらうことを、ピラトに要求し始めた。'),
('JPN', '马可福音', 41, 15, 9, 'そこでピラトは彼らに答えた。「おまえたちはユダヤ人の王を釈放してほしいのか。」'),
('JPN', '马可福音', 41, 15, 10, 'ピラトは、祭司長たちがねたみからイエスを引き渡したことを、知っていたのである。'),
('JPN', '马可福音', 41, 15, 11, 'しかし、祭司長たちは、むしろ、バラバを釈放してもらうように群衆を扇動した。'),
('JPN', '马可福音', 41, 15, 12, 'そこで、ピラトは再び答えた。「では、おまえたちがユダヤ人の王と呼ぶあの人を、私にどうしてほしいのか。」'),
('JPN', '马可福音', 41, 15, 13, 'すると彼らはまたも叫んだ。「十字架につけろ。」'),
('JPN', '马可福音', 41, 15, 14, 'ピラトは彼らに言った。「あの人がどんな悪いことをしたのか。」しかし、彼らはますます激しく叫び続けた。「十字架につけろ。」'),
('JPN', '马可福音', 41, 15, 15, 'それで、ピラトは群衆を満足させようと思い、バラバを釈放し、イエスはむちで打ってから、十字架につけるために引き渡した。'),
('JPN', '马可福音', 41, 15, 16, '兵士たちは、イエスを中庭に、すなわち、総督官邸の中に連れて行き、全部隊を呼び集めた。'),
('JPN', '马可福音', 41, 15, 17, 'そして、イエスに紫の衣を着せ、茨の冠を編んでかぶらせ、'),
('JPN', '马可福音', 41, 15, 18, 'それから、「ユダヤ人の王様、万歳」と叫んで敬礼し始めた。'),
('JPN', '马可福音', 41, 15, 19, 'また、葦の棒でイエスの頭をたたき、唾をかけ、ひざまずいて拝んだ。'),
('JPN', '马可福音', 41, 15, 20, '彼らはイエスをからかってから、紫の衣を脱がせて、元の衣を着せた。それから、イエスを十字架につけるために連れ出した。'),
('JPN', '马可福音', 41, 15, 21, '兵士たちは、通りかかったクレネ人シモンという人に、イエスの十字架を無理やり背負わせた。彼はアレクサンドロとルフォスの父で、田舎から来ていた。'),
('JPN', '马可福音', 41, 15, 22, '彼らはイエスを、ゴルゴタという所（訳すと、どくろの場所）に連れて行った。'),
('JPN', '马可福音', 41, 15, 23, '彼らは、没薬を混ぜたぶどう酒を与えようとしたが、イエスはお受けにならなかった。'),
('JPN', '马可福音', 41, 15, 24, 'それから、彼らはイエスを十字架につけた。そして、くじを引いて、だれが何を取るかを決め、イエスの衣を分けた。'),
('JPN', '马可福音', 41, 15, 25, '彼らがイエスを十字架につけたのは、午前九時であった。'),
('JPN', '马可福音', 41, 15, 26, 'イエスの罪状書きには、「ユダヤ人の王」と書いてあった。'),
('JPN', '马可福音', 41, 15, 27, '彼らは、イエスと一緒に二人の強盗を、一人は右に、一人は左に、十字架につけた。'),
('JPN', '马可福音', 41, 15, 29, '通りすがりの人たちは、頭を振りながらイエスをののしって言った。「おい、神殿を壊して三日で建てる人よ。'),
('JPN', '马可福音', 41, 15, 30, '十字架から降りて来て、自分を救ってみろ。」'),
('JPN', '马可福音', 41, 15, 31, '同じように、祭司長たちも律法学者たちと一緒になって、代わる代わるイエスを嘲って言った。「他人は救ったが、自分は救えない。'),
('JPN', '马可福音', 41, 15, 32, 'キリスト、イスラエルの王に、今、十字架から降りてもらおう。それを見たら信じよう。」また、一緒に十字架につけられていた者たちもイエスをののしった。'),
('JPN', '马可福音', 41, 15, 33, 'さて、十二時になったとき、闇が全地をおおい、午後三時まで続いた。'),
('JPN', '马可福音', 41, 15, 34, 'そして三時に、イエスは大声で叫ばれた。「エロイ、エロイ、レマ、サバクタニ。」訳すと「わが神、わが神、どうしてわたしをお見捨てになったのですか」という意味である。'),
('JPN', '马可福音', 41, 15, 35, 'そばに立っていた人たちの何人かがこれを聞いて言った。「ほら、エリヤを呼んでいる。」'),
('JPN', '马可福音', 41, 15, 36, 'すると一人が駆け寄り、海綿に酸いぶどう酒を含ませて、葦の棒に付け、「待て。エリヤが降ろしに来るか見てみよう」と言って、イエスに飲ませようとした。'),
('JPN', '马可福音', 41, 15, 37, 'しかし、イエスは大声をあげて、息を引き取られた。'),
('JPN', '马可福音', 41, 15, 38, 'すると、神殿の幕が上から下まで真っ二つに裂けた。'),
('JPN', '马可福音', 41, 15, 39, 'イエスの正面に立っていた百人隊長は、イエスがこのように息を引き取られたのを見て言った。「この方は本当に神の子であった。」'),
('JPN', '马可福音', 41, 15, 40, '女たちも遠くから見ていたが、その中には、マグダラのマリアと、小ヤコブとヨセの母マリアと、サロメがいた。'),
('JPN', '马可福音', 41, 15, 41, 'イエスがガリラヤにおられたときに、イエスに従って仕えていた人たちであった。このほかにも、イエスと一緒にエルサレムに上って来た女たちがたくさんいた。'),
('JPN', '马可福音', 41, 15, 42, 'さて、すでに夕方になっていた。その日は備え日、すなわち安息日の前日であったので、'),
('JPN', '马可福音', 41, 15, 43, 'アリマタヤ出身のヨセフは、勇気を出してピラトのところに行き、イエスのからだの下げ渡しを願い出た。ヨセフは有力な議員で、自らも神の国を待ち望んでいた。'),
('JPN', '马可福音', 41, 15, 44, 'ピラトは、イエスがもう死んだのかと驚いた。そして百人隊長を呼び、イエスがすでに死んだのかどうか尋ねた。'),
('JPN', '马可福音', 41, 15, 45, '百人隊長に確認すると、ピラトはイエスの遺体をヨセフに下げ渡した。'),
('JPN', '马可福音', 41, 15, 46, 'ヨセフは亜麻布を買い、イエスを降ろして亜麻布で包み、岩を掘って造った墓に納めた。そして、墓の入り口には石を転がしておいた。'),
('JPN', '马可福音', 41, 15, 47, 'マグダラのマリアとヨセの母マリアは、イエスがどこに納められるか、よく見ていた。'),
('JPN', '马可福音', 41, 16, 1, 'さて、安息日が終わったので、マグダラのマリアとヤコブの母マリアとサロメは、イエスに油を塗りに行こうと思い、香料を買った。'),
('JPN', '马可福音', 41, 16, 2, 'そして、週の初めの日の早朝、日が昇ったころ、墓に行った。'),
('JPN', '马可福音', 41, 16, 3, '彼女たちは、「だれが墓の入り口から石を転がしてくれるでしょうか」と話し合っていた。'),
('JPN', '马可福音', 41, 16, 4, 'ところが、目を上げると、その石が転がしてあるのが見えた。石は非常に大きかった。'),
('JPN', '马可福音', 41, 16, 5, '墓の中に入ると、真っ白な衣をまとった青年が、右側に座っているのが見えたので、彼女たちは非常に驚いた。'),
('JPN', '马可福音', 41, 16, 6, '青年は言った。「驚くことはありません。あなたがたは、十字架につけられたナザレ人イエスを捜しているのでしょう。あの方はよみがえられました。ここにはおられません。ご覧なさい。ここがあの方の納められていた場所です。'),
('JPN', '马可福音', 41, 16, 7, 'さあ行って、弟子たちとペテロに伝えなさい。『イエスは、あなたがたより先にガリラヤへ行かれます。前に言われたとおり、そこでお会いできます』と。」'),
('JPN', '马可福音', 41, 16, 8, '彼女たちは墓を出て、そこから逃げ去った。震え上がり、気も動転していたからである。そしてだれにも何も言わなかった。恐ろしかったからである。〔彼女たちは、命じられたすべてのことを、ペテロとその仲間たちに短く伝えた。その後、イエスご自身が彼らを通して、きよく朽ちることのない永遠の救いの宣言を、日の昇るところから日の沈むところまで送られた。アーメン。〕'),
('JPN', '马可福音', 41, 16, 9, '〔さて、週の初めの日の朝早く、よみがえったイエスは、最初にマグダラのマリアにご自分を現された。彼女は、かつて七つの悪霊をイエスに追い出してもらった人である。'),
('JPN', '马可福音', 41, 16, 10, 'マリアは、イエスと一緒にいた人たちが嘆き悲しんで泣いているところに行って、そのことを知らせた。'),
('JPN', '马可福音', 41, 16, 11, '彼らは、イエスが生きていて彼女にご自分を現された、と聞いても信じなかった。'),
('JPN', '马可福音', 41, 16, 12, 'それから、彼らのうちの二人が徒歩で田舎に向かっていたとき、イエスは別の姿でご自分を現された。'),
('JPN', '马可福音', 41, 16, 13, 'その二人も、ほかの人たちのところへ行って知らせたが、彼らはその話も信じなかった。'),
('JPN', '马可福音', 41, 16, 14, 'その後イエスは、十一人が食卓に着いているところに現れ、彼らの不信仰と頑なな心をお責めになった。よみがえられたイエスを見た人たちの言うことを、彼らが信じなかったからである。'),
('JPN', '马可福音', 41, 16, 15, 'それから、イエスは彼らに言われた。「全世界に出て行き、すべての造られた者に福音を宣べ伝えなさい。'),
('JPN', '马可福音', 41, 16, 16, '信じてバプテスマを受ける者は救われます。しかし、信じない者は罪に定められます。'),
('JPN', '马可福音', 41, 16, 17, '信じる人々には次のようなしるしが伴います。すなわち、わたしの名によって悪霊を追い出し、新しいことばで語り、'),
('JPN', '马可福音', 41, 16, 18, 'その手で蛇をつかみ、たとえ毒を飲んでも決して害を受けず、病人に手を置けば癒やされます。」'),
('JPN', '马可福音', 41, 16, 19, '主イエスは彼らに語った後、天に上げられ、神の右の座に着かれた。'),
('JPN', '马可福音', 41, 16, 20, '弟子たちは出て行って、いたるところで福音を宣べ伝えた。主は彼らとともに働き、みことばを、それに伴うしるしをもって、確かなものとされた。〕'),
('JPN', '路加福音', 42, 1, 1, '私たちの間で成し遂げられた事柄については、初めからの目撃者で、みことばに仕える者となった人たちが私たちに伝えたとおりのことを、多くの人がまとめて書き上げようとすでに試みています。'),
('JPN', '路加福音', 42, 1, 3, '私も、すべてのことを初めから綿密に調べていますから、尊敬するテオフィロ様、あなたのために、順序立てて書いて差し上げるのがよいと思います。'),
('JPN', '路加福音', 42, 1, 4, 'それによって、すでにお受けになった教えが確かであることを、あなたによく分かっていただきたいと思います。'),
('JPN', '路加福音', 42, 1, 5, 'ユダヤの王ヘロデの時代に、アビヤの組の者でザカリヤという名の祭司がいた。彼の妻はアロンの子孫で、名をエリサベツといった。'),
('JPN', '路加福音', 42, 1, 6, '二人とも神の前に正しい人で、主のすべての命令と掟を落度なく行っていた。'),
('JPN', '路加福音', 42, 1, 7, 'しかし、彼らには子がいなかった。エリサベツが不妊だったからである。また、二人ともすでに年をとっていた。'),
('JPN', '路加福音', 42, 1, 8, 'さてザカリヤは、自分の組が当番で、神の前で祭司の務めをしていたとき、'),
('JPN', '路加福音', 42, 1, 9, '祭司職の慣習によってくじを引いたところ、主の神殿に入って香をたくことになった。'),
('JPN', '路加福音', 42, 1, 10, '彼が香をたく間、外では大勢の民がみな祈っていた。'),
('JPN', '路加福音', 42, 1, 11, 'すると、主の使いが彼に現れて、香の祭壇の右に立った。'),
('JPN', '路加福音', 42, 1, 12, 'これを見たザカリヤは取り乱し、恐怖に襲われた。'),
('JPN', '路加福音', 42, 1, 13, '御使いは彼に言った。「恐れることはありません、ザカリヤ。あなたの願いが聞き入れられたのです。あなたの妻エリサベツは、あなたに男の子を産みます。その名をヨハネとつけなさい。'),
('JPN', '路加福音', 42, 1, 14, 'その子はあなたにとって、あふれるばかりの喜びとなり、多くの人もその誕生を喜びます。'),
('JPN', '路加福音', 42, 1, 15, 'その子は主の御前に大いなる者となるからです。彼はぶどう酒や強い酒を決して飲まず、まだ母の胎にいるときから聖霊に満たされ、'),
('JPN', '路加福音', 42, 1, 16, 'イスラエルの子らの多くを、彼らの神である主に立ち返らせます。'),
('JPN', '路加福音', 42, 1, 17, '彼はエリヤの霊と力で、主に先立って歩みます。父たちの心を子どもたちに向けさせ、不従順な者たちを義人の思いに立ち返らせて、主のために、整えられた民を用意します。」'),
('JPN', '路加福音', 42, 1, 18, 'ザカリヤは御使いに言った。「私はそのようなことを、何によって知ることができるでしょうか。この私は年寄りですし、妻ももう年をとっています。」'),
('JPN', '路加福音', 42, 1, 19, '御使いは彼に答えた。「この私は神の前に立つガブリエルです。あなたに話をし、この良い知らせを伝えるために遣わされたのです。'),
('JPN', '路加福音', 42, 1, 20, '見なさい。これらのことが起こる日まで、あなたは口がきけなくなり、話せなくなります。その時が来れば実現する私のことばを、あなたが信じなかったからです。」'),
('JPN', '路加福音', 42, 1, 21, '民はザカリヤを待っていたが、神殿で手間取っているので、不思議に思っていた。'),
('JPN', '路加福音', 42, 1, 22, 'やがて彼は出て来たが、彼らに話をすることができなかった。それで、彼が神殿で幻を見たことが分かった。ザカリヤは彼らに合図をするだけで、口がきけないままであった。'),
('JPN', '路加福音', 42, 1, 23, 'やがて務めの期間が終わり、彼は自分の家に帰った。'),
('JPN', '路加福音', 42, 1, 24, 'しばらくして、妻エリサベツは身ごもった。そして、「主は今このようにして私に目を留め、人々の間から私の恥を取り除いてくださいました」と言い、五か月の間、安静にしていた。'),
('JPN', '路加福音', 42, 1, 26, 'さて、その六か月目に、御使いガブリエルが神から遣わされて、ガリラヤのナザレという町の一人の処女のところに来た。'),
('JPN', '路加福音', 42, 1, 27, 'この処女は、ダビデの家系のヨセフという人のいいなずけで、名をマリアといった。'),
('JPN', '路加福音', 42, 1, 28, '御使いは入って来ると、マリアに言った。「おめでとう、恵まれた方。主があなたとともにおられます。」'),
('JPN', '路加福音', 42, 1, 29, 'しかし、マリアはこのことばにひどく戸惑って、これはいったい何のあいさつかと考え込んだ。'),
('JPN', '路加福音', 42, 1, 30, 'すると、御使いは彼女に言った。「恐れることはありません、マリア。あなたは神から恵みを受けたのです。'),
('JPN', '路加福音', 42, 1, 31, '見なさい。あなたは身ごもって、男の子を産みます。その名をイエスとつけなさい。'),
('JPN', '路加福音', 42, 1, 32, 'その子は大いなる者となり、いと高き方の子と呼ばれます。また神である主は、彼にその父ダビデの王位をお与えになります。'),
('JPN', '路加福音', 42, 1, 33, '彼はとこしえにヤコブの家を治め、その支配に終わりはありません。」'),
('JPN', '路加福音', 42, 1, 34, 'マリアは御使いに言った。「どうしてそのようなことが起こるのでしょう。私は男の人を知りませんのに。」'),
('JPN', '路加福音', 42, 1, 35, '御使いは彼女に答えた。「聖霊があなたの上に臨み、いと高き方の力があなたをおおいます。それゆえ、生まれる子は聖なる者、神の子と呼ばれます。'),
('JPN', '路加福音', 42, 1, 36, '見なさい。あなたの親類のエリサベツ、あの人もあの年になって男の子を宿しています。不妊と言われていた人なのに、今はもう六か月です。'),
('JPN', '路加福音', 42, 1, 37, '神にとって不可能なことは何もありません。」'),
('JPN', '路加福音', 42, 1, 38, 'マリアは言った。「ご覧ください。私は主のはしためです。どうぞ、あなたのおことばどおり、この身になりますように。」すると、御使いは彼女から去って行った。'),
('JPN', '路加福音', 42, 1, 39, 'それから、マリアは立って、山地にあるユダの町に急いで行った。'),
('JPN', '路加福音', 42, 1, 40, 'そしてザカリヤの家に行って、エリサベツにあいさつした。'),
('JPN', '路加福音', 42, 1, 41, 'エリサベツがマリアのあいさつを聞いたとき、子が胎内で躍り、エリサベツは聖霊に満たされた。'),
('JPN', '路加福音', 42, 1, 42, 'そして大声で叫んだ。「あなたは女の中で最も祝福された方。あなたの胎の実も祝福されています。'),
('JPN', '路加福音', 42, 1, 43, '私の主の母が私のところに来られるとは、どうしたことでしょう。'),
('JPN', '路加福音', 42, 1, 44, 'あなたのあいさつの声が私の耳に入った、ちょうどそのとき、私の胎内で子どもが喜んで躍りました。'),
('JPN', '路加福音', 42, 1, 45, '主によって語られたことは必ず実現すると信じた人は、幸いです。」'),
('JPN', '路加福音', 42, 1, 46, 'マリアは言った。「私のたましいは主をあがめ、'),
('JPN', '路加福音', 42, 1, 47, '私の霊は私の救い主である神をたたえます。'),
('JPN', '路加福音', 42, 1, 48, 'この卑しいはしために目を留めてくださったからです。ご覧ください。今から後、どの時代の人々も私を幸いな者と呼ぶでしょう。'),
('JPN', '路加福音', 42, 1, 49, '力ある方が、私に大きなことをしてくださったからです。その御名は聖なるもの、'),
('JPN', '路加福音', 42, 1, 50, '主のあわれみは、代々にわたって主を恐れる者に及びます。'),
('JPN', '路加福音', 42, 1, 51, '主はその御腕で力強いわざを行い、心の思いの高ぶる者を追い散らされました。'),
('JPN', '路加福音', 42, 1, 52, '権力のある者を王位から引き降ろし、低い者を高く引き上げられました。'),
('JPN', '路加福音', 42, 1, 53, '飢えた者を良いもので満ち足らせ、富む者を何も持たせずに追い返されました。'),
('JPN', '路加福音', 42, 1, 54, '主はあわれみを忘れずに、そのしもべイスラエルを助けてくださいました。'),
('JPN', '路加福音', 42, 1, 55, '私たちの父祖たちに語られたとおり、アブラハムとその子孫に対するあわれみをいつまでも忘れずに。」'),
('JPN', '路加福音', 42, 1, 56, 'マリアは、三か月ほどエリサベツのもとにとどまって、家に帰った。'),
('JPN', '路加福音', 42, 1, 57, 'さて、月が満ちて、エリサベツは男の子を産んだ。'),
('JPN', '路加福音', 42, 1, 58, '近所の人たちや親族は、主がエリサベツに大きなあわれみをかけてくださったことを聞いて、彼女とともに喜んだ。'),
('JPN', '路加福音', 42, 1, 59, '八日目になり、人々は幼子に割礼を施すためにやって来た。彼らは幼子を父の名にちなんでザカリヤと名づけようとしたが、'),
('JPN', '路加福音', 42, 1, 60, '母親は「いいえ、名はヨハネとしなければなりません」と言った。'),
('JPN', '路加福音', 42, 1, 61, '彼らは彼女に「あなたの親族には、そのような名の人は一人もいません」と言った。'),
('JPN', '路加福音', 42, 1, 62, 'そして、幼子にどういう名をつけるつもりか、身振りで父親に尋ねた。'),
('JPN', '路加福音', 42, 1, 63, 'すると彼は書き板を持って来させて、「その子の名はヨハネ」と書いたので、人々はみな驚いた。'),
('JPN', '路加福音', 42, 1, 64, 'すると、ただちにザカリヤの口が開かれ、舌が解かれ、ものが言えるようになって神をほめたたえた。'),
('JPN', '路加福音', 42, 1, 65, '近所に住む人たちはみな恐れを抱いた。そして、これらのことの一部始終が、ユダヤの山地全体に語り伝えられていった。'),
('JPN', '路加福音', 42, 1, 66, '聞いた人たちはみな、これらのことを心にとどめ、「いったいこの子は何になるのでしょうか」と言った。主の御手がその子とともにあったからである。'),
('JPN', '路加福音', 42, 1, 67, 'さて、父親のザカリヤは聖霊に満たされて預言した。'),
('JPN', '路加福音', 42, 1, 68, '「ほむべきかな、イスラエルの神、主。主はその御民を顧みて、贖いをなし、'),
('JPN', '路加福音', 42, 1, 69, '救いの角を私たちのために、しもべダビデの家に立てられた。'),
('JPN', '路加福音', 42, 1, 70, '古くから、その聖なる預言者たちの口を通して語られたとおりに。'),
('JPN', '路加福音', 42, 1, 71, 'この救いは、私たちの敵からの、私たちを憎むすべての者の手からの救いである。'),
('JPN', '路加福音', 42, 1, 72, '主は私たちの父祖たちにあわれみを施し、ご自分の聖なる契約を覚えておられた。'),
('JPN', '路加福音', 42, 1, 73, '私たちの父アブラハムに誓われた誓いを。'),
('JPN', '路加福音', 42, 1, 74, '主は私たちを敵の手から救い出し、恐れなく主に仕えるようにしてくださる。'),
('JPN', '路加福音', 42, 1, 75, '私たちのすべての日々において、主の御前で、敬虔に、正しく。'),
('JPN', '路加福音', 42, 1, 76, '幼子よ、あなたこそいと高き方の預言者と呼ばれる。主の御前を先立って行き、その道を備え、'),
('JPN', '路加福音', 42, 1, 77, '罪の赦しによる救いについて、神の民に、知識を与えるからである。'),
('JPN', '路加福音', 42, 1, 78, 'これは私たちの神の深いあわれみによる。そのあわれみにより、曙の光が、いと高き所から私たちに訪れ、'),
('JPN', '路加福音', 42, 1, 79, '暗闇と死の陰に住んでいた者たちを照らし、私たちの足を平和の道に導く。」'),
('JPN', '路加福音', 42, 1, 80, '幼子は成長し、その霊は強くなり、イスラエルの民の前に公に現れる日まで荒野にいた。'),
('JPN', '路加福音', 42, 2, 1, 'そのころ、全世界の住民登録をせよという勅令が、皇帝アウグストゥスから出た。'),
('JPN', '路加福音', 42, 2, 2, 'これは、キリニウスがシリアの総督であったときの、最初の住民登録であった。'),
('JPN', '路加福音', 42, 2, 3, '人々はみな登録のために、それぞれ自分の町に帰って行った。'),
('JPN', '路加福音', 42, 2, 4, 'ヨセフも、ダビデの家に属し、その血筋であったので、ガリラヤの町ナザレから、ユダヤのベツレヘムというダビデの町へ上って行った。'),
('JPN', '路加福音', 42, 2, 5, '身重になっていた、いいなずけの妻マリアとともに登録するためであった。'),
('JPN', '路加福音', 42, 2, 6, 'ところが、彼らがそこにいる間に、マリアは月が満ちて、'),
('JPN', '路加福音', 42, 2, 7, '男子の初子を産んだ。そして、その子を布にくるんで飼葉桶に寝かせた。宿屋には彼らのいる場所がなかったからである。'),
('JPN', '路加福音', 42, 2, 8, 'さて、その地方で、羊飼いたちが野宿をしながら、羊の群れの夜番をしていた。'),
('JPN', '路加福音', 42, 2, 9, 'すると、主の使いが彼らのところに来て、主の栄光が周りを照らしたので、彼らは非常に恐れた。'),
('JPN', '路加福音', 42, 2, 10, '御使いは彼らに言った。「恐れることはありません。見なさい。私は、この民全体に与えられる、大きな喜びを告げ知らせます。'),
('JPN', '路加福音', 42, 2, 11, '今日ダビデの町で、あなたがたのために救い主がお生まれになりました。この方こそ主キリストです。'),
('JPN', '路加福音', 42, 2, 12, 'あなたがたは、布にくるまって飼葉桶に寝ているみどりごを見つけます。それが、あなたがたのためのしるしです。」'),
('JPN', '路加福音', 42, 2, 13, 'すると突然、その御使いと一緒におびただしい数の天の軍勢が現れて、神を賛美した。'),
('JPN', '路加福音', 42, 2, 14, '「いと高き所で、栄光が神にあるように。地の上で、平和がみこころにかなう人々にあるように。」'),
('JPN', '路加福音', 42, 2, 15, '御使いたちが彼らから離れて天に帰ったとき、羊飼いたちは話し合った。「さあ、ベツレヘムまで行って、主が私たちに知らせてくださったこの出来事を見届けて来よう。」'),
('JPN', '路加福音', 42, 2, 16, 'そして急いで行って、マリアとヨセフと、飼葉桶に寝ているみどりごを捜し当てた。'),
('JPN', '路加福音', 42, 2, 17, 'それを目にして羊飼いたちは、この幼子について自分たちに告げられたことを知らせた。'),
('JPN', '路加福音', 42, 2, 18, '聞いた人たちはみな、羊飼いたちが話したことに驚いた。'),
('JPN', '路加福音', 42, 2, 19, 'しかしマリアは、これらのことをすべて心に納めて、思いを巡らしていた。'),
('JPN', '路加福音', 42, 2, 20, '羊飼いたちは、見聞きしたことがすべて御使いの話のとおりだったので、神をあがめ、賛美しながら帰って行った。'),
('JPN', '路加福音', 42, 2, 21, '八日が満ちて幼子に割礼を施す日となり、幼子の名はイエスとつけられた。胎内に宿る前に御使いがつけた名である。'),
('JPN', '路加福音', 42, 2, 22, 'そして、モーセの律法による彼らのきよめの期間が満ちたとき、両親は幼子をエルサレムに連れて行った。'),
('JPN', '路加福音', 42, 2, 23, 'それは、主の律法に「最初に胎を開く男子はみな、主のために聖別された者と呼ばれる」と書いてあるとおり、幼子を主に献げるためであった。'),
('JPN', '路加福音', 42, 2, 24, 'また、主の律法に「山鳩一つがい、あるいは家鳩のひな二羽」と言われていることにしたがって、いけにえを献げるためであった。'),
('JPN', '路加福音', 42, 2, 25, 'そのとき、エルサレムにシメオンという人がいた。この人は正しい、敬虔な人で、イスラエルが慰められるのを待ち望んでいた。また、聖霊が彼の上におられた。'),
('JPN', '路加福音', 42, 2, 26, 'そして、主のキリストを見るまでは決して死を見ることはないと、聖霊によって告げられていた。'),
('JPN', '路加福音', 42, 2, 27, 'シメオンが御霊に導かれて宮に入ると、律法の慣習を守るために、両親が幼子イエスを連れて入って来た。'),
('JPN', '路加福音', 42, 2, 28, 'シメオンは幼子を腕に抱き、神をほめたたえて言った。'),
('JPN', '路加福音', 42, 2, 29, '「主よ。今こそあなたは、おことばどおり、しもべを安らかに去らせてくださいます。'),
('JPN', '路加福音', 42, 2, 30, '私の目があなたの御救いを見たからです。'),
('JPN', '路加福音', 42, 2, 31, 'あなたが万民の前に備えられた救いを。'),
('JPN', '路加福音', 42, 2, 32, '異邦人を照らす啓示の光、御民イスラエルの栄光を。」'),
('JPN', '路加福音', 42, 2, 33, '父と母は、幼子について語られる様々なことに驚いた。'),
('JPN', '路加福音', 42, 2, 34, 'シメオンは両親を祝福し、母マリアに言った。「ご覧なさい。この子は、イスラエルの多くの人が倒れたり立ち上がったりするために定められ、また、人々の反対にあうしるしとして定められています。'),
('JPN', '路加福音', 42, 2, 35, 'あなた自身の心さえも、剣が刺し貫くことになります。それは多くの人の心のうちの思いが、あらわになるためです。」'),
('JPN', '路加福音', 42, 2, 36, 'また、アシェル族のペヌエルの娘で、アンナという女預言者がいた。この人は非常に年をとっていた。処女の時代の後、七年間夫とともに暮らしたが、'),
('JPN', '路加福音', 42, 2, 37, 'やもめとなり、八十四歳になっていた。彼女は宮を離れず、断食と祈りをもって、夜も昼も神に仕えていた。'),
('JPN', '路加福音', 42, 2, 38, 'ちょうどそのとき彼女も近寄って来て、神に感謝をささげ、エルサレムの贖いを待ち望んでいたすべての人に、この幼子のことを語った。'),
('JPN', '路加福音', 42, 2, 39, '両親は、主の律法にしたがってすべてのことを成し遂げたので、ガリラヤの自分たちの町ナザレに帰って行った。'),
('JPN', '路加福音', 42, 2, 40, '幼子は成長し、知恵に満ちてたくましくなり、神の恵みがその上にあった。'),
('JPN', '路加福音', 42, 2, 41, 'さて、イエスの両親は、過越の祭りに毎年エルサレムに行っていた。'),
('JPN', '路加福音', 42, 2, 42, 'イエスが十二歳になられたときも、両親は祭りの慣習にしたがって都へ上った。'),
('JPN', '路加福音', 42, 2, 43, 'そして祭りの期間を過ごしてから帰路についたが、少年イエスはエルサレムにとどまっておられた。両親はそれに気づかずに、'),
('JPN', '路加福音', 42, 2, 44, 'イエスが一行の中にいるものと思って、一日の道のりを進んだ。後になって親族や知人の中を捜し回ったが、'),
('JPN', '路加福音', 42, 2, 45, '見つからなかったので、イエスを捜しながらエルサレムまで引き返した。'),
('JPN', '路加福音', 42, 2, 46, 'そして三日後になって、イエスが宮で教師たちの真ん中に座って、話を聞いたり質問したりしておられるのを見つけた。'),
('JPN', '路加福音', 42, 2, 47, '聞いていた人たちはみな、イエスの知恵と答えに驚いていた。'),
('JPN', '路加福音', 42, 2, 48, '両親は彼を見て驚き、母は言った。「どうしてこんなことをしたのですか。見なさい。お父さんも私も、心配してあなたを捜していたのです。」'),
('JPN', '路加福音', 42, 2, 49, 'すると、イエスは両親に言われた。「どうしてわたしを捜されたのですか。わたしが自分の父の家にいるのは当然であることを、ご存じなかったのですか。」'),
('JPN', '路加福音', 42, 2, 50, 'しかし両親には、イエスの語られたことばが理解できなかった。'),
('JPN', '路加福音', 42, 2, 51, 'それからイエスは一緒に下って行き、ナザレに帰って両親に仕えられた。母はこれらのことをみな、心に留めておいた。'),
('JPN', '路加福音', 42, 2, 52, 'イエスは神と人とにいつくしまれ、知恵が増し加わり、背たけも伸びていった。'),
('JPN', '路加福音', 42, 3, 1, '皇帝ティベリウスの治世の第十五年、ポンティオ・ピラトがユダヤの総督であり、ヘロデがガリラヤの領主、その兄弟ピリポがイトラヤとトラコニテ地方の領主、リサニアがアビレネの領主、'),
('JPN', '路加福音', 42, 3, 2, 'アンナスとカヤパが大祭司であったころ、神のことばが、荒野でザカリヤの子ヨハネに臨んだ。'),
('JPN', '路加福音', 42, 3, 3, 'ヨハネはヨルダン川周辺のすべての地域に行って、罪の赦しに導く悔い改めのバプテスマを宣べ伝えた。'),
('JPN', '路加福音', 42, 3, 4, 'これは、預言者イザヤのことばの書に書いてあるとおりである。「荒野で叫ぶ者の声がする。『主の道を用意せよ。主の通られる道をまっすぐにせよ。'),
('JPN', '路加福音', 42, 3, 5, 'すべての谷は埋められ、すべての山や丘は低くなる。曲がったところはまっすぐになり、険しい道は平らになる。'),
('JPN', '路加福音', 42, 3, 6, 'こうして、すべての者が神の救いを見る。』」'),
('JPN', '路加福音', 42, 3, 7, 'ヨハネは、彼からバプテスマを受けようとして出て来た群衆に言った。「まむしの子孫たち。だれが、迫り来る怒りを逃れるようにと教えたのか。'),
('JPN', '路加福音', 42, 3, 8, 'それなら、悔い改めにふさわしい実を結びなさい。『われわれの父はアブラハムだ』という考えを起こしてはいけません。言っておきますが、神はこれらの石ころからでも、アブラハムの子らを起こすことができるのです。'),
('JPN', '路加福音', 42, 3, 9, '斧もすでに木の根元に置かれています。だから、良い実を結ばない木はすべて切り倒されて、火に投げ込まれます。」'),
('JPN', '路加福音', 42, 3, 10, '群衆はヨハネに尋ねた。「それでは、私たちはどうすればよいのでしょうか。」'),
('JPN', '路加福音', 42, 3, 11, 'ヨハネは答えた。「下着を二枚持っている人は、持っていない人に分けてあげなさい。食べ物を持っている人も同じようにしなさい。」'),
('JPN', '路加福音', 42, 3, 12, '取税人たちもバプテスマを受けにやって来て、ヨハネに言った。「先生、私たちはどうすればよいのでしょうか。」'),
('JPN', '路加福音', 42, 3, 13, 'ヨハネは彼らに言った。「決められた以上には、何も取り立ててはいけません。」'),
('JPN', '路加福音', 42, 3, 14, '兵士たちもヨハネに尋ねた。「この私たちはどうすればよいのでしょうか。」ヨハネは言った。「だれからも、金を力ずくで奪ったり脅し取ったりしてはいけません。自分の給料で満足しなさい。」'),
('JPN', '路加福音', 42, 3, 15, '人々はキリストを待ち望んでいたので、みなヨハネのことを、もしかするとこの方がキリストではないか、と心の中で考えていた。'),
('JPN', '路加福音', 42, 3, 16, 'そこでヨハネは皆に向かって言った。「私は水であなたがたにバプテスマを授けています。しかし、私よりも力のある方が来られます。私はその方の履き物のひもを解く資格もありません。その方は聖霊と火で、あなたがたにバプテスマを授けられます。'),
('JPN', '路加福音', 42, 3, 17, 'また手に箕を持って、ご自分の脱穀場を隅々まで掃ききよめ、麦を集めて倉に納められます。そして、殻を消えない火で焼き尽くされます。」'),
('JPN', '路加福音', 42, 3, 18, 'このようにヨハネは、ほかにも多くのことを勧めながら、人々に福音を伝えた。'),
('JPN', '路加福音', 42, 3, 19, 'しかし領主ヘロデは、兄弟の妻ヘロディアのことと、自分が行った悪事のすべてをヨハネに非難されたので、'),
('JPN', '路加福音', 42, 3, 20, 'すべての悪事にもう一つ悪事を加え、ヨハネを牢に閉じ込めた。'),
('JPN', '路加福音', 42, 3, 21, 'さて、民がみなバプテスマを受けていたころ、イエスもバプテスマを受けられた。そして祈っておられると、天が開け、'),
('JPN', '路加福音', 42, 3, 22, '聖霊が鳩のような形をして、イエスの上に降って来られた。すると、天から声がした。「あなたはわたしの愛する子。わたしはあなたを喜ぶ。」'),
('JPN', '路加福音', 42, 3, 23, 'イエスは、働きを始められたとき、およそ三十歳で、ヨセフの子と考えられていた。ヨセフはエリの子で、さかのぼると、'),
('JPN', '路加福音', 42, 3, 24, 'マタテ、レビ、メルキ、ヤンナイ、ヨセフ、'),
('JPN', '路加福音', 42, 3, 25, 'マタティア、アモス、ナホム、エスリ、ナガイ、'),
('JPN', '路加福音', 42, 3, 26, 'マハテ、マタティア、シメイ、ヨセク、ヨダ、'),
('JPN', '路加福音', 42, 3, 27, 'ヨハナン、レサ、ゼルバベル、シェアルティエル、ネリ、'),
('JPN', '路加福音', 42, 3, 28, 'メルキ、アディ、コサム、エルマダム、エル、'),
('JPN', '路加福音', 42, 3, 29, 'ヨシュア、エリエゼル、ヨリム、マタテ、レビ、'),
('JPN', '路加福音', 42, 3, 30, 'シメオン、ユダ、ヨセフ、ヨナム、エルヤキム、'),
('JPN', '路加福音', 42, 3, 31, 'メレア、メンナ、マタタ、ナタン、ダビデ、'),
('JPN', '路加福音', 42, 3, 32, 'エッサイ、オベデ、ボアズ、サラ、ナフション、'),
('JPN', '路加福音', 42, 3, 33, 'アミナダブ、アデミン、アルニ、ヘツロン、ペレツ、ユダ、'),
('JPN', '路加福音', 42, 3, 34, 'ヤコブ、イサク、アブラハム、テラ、ナホル、'),
('JPN', '路加福音', 42, 3, 35, 'セルグ、レウ、ペレグ、エベル、シェラ、'),
('JPN', '路加福音', 42, 3, 36, 'ケナン、アルパクシャデ、セム、ノア、レメク、'),
('JPN', '路加福音', 42, 3, 37, 'メトシェラ、エノク、ヤレデ、マハラルエル、ケナン、'),
('JPN', '路加福音', 42, 3, 38, 'エノシュ、セツ、アダム、そして神に至る。'),
('JPN', '路加福音', 42, 4, 1, 'さて、イエスは聖霊に満ちてヨルダンから帰られた。そして御霊によって荒野に導かれ、'),
('JPN', '路加福音', 42, 4, 2, '四十日間、悪魔の試みを受けられた。その間イエスは何も食べず、その期間が終わると空腹を覚えられた。'),
('JPN', '路加福音', 42, 4, 3, 'そこで、悪魔はイエスに言った。「あなたが神の子なら、この石に、パンになるように命じなさい。」'),
('JPN', '路加福音', 42, 4, 4, 'イエスは悪魔に答えられた。「『人はパンだけで生きるのではない』と書いてある。」'),
('JPN', '路加福音', 42, 4, 5, 'すると悪魔はイエスを高いところに連れて行き、一瞬のうちに世界のすべての国々を見せて、'),
('JPN', '路加福音', 42, 4, 6, 'こう言った。「このような、国々の権力と栄光をすべてあなたにあげよう。それは私に任されていて、だれでも私が望む人にあげるのだから。'),
('JPN', '路加福音', 42, 4, 7, 'だから、もしあなたが私の前にひれ伏すなら、すべてがあなたのものとなる。」'),
('JPN', '路加福音', 42, 4, 8, 'イエスは悪魔に答えられた。「『あなたの神である主を礼拝しなさい。主にのみ仕えなさい』と書いてある。」'),
('JPN', '路加福音', 42, 4, 9, 'また、悪魔はイエスをエルサレムに連れて行き、神殿の屋根の端に立たせて、こう言った。「あなたが神の子なら、ここから下に身を投げなさい。'),
('JPN', '路加福音', 42, 4, 10, '『神は、あなたのために御使いたちに命じて、あなたを守られる。'),
('JPN', '路加福音', 42, 4, 11, '彼らは、その両手にあなたをのせ、あなたの足が石に打ち当たらないようにする』と書いてあるから。」'),
('JPN', '路加福音', 42, 4, 12, 'するとイエスは答えられた。「『あなたの神である主を試みてはならない』と言われている。」'),
('JPN', '路加福音', 42, 4, 13, '悪魔はあらゆる試みを終えると、しばらくの間イエスから離れた。'),
('JPN', '路加福音', 42, 4, 14, 'イエスは御霊の力を帯びてガリラヤに帰られた。すると、その評判が周辺一帯に広まった。'),
('JPN', '路加福音', 42, 4, 15, 'イエスは彼らの会堂で教え、すべての人に称賛された。'),
('JPN', '路加福音', 42, 4, 16, 'それからイエスはご自分が育ったナザレに行き、いつもしているとおり安息日に会堂に入り、朗読しようとして立たれた。'),
('JPN', '路加福音', 42, 4, 17, 'すると、預言者イザヤの書が手渡されたので、その巻物を開いて、こう書いてある箇所に目を留められた。'),
('JPN', '路加福音', 42, 4, 18, '「主の霊がわたしの上にある。貧しい人に良い知らせを伝えるため、主はわたしに油を注ぎ、わたしを遣わされた。捕らわれ人には解放を、目の見えない人には目の開かれることを告げ、虐げられている人を自由の身とし、'),
('JPN', '路加福音', 42, 4, 19, '主の恵みの年を告げるために。」'),
('JPN', '路加福音', 42, 4, 20, 'イエスは巻物を巻き、係りの者に渡して座られた。会堂にいた皆の目はイエスに注がれていた。'),
('JPN', '路加福音', 42, 4, 21, 'イエスは人々に向かって話し始められた。「あなたがたが耳にしたとおり、今日、この聖書のことばが実現しました。」'),
('JPN', '路加福音', 42, 4, 22, '人々はみなイエスをほめ、その口から出て来る恵みのことばに驚いて、「この人はヨセフの子ではないか」と言った。'),
('JPN', '路加福音', 42, 4, 23, 'そこでイエスは彼らに言われた。「きっとあなたがたは、『医者よ、自分を治せ』ということわざを引いて、『カペナウムで行われたと聞いていることを、あなたの郷里のここでもしてくれ』と言うでしょう。」'),
('JPN', '路加福音', 42, 4, 24, 'そしてこう言われた。「まことに、あなたがたに言います。預言者はだれも、自分の郷里では歓迎されません。'),
('JPN', '路加福音', 42, 4, 25, 'まことに、あなたがたに言います。エリヤの時代に、イスラエルに多くのやもめがいました。三年六か月の間、天が閉じられ、大飢饉が全地に起こったとき、'),
('JPN', '路加福音', 42, 4, 26, 'そのやもめたちのだれのところにもエリヤは遣わされず、シドンのツァレファテにいた、一人のやもめの女にだけ遣わされました。'),
('JPN', '路加福音', 42, 4, 27, 'また、預言者エリシャのときには、イスラエルにはツァラアトに冒された人が多くいましたが、その中のだれもきよめられることはなく、シリア人ナアマンだけがきよめられました。」'),
('JPN', '路加福音', 42, 4, 28, 'これを聞くと、会堂にいた人たちはみな憤りに満たされ、'),
('JPN', '路加福音', 42, 4, 29, '立ち上がってイエスを町の外に追い出した。そして町が建っていた丘の崖の縁まで連れて行き、そこから突き落とそうとした。'),
('JPN', '路加福音', 42, 4, 30, 'しかし、イエスは彼らのただ中を通り抜けて、去って行かれた。'),
('JPN', '路加福音', 42, 4, 31, 'それからイエスは、ガリラヤの町カペナウムに下られた。そして安息日には人々を教えておられた。'),
('JPN', '路加福音', 42, 4, 32, '人々はその教えに驚いた。そのことばに権威があったからである。'),
('JPN', '路加福音', 42, 4, 33, 'そこの会堂に、汚れた悪霊につかれた人がいた。彼は大声で叫んだ。'),
('JPN', '路加福音', 42, 4, 34, '「ああ、ナザレの人イエスよ、私たちと何の関係があるのですか。私たちを滅ぼしに来たのですか。私はあなたがどなたなのか知っています。神の聖者です。」'),
('JPN', '路加福音', 42, 4, 35, 'イエスは彼を叱って、「黙れ。この人から出て行け」と言われた。すると悪霊は、その人を人々の真ん中に投げ倒し、何の害も与えることなくその人から出て行った。'),
('JPN', '路加福音', 42, 4, 36, '人々はみな驚いて、互いに言った。「このことばは何なのだろうか。権威と力をもって命じられると、汚れた霊が出て行くとは。」'),
('JPN', '路加福音', 42, 4, 37, 'こうしてイエスのうわさは、周辺の地域のいたるところに広まっていった。'),
('JPN', '路加福音', 42, 4, 38, 'イエスは立ち上がって会堂を出て、シモンの家に入られた。シモンの姑がひどい熱で苦しんでいたので、人々は彼女のことをイエスにお願いした。'),
('JPN', '路加福音', 42, 4, 39, 'イエスがその枕元に立って熱を叱りつけられると、熱がひいた。彼女はすぐに立ち上がって彼らをもてなし始めた。'),
('JPN', '路加福音', 42, 4, 40, '日が沈むと、様々な病で弱っている者をかかえている人たちがみな、病人たちをみもとに連れて来た。イエスは一人ひとりに手を置いて癒やされた。'),
('JPN', '路加福音', 42, 4, 41, 'また悪霊どもも、「あなたこそ神の子です」と叫びながら、多くの人から出て行った。イエスは悪霊どもを叱って、ものを言うのをお許しにならなかった。イエスがキリストであることを、彼らが知っていたからである。'),
('JPN', '路加福音', 42, 4, 42, '朝になって、イエスは寂しいところに出て行かれた。群衆はイエスを捜し回って、みもとまでやって来た。そして、イエスが自分たちから離れて行かないように、引き止めておこうとした。'),
('JPN', '路加福音', 42, 4, 43, 'しかしイエスは、彼らにこう言われた。「ほかの町々にも、神の国の福音を宣べ伝えなければなりません。わたしは、そのために遣わされたのですから。」'),
('JPN', '路加福音', 42, 4, 44, 'そしてユダヤの諸会堂で、宣教を続けられた。'),
('JPN', '路加福音', 42, 5, 1, 'さて、群衆が神のことばを聞こうとしてイエスに押し迫って来たとき、イエスはゲネサレ湖の岸辺に立って、'),
('JPN', '路加福音', 42, 5, 2, '岸辺に小舟が二艘あるのをご覧になった。漁師たちは舟から降りて網を洗っていた。'),
('JPN', '路加福音', 42, 5, 3, 'イエスはそのうちの一つ、シモンの舟に乗り、陸から少し漕ぎ出すようにお頼みになった。そして腰を下ろし、舟から群衆を教え始められた。'),
('JPN', '路加福音', 42, 5, 4, '話が終わるとシモンに言われた。「深みに漕ぎ出し、網を下ろして魚を捕りなさい。」'),
('JPN', '路加福音', 42, 5, 5, 'すると、シモンが答えた。「先生。私たちは夜通し働きましたが、何一つ捕れませんでした。でも、おことばですので、網を下ろしてみましょう。」'),
('JPN', '路加福音', 42, 5, 6, 'そして、そのとおりにすると、おびただしい数の魚が入り、網が破れそうになった。'),
('JPN', '路加福音', 42, 5, 7, 'そこで別の舟にいた仲間の者たちに、助けに来てくれるよう合図した。彼らがやって来て、魚を二艘の舟いっぱいに引き上げたところ、両方とも沈みそうになった。'),
('JPN', '路加福音', 42, 5, 8, 'これを見たシモン・ペテロは、イエスの足もとにひれ伏して言った。「主よ、私から離れてください。私は罪深い人間ですから。」'),
('JPN', '路加福音', 42, 5, 9, '彼も、一緒にいた者たちもみな、自分たちが捕った魚のことで驚いたのであった。'),
('JPN', '路加福音', 42, 5, 10, 'シモンの仲間の、ゼベダイの子ヤコブやヨハネも同じであった。イエスはシモンに言われた。「恐れることはない。今から後、あなたは人間を捕るようになるのです。」'),
('JPN', '路加福音', 42, 5, 11, '彼らは舟を陸に着けると、すべてを捨ててイエスに従った。'),
('JPN', '路加福音', 42, 5, 12, 'さて、イエスがある町におられたとき、見よ、全身ツァラアトに冒された人がいた。その人はイエスを見ると、ひれ伏してお願いした。「主よ、お心一つで私をきよくすることがおできになります。」'),
('JPN', '路加福音', 42, 5, 13, 'イエスは手を伸ばして彼にさわり、「わたしの心だ。きよくなれ」と言われた。すると、すぐにツァラアトが消えた。'),
('JPN', '路加福音', 42, 5, 14, 'イエスは彼にこう命じられた。「だれにも話してはいけない。ただ行って、自分を祭司に見せなさい。そして、人々への証しのため、モーセが命じたように、あなたのきよめのささげ物をしなさい。」'),
('JPN', '路加福音', 42, 5, 15, 'しかし、イエスのうわさはますます広まり、大勢の群衆が話を聞くために、また病気を癒やしてもらうために集まって来た。'),
('JPN', '路加福音', 42, 5, 16, 'だが、イエスご自身は寂しいところに退いて祈っておられた。'),
('JPN', '路加福音', 42, 5, 17, 'ある日のこと、イエスが教えておられると、パリサイ人たちと律法の教師たちが、そこに座っていた。彼らはガリラヤとユダヤのすべての村やエルサレムから来ていた。イエスは主の御力によって、病気を治しておられた。'),
('JPN', '路加福音', 42, 5, 18, 'すると見よ。男たちが、中風をわずらっている人を床に載せて運んで来た。そして家の中に運び込み、イエスの前に置こうとした。'),
('JPN', '路加福音', 42, 5, 19, 'しかし、大勢の人のために病人を運び込む方法が見つからなかったので、屋上に上って瓦をはがし、そこから彼の寝床を、人々の真ん中、イエスの前につり降ろした。'),
('JPN', '路加福音', 42, 5, 20, 'イエスは彼らの信仰を見て、「友よ、あなたの罪は赦された」と言われた。'),
('JPN', '路加福音', 42, 5, 21, 'ところが、律法学者たち、パリサイ人たちはあれこれ考え始めた。「神への冒瀆を口にするこの人は、いったい何者だ。神おひとりのほかに、だれが罪を赦すことができるだろうか。」'),
('JPN', '路加福音', 42, 5, 22, 'イエスは彼らがあれこれ考えているのを見抜いて言われた。「あなたがたは心の中で何を考えているのか。'),
('JPN', '路加福音', 42, 5, 23, '『あなたの罪は赦された』と言うのと、『起きて歩け』と言うのと、どちらが易しいか。'),
('JPN', '路加福音', 42, 5, 24, 'しかし、人の子が地上で罪を赦す権威を持っていることを、あなたがたが知るために──。」そう言って、中風の人に言われた。「あなたに言う。起きなさい。寝床を担いで、家に帰りなさい。」'),
('JPN', '路加福音', 42, 5, 25, 'すると彼はすぐに人々の前で立ち上がり、寝ていた床を担ぎ、神をあがめながら自分の家に帰って行った。'),
('JPN', '路加福音', 42, 5, 26, '人々はみな非常に驚き、神をあがめた。また、恐れに満たされて言った。「私たちは今日、驚くべきことを見た。」'),
('JPN', '路加福音', 42, 5, 27, 'その後、イエスは出て行き、収税所に座っているレビという取税人に目を留められた。そして「わたしについて来なさい」と言われた。'),
('JPN', '路加福音', 42, 5, 28, 'するとレビは、すべてを捨てて立ち上がり、イエスに従った。'),
('JPN', '路加福音', 42, 5, 29, 'それからレビは、自分の家でイエスのために盛大なもてなしをした。取税人たちやほかの人たちが大勢、ともに食卓に着いていた。'),
('JPN', '路加福音', 42, 5, 30, 'すると、パリサイ人たちや彼らのうちの律法学者たちが、イエスの弟子たちに向かって小声で文句を言った。「なぜあなたがたは、取税人たちや罪人たちと一緒に食べたり飲んだりするのですか。」'),
('JPN', '路加福音', 42, 5, 31, 'そこでイエスは彼らに答えられた。「医者を必要とするのは、健康な人ではなく病人です。'),
('JPN', '路加福音', 42, 5, 32, 'わたしが来たのは、正しい人を招くためではなく、罪人を招いて悔い改めさせるためです。」'),
('JPN', '路加福音', 42, 5, 33, 'また彼らはイエスに言った。「ヨハネの弟子たちはよく断食をし、祈りをしています。パリサイ人の弟子たちも同じです。ところが、あなたの弟子たちは食べたり飲んだりしています。」'),
('JPN', '路加福音', 42, 5, 34, 'イエスは彼らに言われた。「花婿が一緒にいるのに、花婿に付き添う友人たちに断食させることが、あなたがたにできますか。'),
('JPN', '路加福音', 42, 5, 35, 'しかし、やがて時が来て、花婿が取り去られたら、その日には彼らは断食します。」'),
('JPN', '路加福音', 42, 5, 36, 'イエスはまた一つのたとえを彼らに話された。「だれも、新しい衣から布切れを引き裂いて、古い衣に継ぎを当てたりはしません。そんなことをすれば、その新しい衣を裂くことになり、新しい衣から取った布切れも古い衣には合いません。'),
('JPN', '路加福音', 42, 5, 37, 'まただれも、新しいぶどう酒を古い皮袋に入れたりはしません。そんなことをすれば、新しいぶどう酒は皮袋を裂き、ぶどう酒が流れ出て、皮袋もだめになります。'),
('JPN', '路加福音', 42, 5, 38, '新しいぶどう酒は、新しい皮袋に入れなければなりません。'),
('JPN', '路加福音', 42, 5, 39, 'まただれも、古いぶどう酒を飲んでから、新しい物を望みはしません。『古い物が良い』と言います。」'),
('JPN', '路加福音', 42, 6, 1, 'ある安息日に、イエスが麦畑を通っておられたときのことである。弟子たちは穂を摘んで、手でもみながら食べていた。'),
('JPN', '路加福音', 42, 6, 2, 'すると、パリサイ人のうちの何人かが言った。「なぜあなたがたは、安息日にしてはならないことをするのですか。」'),
('JPN', '路加福音', 42, 6, 3, 'イエスは彼らに答えられた。「ダビデと供の者たちが空腹になったとき、ダビデが何をしたか、'),
('JPN', '路加福音', 42, 6, 4, 'どのようにして、神の家に入り、祭司以外はだれも食べてはならない臨在のパンを取って食べ、供の者たちにも与えたか、読んだことがないのですか。」'),
('JPN', '路加福音', 42, 6, 5, 'そして彼らに言われた。「人の子は安息日の主です。」'),
('JPN', '路加福音', 42, 6, 6, '別の安息日に、イエスは会堂に入って教えておられた。そこに右手の萎えた人がいた。'),
('JPN', '路加福音', 42, 6, 7, '律法学者たちやパリサイ人たちは、イエスが安息日に癒やしを行うかどうか、じっと見つめていた。彼を訴える口実を見つけるためであった。'),
('JPN', '路加福音', 42, 6, 8, 'イエスは彼らの考えを知っておられた。それで、手の萎えた人に言われた。「立って、真ん中に出なさい。」その人は起き上がり、そこに立った。'),
('JPN', '路加福音', 42, 6, 9, 'イエスは彼らに言われた。「あなたがたに尋ねますが、安息日に律法にかなっているのは、善を行うことですか、それとも悪を行うことですか。いのちを救うことですか、それとも滅ぼすことですか。」'),
('JPN', '路加福音', 42, 6, 10, 'そして彼ら全員を見回してから、その人に「手を伸ばしなさい」と言われた。そのとおりにすると、手は元どおりになった。'),
('JPN', '路加福音', 42, 6, 11, '彼らは怒りに満ち、イエスをどうするか、話し合いを始めた。'),
('JPN', '路加福音', 42, 6, 12, 'そのころ、イエスは祈るために山に行き、神に祈りながら夜を明かされた。'),
('JPN', '路加福音', 42, 6, 13, 'そして、夜が明けると弟子たちを呼び寄せ、その中から十二人を選び、彼らに使徒という名をお与えになった。'),
('JPN', '路加福音', 42, 6, 14, 'すなわち、ペテロという名を与えられたシモンとその兄弟アンデレ、そしてヤコブ、ヨハネ、ピリポ、バルトロマイ、'),
('JPN', '路加福音', 42, 6, 15, 'マタイ、トマス、アルパヨの子ヤコブ、熱心党員と呼ばれていたシモン、'),
('JPN', '路加福音', 42, 6, 16, 'ヤコブの子ユダ、イスカリオテのユダで、このユダが裏切る者となった。'),
('JPN', '路加福音', 42, 6, 17, 'それからイエスは彼らとともに山を下り、平らなところにお立ちになった。大勢の弟子たちの群れや、ユダヤ全土、エルサレム、ツロやシドンの海岸地方から来た、おびただしい数の人々がそこにいた。'),
('JPN', '路加福音', 42, 6, 18, '彼らはイエスの教えを聞くため、また病気を治してもらうために来ていた。汚れた霊に悩まされていた人たちも癒やしてもらっていた。'),
('JPN', '路加福音', 42, 6, 19, '群衆はみな何とかしてイエスにさわろうとしていた。イエスから力が出て、すべての人を癒やしていたからである。'),
('JPN', '路加福音', 42, 6, 20, 'イエスは目を上げて弟子たちを見つめながら、話し始められた。「貧しい人たちは幸いです。神の国はあなたがたのものだからです。'),
('JPN', '路加福音', 42, 6, 21, '今飢えている人たちは幸いです。あなたがたは満ち足りるようになるからです。今泣いている人たちは幸いです。あなたがたは笑うようになるからです。'),
('JPN', '路加福音', 42, 6, 22, '人々があなたがたを憎むとき、人の子のゆえに排除し、ののしり、あなたがたの名を悪しざまにけなすとき、あなたがたは幸いです。'),
('JPN', '路加福音', 42, 6, 23, 'その日には躍り上がって喜びなさい。見なさい。天においてあなたがたの報いは大きいのですから。彼らの先祖たちも、預言者たちに同じことをしたのです。'),
('JPN', '路加福音', 42, 6, 24, 'しかし、富んでいるあなたがたは哀れです。あなたがたは慰めをすでに受けているからです。'),
('JPN', '路加福音', 42, 6, 25, '今満腹しているあなたがたは哀れです。あなたがたは飢えるようになるからです。今笑っているあなたがたは哀れです。あなたがたは泣き悲しむようになるからです。'),
('JPN', '路加福音', 42, 6, 26, '人々がみな、あなたがたをほめるとき、あなたがたは哀れです。彼らの先祖たちも、偽預言者たちに同じことをしたのです。'),
('JPN', '路加福音', 42, 6, 27, 'しかし、これを聞いているあなたがたに、わたしは言います。あなたがたの敵を愛しなさい。あなたがたを憎む者たちに善を行いなさい。'),
('JPN', '路加福音', 42, 6, 28, 'あなたがたを呪う者たちを祝福しなさい。あなたがたを侮辱する者たちのために祈りなさい。'),
('JPN', '路加福音', 42, 6, 29, 'あなたの頬を打つ者には、もう一方の頬も向けなさい。あなたの上着を奪い取る者には、下着も拒んではいけません。'),
('JPN', '路加福音', 42, 6, 30, '求める者には、だれにでも与えなさい。あなたのものを奪い取る者から、取り戻してはいけません。'),
('JPN', '路加福音', 42, 6, 31, '人からしてもらいたいと望むとおりに、人にしなさい。'),
('JPN', '路加福音', 42, 6, 32, '自分を愛してくれる者たちを愛したとしても、あなたがたにどんな恵みがあるでしょうか。罪人たちでも、自分を愛してくれる者たちを愛しています。'),
('JPN', '路加福音', 42, 6, 33, '自分に良いことをしてくれる者たちに良いことをしたとしても、あなたがたにどんな恵みがあるでしょうか。罪人たちでも同じことをしています。'),
('JPN', '路加福音', 42, 6, 34, '返してもらうつもりで人に貸したとしても、あなたがたにどんな恵みがあるでしょうか。罪人たちでも、同じだけ返してもらうつもりで、罪人たちに貸しています。'),
('JPN', '路加福音', 42, 6, 35, 'しかし、あなたがたは自分の敵を愛しなさい。彼らに良くしてやり、返してもらうことを考えずに貸しなさい。そうすれば、あなたがたの受ける報いは多く、あなたがたは、いと高き方の子どもになります。いと高き方は、恩知らずな者にも悪人にもあわれみ深いからです。'),
('JPN', '路加福音', 42, 6, 36, 'あなたがたの父があわれみ深いように、あなたがたも、あわれみ深くなりなさい。'),
('JPN', '路加福音', 42, 6, 37, 'さばいてはいけません。そうすれば、あなたがたもさばかれません。人を不義に定めてはいけません。そうすれば、あなたがたも不義に定められません。赦しなさい。そうすれば、あなたがたも赦されます。'),
('JPN', '路加福音', 42, 6, 38, '与えなさい。そうすれば、あなたがたも与えられます。詰め込んだり、揺すって入れたり、盛り上げたりして、気前良く量って懐に入れてもらえます。あなたがたが量るその秤で、あなたがたも量り返してもらえるからです。」'),
('JPN', '路加福音', 42, 6, 39, 'イエスはまた、彼らに一つのたとえを話された。「盲人が盲人を案内できるでしょうか。二人とも穴に落ち込まないでしょうか。'),
('JPN', '路加福音', 42, 6, 40, '弟子は師以上の者ではありません。しかし、だれでも十分に訓練を受ければ、自分の師のようにはなります。'),
('JPN', '路加福音', 42, 6, 41, 'あなたは、兄弟の目にあるちりは見えるのに、自分自身の目にある梁には、なぜ気がつかないのですか。'),
('JPN', '路加福音', 42, 6, 42, 'あなた自身、自分の目にある梁が見えていないのに、兄弟に対して『兄弟、あなたの目のちりを取り除かせてください』と、どうして言えるのですか。偽善者よ、まず自分の目から梁を取り除きなさい。そうすれば、兄弟の目のちりがはっきり見えるようになって、取り除くことができます。'),
('JPN', '路加福音', 42, 6, 43, '良い木が悪い実を結ぶことはなく、悪い木が良い実を結ぶこともありません。'),
('JPN', '路加福音', 42, 6, 44, '木はそれぞれ、その実によって分かります。茨からいちじくを採ることはなく、野ばらからぶどうを摘むこともありません。'),
('JPN', '路加福音', 42, 6, 45, '良い人は、その心の良い倉から良い物を出し、悪い人は、悪い倉から悪い物を出します。人の口は、心に満ちていることを話すからです。'),
('JPN', '路加福音', 42, 6, 46, 'なぜあなたがたは、わたしを『主よ、主よ』と呼びながら、わたしの言うことを行わないのですか。'),
('JPN', '路加福音', 42, 6, 47, 'わたしのもとに来て、わたしのことばを聞き、それを行う人がみな、どんな人に似ているか、あなたがたに示しましょう。'),
('JPN', '路加福音', 42, 6, 48, 'その人は、地面を深く掘り下げ、岩の上に土台を据えて、家を建てた人に似ています。洪水になり、川の水がその家に押し寄せても、しっかり建てられていたので、びくともしませんでした。'),
('JPN', '路加福音', 42, 6, 49, 'しかし、聞いても行わない人は、土台なしで地面に家を建てた人に似ています。川の水が押し寄せると、家はすぐに倒れてしまい、その壊れ方はひどいものでした。」'),
('JPN', '路加福音', 42, 7, 1, 'イエスは、耳を傾けている人々にこれらのことばをすべて話し終えると、カペナウムに入られた。'),
('JPN', '路加福音', 42, 7, 2, '時に、ある百人隊長に重んじられていた一人のしもべが、病気で死にかけていた。'),
('JPN', '路加福音', 42, 7, 3, '百人隊長はイエスのことを聞き、みもとにユダヤ人の長老たちを送って、自分のしもべを助けに来てくださいとお願いした。'),
('JPN', '路加福音', 42, 7, 4, 'イエスのもとに来たその人たちは、熱心にお願いして言った。「この人は、あなたにそうしていただく資格のある人です。'),
('JPN', '路加福音', 42, 7, 5, '私たちの国民を愛し、私たちのために自ら会堂を建ててくれました。」'),
('JPN', '路加福音', 42, 7, 6, 'そこで、イエスは彼らと一緒に行かれた。ところが、百人隊長の家からあまり遠くないところまで来たとき、百人隊長は友人たちを使いに出して、イエスにこう伝えた。「主よ、わざわざ、ご足労くださるには及びません。あなた様を、私のような者の家の屋根の下にお入れする資格はありませんので。'),
('JPN', '路加福音', 42, 7, 7, 'ですから、私自身があなた様のもとに伺うのも、ふさわしいとは思いませんでした。ただ、おことばを下さい。そうして私のしもべを癒やしてください。'),
('JPN', '路加福音', 42, 7, 8, 'と申しますのは、私も権威の下に置かれている者だからです。私自身の下にも兵士たちがいて、その一人に『行け』と言えば行きますし、別の者に『来い』と言えば来ます。また、しもべに『これをしろ』と言えば、そのようにします。」'),
('JPN', '路加福音', 42, 7, 9, 'イエスはこれを聞いて驚き、振り向いて、ついて来ていた群衆に言われた。「あなたがたに言いますが、わたしはイスラエルのうちでも、これほどの信仰を見たことがありません。」'),
('JPN', '路加福音', 42, 7, 10, '使いに送られた人たちが家に戻ると、そのしもべは良くなっていた。'),
('JPN', '路加福音', 42, 7, 11, 'それから間もなく、イエスはナインという町に行かれた。弟子たちと大勢の群衆も一緒に行った。'),
('JPN', '路加福音', 42, 7, 12, 'イエスが町の門に近づかれると、見よ、ある母親の一人息子が、死んで担ぎ出されるところであった。その母親はやもめで、その町の人々が大勢、彼女に付き添っていた。'),
('JPN', '路加福音', 42, 7, 13, '主はその母親を見て深くあわれみ、「泣かなくてもよい」と言われた。'),
('JPN', '路加福音', 42, 7, 14, 'そして近寄って棺に触れられると、担いでいた人たちは立ち止まった。イエスは言われた。「若者よ、あなたに言う。起きなさい。」'),
('JPN', '路加福音', 42, 7, 15, 'すると、その死人が起き上がって、ものを言い始めた。イエスは彼を母親に返された。'),
('JPN', '路加福音', 42, 7, 16, '人々はみな恐れを抱き、「偉大な預言者が私たちのうちに現れた」とか、「神がご自分の民を顧みてくださった」と言って、神をあがめた。'),
('JPN', '路加福音', 42, 7, 17, 'イエスについてのこの話は、ユダヤ全土と周辺の地域一帯に広まった。'),
('JPN', '路加福音', 42, 7, 18, 'さて、ヨハネの弟子たちは、これらのことをすべてヨハネに報告した。すると、ヨハネは弟子たちの中から二人の者を呼んで、'),
('JPN', '路加福音', 42, 7, 19, 'こう言づけて、主のもとに送り出した。「おいでになるはずの方は、あなたですか。それとも、ほかの方を待つべきでしょうか。」'),
('JPN', '路加福音', 42, 7, 20, 'その人たちはみもとに来て言った。「私たちはバプテスマのヨハネから遣わされて、ここに参りました。『おいでになるはずの方は、あなたですか。それとも、ほかの方を待つべきでしょうか』と、ヨハネが申しております。」'),
('JPN', '路加福音', 42, 7, 21, 'ちょうどそのころ、イエスは病気や苦しみや悪霊に悩む多くの人たちを癒やし、また目の見えない多くの人たちを見えるようにしておられた。'),
('JPN', '路加福音', 42, 7, 22, 'イエスは彼らにこう答えられた。「あなたがたは行って、自分たちが見たり聞いたりしたことをヨハネに伝えなさい。目の見えない者たちが見、足の不自由な者たちが歩き、ツァラアトに冒された者たちがきよめられ、耳の聞こえない者たちが聞き、死人たちが生き返り、貧しい者たちに福音が伝えられています。'),
('JPN', '路加福音', 42, 7, 23, 'だれでも、わたしにつまずかない者は幸いです。」'),
('JPN', '路加福音', 42, 7, 24, 'ヨハネの使いが帰ってから、イエスはヨハネについて群衆に話し始められた。「あなたがたは、何を見に荒野に出て行ったのですか。風に揺れる葦ですか。'),
('JPN', '路加福音', 42, 7, 25, 'では、何を見に行ったのですか。柔らかな衣をまとった人ですか。ご覧なさい。きらびやかな服を着て、ぜいたくに暮らしている人たちなら宮殿にいます。'),
('JPN', '路加福音', 42, 7, 26, 'では、何を見に行ったのですか。預言者ですか。そのとおり。わたしはあなたがたに言います。預言者よりもすぐれた者をです。'),
('JPN', '路加福音', 42, 7, 27, 'この人こそ、『見よ、わたしはわたしの使いをあなたの前に遣わす。彼は、あなたの前にあなたの道を備える』と書かれているその人です。'),
('JPN', '路加福音', 42, 7, 28, 'わたしはあなたがたに言います。女から生まれた者の中で、ヨハネよりも偉大な者はだれもいません。しかし、神の国で一番小さい者でさえ、彼より偉大です。'),
('JPN', '路加福音', 42, 7, 29, 'ヨハネの教えを聞いた民はみな、取税人たちでさえ彼からバプテスマを受けて、神が正しいことを認めました。'),
('JPN', '路加福音', 42, 7, 30, 'ところが、パリサイ人たちや律法の専門家たちは、彼からバプテスマを受けず、自分たちに対する神のみこころを拒みました。'),
('JPN', '路加福音', 42, 7, 31, 'それでは、この時代の人々を何にたとえたらよいでしょうか。彼らは何に似ているでしょうか。'),
('JPN', '路加福音', 42, 7, 32, '広場に座り、互いに呼びかけながら、こう言っている子どもたちに似ています。『笛を吹いてあげたのに、君たちは踊らなかった。弔いの歌を歌ってあげたのに、泣かなかった。』'),
('JPN', '路加福音', 42, 7, 33, 'バプテスマのヨハネが来て、パンも食べず、ぶどう酒も飲まずにいると、あなたがたは『あれは悪霊につかれている』と言い、'),
('JPN', '路加福音', 42, 7, 34, '人の子が来て食べたり飲んだりしていると、『見ろ、大食いの大酒飲み、取税人や罪人の仲間だ』と言います。'),
('JPN', '路加福音', 42, 7, 35, 'しかし、知恵が正しいことは、すべての知恵の子らが証明します。」'),
('JPN', '路加福音', 42, 7, 36, 'さて、あるパリサイ人が一緒に食事をしたいとイエスを招いたので、イエスはそのパリサイ人の家に入って食卓に着かれた。'),
('JPN', '路加福音', 42, 7, 37, 'すると見よ。その町に一人の罪深い女がいて、イエスがパリサイ人の家で食卓に着いておられることを知り、香油の入った石膏の壺を持って来た。'),
('JPN', '路加福音', 42, 7, 38, 'そしてうしろからイエスの足もとに近寄り、泣きながらイエスの足を涙でぬらし始め、髪の毛でぬぐい、その足に口づけして香油を塗った。'),
('JPN', '路加福音', 42, 7, 39, 'イエスを招いたパリサイ人はこれを見て、「この人がもし預言者だったら、自分にさわっている女がだれで、どんな女であるか知っているはずだ。この女は罪深いのだから」と心の中で思っていた。'),
('JPN', '路加福音', 42, 7, 40, 'するとイエスは彼に向かって、「シモン、あなたに言いたいことがあります」と言われた。シモンは、「先生、お話しください」と言った。'),
('JPN', '路加福音', 42, 7, 41, '「ある金貸しから、二人の人が金を借りていた。一人は五百デナリ、もう一人は五十デナリ。'),
('JPN', '路加福音', 42, 7, 42, '彼らは返すことができなかったので、金貸しは二人とも借金を帳消しにしてやった。それでは、二人のうちのどちらが、金貸しをより多く愛するようになるでしょうか。」'),
('JPN', '路加福音', 42, 7, 43, 'シモンが「より多くを帳消しにしてもらったほうだと思います」と答えると、イエスは「あなたの判断は正しい」と言われた。'),
('JPN', '路加福音', 42, 7, 44, 'それから彼女の方を向き、シモンに言われた。「この人を見ましたか。わたしがあなたの家に入って来たとき、あなたは足を洗う水をくれなかったが、彼女は涙でわたしの足をぬらし、自分の髪の毛でぬぐってくれました。'),
('JPN', '路加福音', 42, 7, 45, 'あなたは口づけしてくれなかったが、彼女は、わたしが入って来たときから、わたしの足に口づけしてやめませんでした。'),
('JPN', '路加福音', 42, 7, 46, 'あなたはわたしの頭にオリーブ油を塗ってくれなかったが、彼女は、わたしの足に香油を塗ってくれました。'),
('JPN', '路加福音', 42, 7, 47, 'ですから、わたしはあなたに言います。この人は多くの罪を赦されています。彼女は多く愛したのですから。赦されることの少ない者は、愛することも少ないのです。」'),
('JPN', '路加福音', 42, 7, 48, 'そして彼女に、「あなたの罪は赦されています」と言われた。'),
('JPN', '路加福音', 42, 7, 49, 'すると、ともに食卓に着いていた人たちは、自分たちの間で言い始めた。「罪を赦すことさえするこの人は、いったいだれなのか。」'),
('JPN', '路加福音', 42, 7, 50, 'イエスは彼女に言われた。「あなたの信仰があなたを救ったのです。安心して行きなさい。」'),
('JPN', '路加福音', 42, 8, 1, 'その後、イエスは町や村を巡って神の国を説き、福音を宣べ伝えられた。十二人もお供をした。'),
('JPN', '路加福音', 42, 8, 2, 'また、悪霊や病気を治してもらった女たち、すなわち、七つの悪霊を追い出してもらったマグダラの女と呼ばれるマリア、'),
('JPN', '路加福音', 42, 8, 3, 'ヘロデの執事クーザの妻ヨハンナ、スザンナ、そのほか多くの女たちも一緒であった。彼女たちは、自分の財産をもって彼らに仕えていた。'),
('JPN', '路加福音', 42, 8, 4, 'さて、大勢の群衆が集まり、方々の町から人々がみもとにやって来たので、イエスはたとえを用いて話された。'),
('JPN', '路加福音', 42, 8, 5, '「種を蒔く人が種蒔きに出かけた。蒔いていると、ある種が道端に落ちた。すると、人に踏みつけられ、空の鳥が食べてしまった。'),
('JPN', '路加福音', 42, 8, 6, 'また、別の種は岩の上に落ちた。生長したが、水分がなかったので枯れてしまった。'),
('JPN', '路加福音', 42, 8, 7, 'また、別の種は茨の真ん中に落ちた。すると、茨も一緒に生え出てふさいでしまった。'),
('JPN', '路加福音', 42, 8, 8, 'また、別の種は良い地に落ち、生長して百倍の実を結んだ。」イエスはこれらのことを話しながら、大声で言われた。「聞く耳のある者は聞きなさい。」'),
('JPN', '路加福音', 42, 8, 9, '弟子たちは、このたとえがどういう意味なのか、イエスに尋ねた。'),
('JPN', '路加福音', 42, 8, 10, 'イエスは言われた。「あなたがたには神の国の奥義を知ることが許されていますが、ほかの人たちには、たとえで話します。『彼らが見ていても見ることがなく、聞いていても悟ることがないように』するためです。'),
('JPN', '路加福音', 42, 8, 11, 'このたとえの意味はこうです。種は神のことばです。'),
('JPN', '路加福音', 42, 8, 12, '道端に落ちたものとは、みことばを聞いても信じて救われないように、後で悪魔が来て、その心からみことばを取り去ってしまう、そのような人たちのことです。'),
('JPN', '路加福音', 42, 8, 13, '岩の上に落ちたものとは、みことばを聞くと喜んで受け入れるのですが、根がないので、しばらくは信じていても試練のときに身を引いてしまう、そのような人たちのことです。'),
('JPN', '路加福音', 42, 8, 14, '茨の中に落ちたものとは、こういう人たちのことです。彼らはみことばを聞いたのですが、時がたつにつれ、生活における思い煩いや、富や、快楽でふさがれて、実が熟すまでになりません。'),
('JPN', '路加福音', 42, 8, 15, 'しかし、良い地に落ちたものとは、こういう人たちのことです。彼らは立派な良い心でみことばを聞いて、それをしっかり守り、忍耐して実を結びます。'),
('JPN', '路加福音', 42, 8, 16, '明かりをつけてから、それを器で隠したり、寝台の下に置いたりする人はいません。燭台の上に置いて、入って来た人たちに光が見えるようにします。'),
('JPN', '路加福音', 42, 8, 17, '隠れているもので、あらわにされないものはなく、秘められたもので知られないもの、明らかにされないものはありません。'),
('JPN', '路加福音', 42, 8, 18, 'ですから、聞き方に注意しなさい。というのは、持っている人はさらに与えられ、持っていない人は、持っていると思っているものまで取り上げられるからです。」'),
('JPN', '路加福音', 42, 8, 19, 'さて、イエスのところに母と兄弟たちが来たが、大勢の人のためにそばに近寄れなかった。'),
('JPN', '路加福音', 42, 8, 20, 'それでイエスに、「母上と兄弟方が、お会いしたいと外に立っておられます」という知らせがあった。'),
('JPN', '路加福音', 42, 8, 21, 'しかし、イエスはその人たちにこう答えられた。「わたしの母、わたしの兄弟たちとは、神のことばを聞いて行う人たちのことです。」'),
('JPN', '路加福音', 42, 8, 22, 'ある日のことであった。イエスは弟子たちと一緒に舟に乗り、「湖の向こう岸へ渡ろう」と言われたので、弟子たちは舟を出した。'),
('JPN', '路加福音', 42, 8, 23, '舟で渡っている間に、イエスは眠り始められた。ところが突風が湖に吹きおろして来たので、彼らは水をかぶって危険になった。'),
('JPN', '路加福音', 42, 8, 24, 'そこで弟子たちは近寄ってイエスを起こし、「先生、先生、私たちは死んでしまいます」と言った。イエスは起き上がり、風と荒波を叱りつけられた。すると静まり、凪になった。'),
('JPN', '路加福音', 42, 8, 25, 'イエスは彼らに対して、「あなたがたの信仰はどこにあるのですか」と言われた。弟子たちは驚き恐れて互いに言った。「お命じになると、風や水までが従うとは、いったいこの方はどういう方なのだろうか。」'),
('JPN', '路加福音', 42, 8, 26, 'こうして彼らは、舟で、ガリラヤの反対側にあるゲラサ人の地に着いた。'),
('JPN', '路加福音', 42, 8, 27, 'イエスが陸に上がられると、その町の者で、悪霊につかれている男がイエスを迎えた。彼は長い間、服を身に着けず、家に住まないで墓場に住んでいた。'),
('JPN', '路加福音', 42, 8, 28, '彼はイエスを見ると叫び声をあげ、御前にひれ伏して大声で言った。「いと高き神の子イエスよ、私とあなたに何の関係があるのですか。お願いです。私を苦しめないでください。」'),
('JPN', '路加福音', 42, 8, 29, 'それは、イエスが汚れた霊に、この人から出て行くように命じられたからであった。汚れた霊はこの人を何回も捕らえていた。それで彼は鎖と足かせでつながれて監視されていたが、それらを断ち切っては、悪霊によって荒野に駆り立てられていた。'),
('JPN', '路加福音', 42, 8, 30, 'イエスが「おまえの名は何か」とお尋ねになると、彼は「レギオンです」と答えた。悪霊が大勢彼に入っていたからである。'),
('JPN', '路加福音', 42, 8, 31, '悪霊どもはイエスに、底知れぬ所に行けと自分たちにお命じにならないようにと懇願した。'),
('JPN', '路加福音', 42, 8, 32, 'ちょうど、そのあたりの山に、たくさんの豚の群れが飼われていたので、悪霊どもは、その豚に入ることを許してくださいと懇願した。イエスはそれを許された。'),
('JPN', '路加福音', 42, 8, 33, '悪霊どもはその人から出て、豚に入った。すると豚の群れは崖を下って湖へなだれ込み、おぼれて死んだ。'),
('JPN', '路加福音', 42, 8, 34, '飼っていた人たちは、この出来事を見て逃げ出し、町や里でこのことを伝えた。'),
('JPN', '路加福音', 42, 8, 35, '人々は、起こったことを見ようと出て来た。そしてイエスのところに来て、イエスの足もとに、悪霊の去った男が服を着て、正気に返って座っているのを見た。それで恐ろしくなった。'),
('JPN', '路加福音', 42, 8, 36, '見ていた人たちは、悪霊につかれていた人がどのように救われたか、人々に知らせた。'),
('JPN', '路加福音', 42, 8, 37, 'ゲラサ周辺の人々はみな、イエスに、自分たちのところから出て行ってほしいと願った。非常な恐れに取りつかれていたからであった。それで、イエスが舟に乗って帰ろうとされると、'),
('JPN', '路加福音', 42, 8, 38, '悪霊が去ったその人は、お供をしたいとしきりに願った。しかし、イエスはこう言って彼を帰された。'),
('JPN', '路加福音', 42, 8, 39, '「あなたの家に帰って、神があなたにしてくださったことをすべて、話して聞かせなさい。」それで彼は立ち去って、イエスが自分にしてくださったことをすべて、町中に言い広めた。'),
('JPN', '路加福音', 42, 8, 40, 'さて、イエスが帰って来られると、群衆は喜んで迎えた。みなイエスを待ちわびていたのである。'),
('JPN', '路加福音', 42, 8, 41, 'すると見よ、ヤイロという人がやって来た。この人は会堂司であった。彼はイエスの足もとにひれ伏して、自分の家に来ていただきたいと懇願した。'),
('JPN', '路加福音', 42, 8, 42, '彼には十二歳ぐらいの一人娘がいて、死にかけていたのであった。それでイエスが出かけられると、群衆はイエスに押し迫って来た。'),
('JPN', '路加福音', 42, 8, 43, 'そこに、十二年の間、長血をわずらい、医者たちに財産すべてを費やしたのに、だれにも治してもらえなかった女の人がいた。'),
('JPN', '路加福音', 42, 8, 44, '彼女はイエスのうしろから近づいて、その衣の房に触れた。すると、ただちに出血が止まった。'),
('JPN', '路加福音', 42, 8, 45, 'イエスは、「わたしにさわったのは、だれですか」と言われた。みな自分ではないと言ったので、ペテロは、「先生。大勢の人たちが、あなたを囲んで押し合っています」と言った。'),
('JPN', '路加福音', 42, 8, 46, 'しかし、イエスは言われた。「だれかがわたしにさわりました。わたし自身、自分から力が出て行くのを感じました。」'),
('JPN', '路加福音', 42, 8, 47, '彼女は隠しきれないと知って、震えながら進み出て御前にひれ伏し、イエスにさわった理由と、ただちに癒やされた次第を、すべての民の前で話した。'),
('JPN', '路加福音', 42, 8, 48, 'イエスは彼女に言われた。「娘よ、あなたの信仰があなたを救ったのです。安心して行きなさい。」'),
('JPN', '路加福音', 42, 8, 49, 'イエスがまだ話しておられるとき、会堂司の家から人が来て言った。「お嬢さんは亡くなりました。もう、先生を煩わすことはありません。」'),
('JPN', '路加福音', 42, 8, 50, 'これを聞いて、イエスは答えられた。「恐れないで、ただ信じなさい。そうすれば、娘は救われます。」'),
('JPN', '路加福音', 42, 8, 51, 'イエスは家に着いたが、ペテロ、ヨハネ、ヤコブ、そしてその子の父と母のほかは、だれも一緒に入ることをお許しにならなかった。'),
('JPN', '路加福音', 42, 8, 52, '人々はみな、少女のために泣き悲しんでいた。しかし、イエスは言われた。「泣かなくてよい。死んだのではなく、眠っているのです。」'),
('JPN', '路加福音', 42, 8, 53, '人々は、少女が死んだことを知っていたので、イエスをあざ笑った。'),
('JPN', '路加福音', 42, 8, 54, 'しかし、イエスは少女の手を取って叫ばれた。「子よ、起きなさい。」'),
('JPN', '路加福音', 42, 8, 55, 'すると少女の霊が戻って、少女はただちに起き上がった。それでイエスは、その子に食べ物を与えるように命じられた。'),
('JPN', '路加福音', 42, 8, 56, '両親が驚いていると、イエスは、この出来事をだれにも話さないように命じられた。'),
('JPN', '路加福音', 42, 9, 1, 'イエスは十二人を呼び集めて、すべての悪霊を制して病気を癒やす力と権威を、彼らにお授けになった。'),
('JPN', '路加福音', 42, 9, 2, 'そして、神の国を宣べ伝え、病人を治すために、こう言って彼らを遣わされた。'),
('JPN', '路加福音', 42, 9, 3, '「旅には何も持って行かないようにしなさい。杖も袋もパンも金もです。また下着も、それぞれ二枚持ってはいけません。'),
('JPN', '路加福音', 42, 9, 4, 'どの家に入っても、そこにとどまり、そこから出かけなさい。'),
('JPN', '路加福音', 42, 9, 5, '人々があなたがたを受け入れないなら、その町を出て行くときに、彼らに対する証言として、足のちりを払い落としなさい。」'),
('JPN', '路加福音', 42, 9, 6, '十二人は出て行って、村から村へと巡りながら、いたるところで福音を宣べ伝え、癒やしを行った。'),
('JPN', '路加福音', 42, 9, 7, 'さて、領主ヘロデはこのすべての出来事を聞いて、ひどく当惑していた。ある人たちは、「ヨハネが死人の中からよみがえったのだ」と言い、'),
('JPN', '路加福音', 42, 9, 8, '別の人たちは、「エリヤが現れたのだ」と言い、さらに別の人たちは、「昔の預言者の一人が生き返ったのだ」と言っていたからである。'),
('JPN', '路加福音', 42, 9, 9, 'ヘロデは言った。「ヨハネは私が首をはねた。このようなうわさがあるこの人は、いったいだれなのだろうか。」ヘロデはイエスに会ってみたいと思った。'),
('JPN', '路加福音', 42, 9, 10, 'さて、使徒たちは帰って来て、自分たちがしたことをすべて報告した。それからイエスは彼らを連れて、ベツサイダという町へひそかに退かれた。'),
('JPN', '路加福音', 42, 9, 11, 'ところが、それを知った群衆がイエスの後について来た。イエスは彼らを喜んで迎え、神の国のことを話し、また、癒やしを必要とする人たちを治された。'),
('JPN', '路加福音', 42, 9, 12, '日が傾き始めたので、十二人はみもとに来て言った。「群衆を解散させてください。そうすれば、彼らは周りの村や里に行き、宿をとり、何か食べることができるでしょう。私たちは、このような寂しいところにいるのですから。」'),
('JPN', '路加福音', 42, 9, 13, 'すると、イエスは彼らに言われた。「あなたがたが、あの人たちに食べる物をあげなさい。」彼らは言った。「私たちには五つのパンと二匹の魚しかありません。私たちが出かけて行って、この民全員のために食べ物を買うのでしょうか。」'),
('JPN', '路加福音', 42, 9, 14, 'というのは、男だけでおよそ五千人もいたからである。しかし、イエスは弟子たちに言われた。「人々を、五十人ぐらいずつ組にして座らせなさい。」'),
('JPN', '路加福音', 42, 9, 15, '弟子たちはそのとおりにして、全員を座らせた。'),
('JPN', '路加福音', 42, 9, 16, 'そこでイエスは、五つのパンと二匹の魚を取り、天を見上げ、それらのゆえに神をほめたたえてそれを裂き、群衆に配るように弟子たちにお与えになった。'),
('JPN', '路加福音', 42, 9, 17, '人々はみな、食べて満腹した。そして余ったパン切れを集めると、十二かごあった。'),
('JPN', '路加福音', 42, 9, 18, 'さて、イエスが一人で祈っておられたとき、弟子たちも一緒にいた。イエスは彼らにお尋ねになった。「群衆はわたしのことをだれだと言っていますか。」'),
('JPN', '路加福音', 42, 9, 19, '彼らは答えた。「バプテスマのヨハネだと言っています。エリヤだと言う人たち、昔の預言者の一人が生き返ったのだと言う人たちもいます。」'),
('JPN', '路加福音', 42, 9, 20, 'イエスは彼らに言われた。「あなたがたは、わたしをだれだと言いますか。」ペテロが答えた。「神のキリストです。」'),
('JPN', '路加福音', 42, 9, 21, 'するとイエスは弟子たちを戒め、このことをだれにも話さないように命じられた。'),
('JPN', '路加福音', 42, 9, 22, 'そして、人の子は多くの苦しみを受け、長老たち、祭司長たち、律法学者たちに捨てられ、殺され、三日目によみがえらなければならない、と語られた。'),
('JPN', '路加福音', 42, 9, 23, 'イエスは皆に言われた。「だれでもわたしについて来たいと思うなら、自分を捨て、日々自分の十字架を負って、わたしに従って来なさい。'),
('JPN', '路加福音', 42, 9, 24, '自分のいのちを救おうと思う者はそれを失い、わたしのためにいのちを失う者は、それを救うのです。'),
('JPN', '路加福音', 42, 9, 25, '人は、たとえ全世界を手に入れても、自分自身を失い、損じたら、何の益があるでしょうか。'),
('JPN', '路加福音', 42, 9, 26, 'だれでも、わたしとわたしのことばを恥じるなら、人の子もまた、自分と父と聖なる御使いの栄光を帯びてやって来るとき、その人を恥じます。'),
('JPN', '路加福音', 42, 9, 27, 'まことに、あなたがたに言います。ここに立っている人たちの中には、神の国を見るまで、決して死を味わわない人たちがいます。」'),
('JPN', '路加福音', 42, 9, 28, 'これらのことを教えてから八日ほどして、イエスはペテロとヨハネとヤコブを連れて、祈るために山に登られた。'),
('JPN', '路加福音', 42, 9, 29, '祈っておられると、その御顔の様子が変わり、その衣は白く光り輝いた。'),
('JPN', '路加福音', 42, 9, 30, 'そして、見よ、二人の人がイエスと語り合っていた。それはモーセとエリヤで、'),
('JPN', '路加福音', 42, 9, 31, '栄光のうちに現れ、イエスがエルサレムで遂げようとしておられる最期について、話していたのであった。'),
('JPN', '路加福音', 42, 9, 32, 'ペテロと仲間たちは眠くてたまらなかったが、はっきり目が覚めると、イエスの栄光と、イエスと一緒に立っている二人の人が見えた。'),
('JPN', '路加福音', 42, 9, 33, 'この二人がイエスと別れようとしたとき、ペテロがイエスに言った。「先生。私たちがここにいることはすばらしいことです。幕屋を三つ造りましょう。一つはあなたのために、一つはモーセのために、一つはエリヤのために。」ペテロは自分の言っていることが分かっていなかった。'),
('JPN', '路加福音', 42, 9, 34, 'ペテロがこう言っているうちに、雲がわき起こって彼らをおおった。彼らが雲の中に入ると、弟子たちは恐ろしくなった。'),
('JPN', '路加福音', 42, 9, 35, 'すると雲の中から言う声がした。「これはわたしの選んだ子。彼の言うことを聞け。」'),
('JPN', '路加福音', 42, 9, 36, 'この声がしたとき、そこに見えたのはイエスだけであった。弟子たちは沈黙を守り、当時は自分たちの見たことをいっさい、だれにも話さなかった。'),
('JPN', '路加福音', 42, 9, 37, '次の日、一行が山から下りて来ると、大勢の群衆がイエスを迎えた。'),
('JPN', '路加福音', 42, 9, 38, 'すると見よ、群衆の中から、一人の人が叫んで言った。「先生、お願いします。息子を見てやってください。私の一人息子です。'),
('JPN', '路加福音', 42, 9, 39, 'ご覧ください。霊がこの子に取りつくと、突然叫びます。そして、引きつけを起こさせて泡を吹かせ、打ちのめして、なかなか離れようとしません。'),
('JPN', '路加福音', 42, 9, 40, 'あなたのお弟子たちに、霊を追い出してくださいとお願いしたのですが、できませんでした。」'),
('JPN', '路加福音', 42, 9, 41, 'イエスは答えられた。「ああ、不信仰な曲がった時代だ。いつまで、わたしはあなたがたと一緒にいて、あなたがたに我慢しなければならないのか。あなたの子をここに連れて来なさい。」'),
('JPN', '路加福音', 42, 9, 42, 'その子が来る途中でも、悪霊は彼を倒して引きつけを起こさせた。しかし、イエスは汚れた霊を叱り、その子を癒やして父親に渡された。'),
('JPN', '路加福音', 42, 9, 43, '人々はみな、神の偉大さに驚嘆した。イエスがなさったすべてのことに人々がみな驚いていると、イエスは弟子たちにこう言われた。'),
('JPN', '路加福音', 42, 9, 44, '「あなたがたは、これらのことばを自分の耳に入れておきなさい。人の子は、人々の手に渡されようとしています。」'),
('JPN', '路加福音', 42, 9, 45, 'しかし、弟子たちには、このことばが理解できなかった。彼らには分からないように、彼らから隠されていたのであった。彼らは、このことばについてイエスに尋ねるのを恐れていた。'),
('JPN', '路加福音', 42, 9, 46, 'さて、弟子たちの間で、だれが一番偉いかという議論が持ち上がった。'),
('JPN', '路加福音', 42, 9, 47, 'しかし、イエスは彼らの心にある考えを知り、一人の子どもの手を取って、自分のそばに立たせ、'),
('JPN', '路加福音', 42, 9, 48, '彼らに言われた。「だれでも、このような子どもを、わたしの名のゆえに受け入れる人は、わたしを受け入れるのです。また、だれでもわたしを受け入れる人は、わたしを遣わされた方を受け入れるのです。あなたがた皆の中で一番小さい者が、一番偉いのです。」'),
('JPN', '路加福音', 42, 9, 49, 'さて、ヨハネが言った。「先生。あなたの名によって悪霊を追い出している人を見たので、やめさせようとしました。その人が私たちについて来なかったからです。」'),
('JPN', '路加福音', 42, 9, 50, 'しかし、イエスは彼に言われた。「やめさせてはいけません。あなたがたに反対しない人は、あなたがたの味方です。」'),
('JPN', '路加福音', 42, 9, 51, 'さて、天に上げられる日が近づいて来たころのことであった。イエスは御顔をエルサレムに向け、毅然として進んで行かれた。'),
('JPN', '路加福音', 42, 9, 52, 'そして、ご自分の前に使いを送り出された。彼らは行ってサマリア人の村に入り、イエスのために備えをした。'),
('JPN', '路加福音', 42, 9, 53, 'しかし、イエスが御顔をエルサレムに向けて進んでおられたので、サマリア人はイエスを受け入れなかった。'),
('JPN', '路加福音', 42, 9, 54, '弟子のヤコブとヨハネが、これを見て言った。「主よ。私たちが天から火を下して、彼らを焼き滅ぼしましょうか。」'),
('JPN', '路加福音', 42, 9, 55, 'しかし、イエスは振り向いて二人を叱られた。'),
('JPN', '路加福音', 42, 9, 56, 'そして一行は別の村に行った。'),
('JPN', '路加福音', 42, 9, 57, '彼らが道を進んで行くと、ある人がイエスに言った。「あなたがどこに行かれても、私はついて行きます。」'),
('JPN', '路加福音', 42, 9, 58, 'イエスは彼に言われた。「狐には穴があり、空の鳥には巣があるが、人の子には枕するところもありません。」'),
('JPN', '路加福音', 42, 9, 59, 'イエスは別の人に、「わたしに従って来なさい」と言われた。しかし、その人は言った。「まず行って、父を葬ることをお許しください。」'),
('JPN', '路加福音', 42, 9, 60, 'イエスは彼に言われた。「死人たちに、彼ら自身の死人たちを葬らせなさい。あなたは出て行って、神の国を言い広めなさい。」'),
('JPN', '路加福音', 42, 9, 61, 'また、別の人が言った。「主よ、あなたに従います。ただ、まず自分の家の者たちに、別れを告げることをお許しください。」'),
('JPN', '路加福音', 42, 9, 62, 'すると、イエスは彼に言われた。「鋤に手をかけてからうしろを見る者はだれも、神の国にふさわしくありません。」'),
('JPN', '路加福音', 42, 10, 1, 'その後、主は別に七十二人を指名して、ご自分が行くつもりのすべての町や場所に、先に二人ずつ遣わされた。'),
('JPN', '路加福音', 42, 10, 2, 'そして彼らに言われた。「収穫は多いが、働き手が少ない。だから、収穫の主に、ご自分の収穫のために働き手を送ってくださるように祈りなさい。'),
('JPN', '路加福音', 42, 10, 3, 'さあ、行きなさい。いいですか。わたしがあなたがたを遣わすのは、狼の中に子羊を送り出すようなものです。'),
('JPN', '路加福音', 42, 10, 4, '財布も袋も持たず、履き物もはかずに行きなさい。道でだれにもあいさつしてはいけません。'),
('JPN', '路加福音', 42, 10, 5, 'どの家に入っても、まず、『この家に平安があるように』と言いなさい。'),
('JPN', '路加福音', 42, 10, 6, 'そこに平安の子がいたら、あなたがたの平安は、その人の上にとどまります。いなければ、その平安はあなたがたに返って来ます。'),
('JPN', '路加福音', 42, 10, 7, 'その家にとどまり、出される物を食べたり飲んだりしなさい。働く者が報酬を受けるのは当然だからです。家から家へと渡り歩いてはいけません。'),
('JPN', '路加福音', 42, 10, 8, 'どの町に入っても、人々があなたがたを受け入れてくれたら、出された物を食べなさい。'),
('JPN', '路加福音', 42, 10, 9, 'そして、その町の病人を癒やし、彼らに『神の国があなたがたの近くに来ている』と言いなさい。'),
('JPN', '路加福音', 42, 10, 10, 'しかし、どの町であれ、人々があなたがたを受け入れないなら、大通りに出て言いなさい。'),
('JPN', '路加福音', 42, 10, 11, '『私たちは、足に付いたこの町のちりさえ、おまえたちに払い落として行く。しかし、神の国が近づいたことは知っておきなさい。』'),
('JPN', '路加福音', 42, 10, 12, 'あなたがたに言います。その日には、ソドムのほうが、その町よりもさばきに耐えやすいのです。'),
('JPN', '路加福音', 42, 10, 13, 'ああ、コラジン。ああ、ベツサイダ。おまえたちの間で行われた力あるわざが、ツロとシドンで行われていたら、彼らはとうの昔に粗布をまとい、灰をかぶって座り、悔い改めていたことだろう。'),
('JPN', '路加福音', 42, 10, 14, 'しかし、さばきのときには、ツロとシドンのほうが、おまえたちよりもさばきに耐えやすいのだ。'),
('JPN', '路加福音', 42, 10, 15, 'カペナウム、おまえが天に上げられることがあるだろうか。よみにまで落とされるのだ。'),
('JPN', '路加福音', 42, 10, 16, 'あなたがたに耳を傾ける者は、わたしに耳を傾け、あなたがたを拒む者は、わたしを拒むのです。わたしを拒む者は、わたしを遣わされた方を拒むのです。」'),
('JPN', '路加福音', 42, 10, 17, 'さて、七十二人が喜んで帰って来て言った。「主よ。あなたの御名を用いると、悪霊どもでさえ私たちに服従します。」'),
('JPN', '路加福音', 42, 10, 18, 'イエスは彼らに言われた。「サタンが稲妻のように天から落ちるのを、わたしは見ました。'),
('JPN', '路加福音', 42, 10, 19, '確かにわたしはあなたがたに、蛇やサソリを踏みつけ、敵のあらゆる力に打ち勝つ権威を授けました。ですから、あなたがたに害を加えるものは何一つありません。'),
('JPN', '路加福音', 42, 10, 20, 'しかし、霊どもがあなたがたに服従することを喜ぶのではなく、あなたがたの名が天に書き記されていることを喜びなさい。」'),
('JPN', '路加福音', 42, 10, 21, 'ちょうどそのとき、イエスは聖霊によって喜びにあふれて言われた。「天地の主であられる父よ、あなたをほめたたえます。あなたはこれらのことを、知恵ある者や賢い者には隠して、幼子たちに現してくださいました。そうです、父よ、これはみこころにかなったことでした。'),
('JPN', '路加福音', 42, 10, 22, 'すべてのことが、わたしの父からわたしに渡されています。子がだれであるかは、父のほかはだれも知りません。また父がだれであるかは、子と、子が父を現そうと心に定めた者のほかは、だれも知りません。」'),
('JPN', '路加福音', 42, 10, 23, 'それからイエスは、弟子たちの方を振り向いて、彼らだけに言われた。「あなたがたが見ているものを見る目は幸いです。'),
('JPN', '路加福音', 42, 10, 24, 'あなたがたに言います。多くの預言者や王たちは、あなたがたが見ているものを見たいと願ったのに、見られず、あなたがたが聞いていることを聞きたいと願ったのに、聞けませんでした。」'),
('JPN', '路加福音', 42, 10, 25, 'さて、ある律法の専門家が立ち上がり、イエスを試みようとして言った。「先生。何をしたら、永遠のいのちを受け継ぐことができるでしょうか。」'),
('JPN', '路加福音', 42, 10, 26, 'イエスは彼に言われた。「律法には何と書いてありますか。あなたはどう読んでいますか。」'),
('JPN', '路加福音', 42, 10, 27, 'すると彼は答えた。「『あなたは心を尽くし、いのちを尽くし、力を尽くし、知性を尽くして、あなたの神、主を愛しなさい』、また『あなたの隣人を自分自身のように愛しなさい』とあります。」'),
('JPN', '路加福音', 42, 10, 28, 'イエスは言われた。「あなたの答えは正しい。それを実行しなさい。そうすれば、いのちを得ます。」'),
('JPN', '路加福音', 42, 10, 29, 'しかし彼は、自分が正しいことを示そうとしてイエスに言った。「では、私の隣人とはだれですか。」'),
('JPN', '路加福音', 42, 10, 30, 'イエスは答えられた。「ある人が、エルサレムからエリコへ下って行ったが、強盗に襲われた。強盗たちはその人の着ている物をはぎ取り、殴りつけ、半殺しにしたまま立ち去った。'),
('JPN', '路加福音', 42, 10, 31, 'たまたま祭司が一人、その道を下って来たが、彼を見ると反対側を通り過ぎて行った。'),
('JPN', '路加福音', 42, 10, 32, '同じようにレビ人も、その場所に来て彼を見ると、反対側を通り過ぎて行った。'),
('JPN', '路加福音', 42, 10, 33, 'ところが、旅をしていた一人のサマリア人は、その人のところに来ると、見てかわいそうに思った。'),
('JPN', '路加福音', 42, 10, 34, 'そして近寄って、傷にオリーブ油とぶどう酒を注いで包帯をし、自分の家畜に乗せて宿屋に連れて行って介抱した。'),
('JPN', '路加福音', 42, 10, 35, '次の日、彼はデナリ二枚を取り出し、宿屋の主人に渡して言った。『介抱してあげてください。もっと費用がかかったら、私が帰りに払います。』'),
('JPN', '路加福音', 42, 10, 36, 'この三人の中でだれが、強盗に襲われた人の隣人になったと思いますか。」'),
('JPN', '路加福音', 42, 10, 37, '彼は言った。「その人にあわれみ深い行いをした人です。」するとイエスは言われた。「あなたも行って、同じようにしなさい。」'),
('JPN', '路加福音', 42, 10, 38, 'さて、一行が進んで行くうちに、イエスはある村に入られた。すると、マルタという女の人がイエスを家に迎え入れた。'),
('JPN', '路加福音', 42, 10, 39, '彼女にはマリアという姉妹がいたが、主の足もとに座って、主のことばに聞き入っていた。'),
('JPN', '路加福音', 42, 10, 40, 'ところが、マルタはいろいろなもてなしのために心が落ち着かず、みもとに来て言った。「主よ。私の姉妹が私だけにもてなしをさせているのを、何ともお思いにならないのですか。私の手伝いをするように、おっしゃってください。」'),
('JPN', '路加福音', 42, 10, 41, '主は答えられた。「マルタ、マルタ、あなたはいろいろなことを思い煩って、心を乱しています。'),
('JPN', '路加福音', 42, 10, 42, 'しかし、必要なことは一つだけです。マリアはその良いほうを選びました。それが彼女から取り上げられることはありません。」'),
('JPN', '路加福音', 42, 11, 1, 'さて、イエスはある場所で祈っておられた。祈りが終わると、弟子の一人がイエスに言った。「主よ。ヨハネが弟子たちに教えたように、私たちにも祈りを教えてください。」'),
('JPN', '路加福音', 42, 11, 2, 'そこでイエスは彼らに言われた。「祈るときには、こう言いなさい。『父よ、御名が聖なるものとされますように。御国が来ますように。'),
('JPN', '路加福音', 42, 11, 3, '私たちの日ごとの糧を、毎日お与えください。'),
('JPN', '路加福音', 42, 11, 4, '私たちの罪をお赦しください。私たちも私たちに負い目のある者をみな赦します。私たちを試みにあわせないでください。』」'),
('JPN', '路加福音', 42, 11, 5, 'また、イエスはこう言われた。「あなたがたのうちのだれかに友だちがいて、その人のところに真夜中に行き、次のように言ったとします。『友よ、パンを三つ貸してくれないか。'),
('JPN', '路加福音', 42, 11, 6, '友人が旅の途中、私のところに来たのだが、出してやるものがないのだ。』'),
('JPN', '路加福音', 42, 11, 7, 'すると、その友だちは家の中からこう答えるでしょう。『面倒をかけないでほしい。もう戸を閉めてしまったし、子どもたちも私と一緒に床に入っている。起きて、何かをあげることはできない。』'),
('JPN', '路加福音', 42, 11, 8, 'あなたがたに言います。この人は、友だちだからというだけでは、起きて何かをあげることはしないでしょう。しかし、友だちのしつこさのゆえなら起き上がり、必要なものを何でもあげるでしょう。'),
('JPN', '路加福音', 42, 11, 9, 'ですから、あなたがたに言います。求めなさい。そうすれば与えられます。探しなさい。そうすれば見出します。たたきなさい。そうすれば開かれます。'),
('JPN', '路加福音', 42, 11, 10, 'だれでも、求める者は手に入れ、探す者は見出し、たたく者には開かれます。'),
('JPN', '路加福音', 42, 11, 11, 'あなたがたの中で、子どもが魚を求めているのに、魚の代わりに蛇を与えるような父親がいるでしょうか。'),
('JPN', '路加福音', 42, 11, 12, '卵を求めているのに、サソリを与えるような父親がいるでしょうか。'),
('JPN', '路加福音', 42, 11, 13, 'ですから、あなたがたは悪い者であっても、自分の子どもたちには良いものを与えることを知っています。それならなおのこと、天の父はご自分に求める者たちに聖霊を与えてくださいます。」'),
('JPN', '路加福音', 42, 11, 14, 'さて、イエスは悪霊を追い出しておられた。それは口をきけなくする悪霊であった。悪霊が出て行くと、口がきけなかった人がものを言い始めたので、群衆は驚いた。'),
('JPN', '路加福音', 42, 11, 15, 'しかし、彼らのうちのある者たちは、「悪霊どものかしらベルゼブルによって、悪霊どもを追い出しているのだ」と言った。'),
('JPN', '路加福音', 42, 11, 16, 'また、ほかの者たちはイエスを試みようとして、天からのしるしを要求した。'),
('JPN', '路加福音', 42, 11, 17, 'しかし、イエスは彼らの心を見抜いて言われた。「どんな国でも内輪もめしたら荒れすたれ、家も内輪で争えば倒れます。'),
('JPN', '路加福音', 42, 11, 18, 'あなたがたは、わたしがベルゼブルによって悪霊どもを追い出していると言いますが、サタンが仲間割れしたのなら、どうしてサタンの国は立ち行くことができるでしょう。'),
('JPN', '路加福音', 42, 11, 19, 'もし、わたしがベルゼブルによって悪霊どもを追い出しているとしたら、あなたがたの子らが悪霊どもを追い出しているのは、だれによってなのですか。そういうわけで、あなたがたの子らがあなたがたをさばく者となります。'),
('JPN', '路加福音', 42, 11, 20, 'しかし、わたしが神の指によって悪霊どもを追い出しているのなら、もう神の国はあなたがたのところに来ているのです。'),
('JPN', '路加福音', 42, 11, 21, '強い者が十分に武装して自分の屋敷を守っているときは、その財産は無事です。'),
('JPN', '路加福音', 42, 11, 22, 'しかし、もっと強い人が襲って来て彼に打ち勝つと、彼が頼みにしていた武具を奪い、分捕り品を分けます。'),
('JPN', '路加福音', 42, 11, 23, 'わたしに味方しない者はわたしに敵対し、わたしとともに集めない者は散らしているのです。'),
('JPN', '路加福音', 42, 11, 24, '汚れた霊は人から出て行くと、水のない地をさまよって休み場を探します。でも見つからず、『出て来た自分の家に帰ろう』と言います。'),
('JPN', '路加福音', 42, 11, 25, '帰って見ると、家は掃除されてきちんと片付いています。'),
('JPN', '路加福音', 42, 11, 26, 'そこで出かけて行って、自分よりも悪い、七つのほかの霊を連れて来て、入り込んでそこに住みつきます。そうなると、その人の最後の状態は、初めよりも悪くなるのです。」'),
('JPN', '路加福音', 42, 11, 27, 'イエスがこれらのことを話しておられると、群衆の中から、ある女が声をあげてイエスに言った。「あなたを宿した胎、あなたが吸った乳房は幸いです。」'),
('JPN', '路加福音', 42, 11, 28, 'しかし、イエスは言われた。「幸いなのは、むしろ神のことばを聞いてそれを守る人たちです。」'),
('JPN', '路加福音', 42, 11, 29, 'さて、群衆の数が増えてくると、イエスは話し始められた。「この時代は悪い時代です。しるしを求めますが、しるしは与えられません。ただし、ヨナのしるしは別です。'),
('JPN', '路加福音', 42, 11, 30, 'ヨナがニネベの人々のために、しるしとなったように、人の子がこの時代のために、しるしとなるからです。'),
('JPN', '路加福音', 42, 11, 31, '南の女王が、さばきのときに、この時代の人々とともに立って、この時代の人々を罪ありとします。彼女はソロモンの知恵を聞くために地の果てから来たからです。しかし見なさい。ここにソロモンにまさるものがあります。'),
('JPN', '路加福音', 42, 11, 32, 'ニネベの人々が、さばきのときに、この時代の人々とともに立って、この時代の人々を罪ありとします。ニネベの人々はヨナの説教で悔い改めたからです。しかし見なさい。ここにヨナにまさるものがあります。'),
('JPN', '路加福音', 42, 11, 33, 'だれも、明かりをともして、それを穴蔵の中や升の下に置く者はいません。燭台の上に置きます。入って来た人たちに、その光が見えるようにするためです。'),
('JPN', '路加福音', 42, 11, 34, 'からだの明かりは目です。あなたの目が健やかなら全身も明るくなりますが、目が悪いと、からだも暗くなります。'),
('JPN', '路加福音', 42, 11, 35, 'ですから、自分のうちの光が闇にならないように気をつけなさい。'),
('JPN', '路加福音', 42, 11, 36, 'もし、あなたの全身が明るくて何の暗い部分もないなら、明かりがその輝きであなたを照らすときのように、全身が光に満ちたものとなります。」'),
('JPN', '路加福音', 42, 11, 37, 'イエスが話し終えられると、一人のパリサイ人が、自分の家で食事をしていただきたい、とお願いした。そこでイエスは家に入って、食卓に着かれた。'),
('JPN', '路加福音', 42, 11, 38, 'そのパリサイ人は、イエスが食事の前に、まずきよめの洗いをなさらないのを見て驚いた。'),
('JPN', '路加福音', 42, 11, 39, 'すると、主は彼に言われた。「なるほど、あなたがたパリサイ人は、杯や皿の外側はきよめるが、その内側は強欲と邪悪で満ちています。'),
('JPN', '路加福音', 42, 11, 40, '愚かな者たち。外側を造られた方は、内側も造られたのではありませんか。'),
('JPN', '路加福音', 42, 11, 41, 'とにかく、内にあるものを施しに用いなさい。そうすれば、見よ、あなたがたにとって、すべてがきよいものとなります。'),
('JPN', '路加福音', 42, 11, 42, 'だが、わざわいだ、パリサイ人。おまえたちはミント、うん香、あらゆる野菜の十分の一を納めているが、正義と神への愛をおろそかにしている。十分の一もおろそかにしてはいけないが、これこそしなければならないことだ。'),
('JPN', '路加福音', 42, 11, 43, 'わざわいだ、パリサイ人。おまえたちは会堂の上席や、広場であいさつされることが好きだ。'),
('JPN', '路加福音', 42, 11, 44, 'わざわいだ。おまえたちは人目につかない墓のようで、人々は、その上を歩いても気がつかない。」'),
('JPN', '路加福音', 42, 11, 45, 'すると、律法の専門家の一人がイエスに言った。「先生。そのようなことを言われるなら、私たちまで侮辱することになります。」'),
('JPN', '路加福音', 42, 11, 46, 'しかし、イエスは言われた。「おまえたちもわざわいだ。律法の専門家たち。人々には負いきれない荷物を負わせるが、自分は、その荷物に指一本触れようとはしない。'),
('JPN', '路加福音', 42, 11, 47, 'わざわいだ。おまえたちは預言者たちの墓を建てているが、彼らを殺したのは、おまえたちの先祖だ。'),
('JPN', '路加福音', 42, 11, 48, 'こうして、おまえたちは先祖がしたことの証人となり、同意しているのだ。彼らが預言者たちを殺し、おまえたちが墓を建てているのだから。'),
('JPN', '路加福音', 42, 11, 49, 'だから、神の知恵もこう言ったのだ。『わたしは預言者たちや使徒たちを彼らに遣わすが、彼らは、そのうちのある者たちを殺し、ある者たちを迫害する。'),
('JPN', '路加福音', 42, 11, 50, 'それは、世界の基が据えられたときから流されてきた、すべての預言者の血の責任を、この時代が問われるためである。'),
('JPN', '路加福音', 42, 11, 51, 'アベルの血から、祭壇と神の家の間で殺されたザカリヤの血に至るまで。』そうだ。わたしはおまえたちに言う。この時代はその責任を問われる。'),
('JPN', '路加福音', 42, 11, 52, 'わざわいだ、律法の専門家たち。おまえたちは知識の鍵を取り上げて、自分は入らず、入ろうとする人々を妨げたのだ。」'),
('JPN', '路加福音', 42, 11, 53, 'イエスがそこを出て行かれると、律法学者たち、パリサイ人たちはイエスに対して激しい敵意を抱き、多くのことについてしつこく質問攻めを始めた。'),
('JPN', '路加福音', 42, 11, 54, '彼らは、イエスの口から出ることに、言いがかりをつけようと狙っていたのである。'),
('JPN', '路加福音', 42, 12, 1, 'そうしているうちに、数えきれないほどの群衆が集まって来て、足を踏み合うほどになった。イエスはまず弟子たちに話し始められた。「パリサイ人のパン種、すなわち偽善には気をつけなさい。'),
('JPN', '路加福音', 42, 12, 2, 'おおわれているもので現されないものはなく、隠されているもので知られずにすむものはありません。'),
('JPN', '路加福音', 42, 12, 3, 'ですから、あなたがたが暗闇で言ったことが、みな明るみで聞かれ、奥の部屋で耳にささやいたことが、屋上で言い広められるのです。'),
('JPN', '路加福音', 42, 12, 4, 'わたしの友であるあなたがたに言います。からだを殺しても、その後はもう何もできない者たちを恐れてはいけません。'),
('JPN', '路加福音', 42, 12, 5, '恐れなければならない方を、あなたがたに教えてあげましょう。殺した後で、ゲヘナに投げ込む権威を持っておられる方を恐れなさい。そうです。あなたがたに言います。この方を恐れなさい。'),
('JPN', '路加福音', 42, 12, 6, '五羽の雀が、二アサリオンで売られているではありませんか。そんな雀の一羽でも、神の御前で忘れられてはいません。'),
('JPN', '路加福音', 42, 12, 7, 'それどころか、あなたがたの髪の毛さえも、すべて数えられています。恐れることはありません。あなたがたは、多くの雀よりも価値があるのです。'),
('JPN', '路加福音', 42, 12, 8, 'あなたがたに言います。だれでも人々の前でわたしを認めるなら、人の子もまた、神の御使いたちの前でその人を認めます。'),
('JPN', '路加福音', 42, 12, 9, 'しかし、人々の前でわたしを知らないと言う者は、神の御使いたちの前で知らないと言われます。'),
('JPN', '路加福音', 42, 12, 10, '人の子を悪く言う者はだれでも赦されます。しかし、聖霊を冒瀆する者は赦されません。'),
('JPN', '路加福音', 42, 12, 11, 'また、人々があなたがたを、会堂や役人たち、権力者たちのところに連れて行ったとき、何をどう弁明しようか、何を言おうかと心配しなくてよいのです。'),
('JPN', '路加福音', 42, 12, 12, '言うべきことは、そのときに聖霊が教えてくださるからです。」'),
('JPN', '路加福音', 42, 12, 13, '群衆の中の一人がイエスに言った。「先生。遺産を私と分けるように、私の兄弟に言ってください。」'),
('JPN', '路加福音', 42, 12, 14, 'すると、イエスは彼に言われた。「いったいだれが、わたしをあなたがたの裁判官や調停人に任命したのですか。」'),
('JPN', '路加福音', 42, 12, 15, 'そして人々に言われた。「どんな貪欲にも気をつけ、警戒しなさい。人があり余るほど持っていても、その人のいのちは財産にあるのではないからです。」'),
('JPN', '路加福音', 42, 12, 16, 'それからイエスは人々にたとえを話された。「ある金持ちの畑が豊作であった。'),
('JPN', '路加福音', 42, 12, 17, '彼は心の中で考えた。『どうしよう。私の作物をしまっておく場所がない。』'),
('JPN', '路加福音', 42, 12, 18, 'そして言った。『こうしよう。私の倉を壊して、もっと大きいのを建て、私の穀物や財産はすべてそこにしまっておこう。'),
('JPN', '路加福音', 42, 12, 19, 'そして、自分のたましいにこう言おう。「わがたましいよ、これから先何年分もいっぱい物がためられた。さあ休め。食べて、飲んで、楽しめ。」』'),
('JPN', '路加福音', 42, 12, 20, 'しかし、神は彼に言われた。『愚か者、おまえのたましいは、今夜おまえから取り去られる。おまえが用意した物は、いったいだれのものになるのか。』'),
('JPN', '路加福音', 42, 12, 21, '自分のために蓄えても、神に対して富まない者はこのとおりです。」'),
('JPN', '路加福音', 42, 12, 22, 'それからイエスは弟子たちに言われた。「ですから、わたしはあなたがたに言います。何を食べようかと、いのちのことで心配したり、何を着ようかと、からだのことで心配したりするのはやめなさい。'),
('JPN', '路加福音', 42, 12, 23, 'いのちは食べ物以上のもの、からだは着る物以上のものだからです。'),
('JPN', '路加福音', 42, 12, 24, '烏のことをよく考えなさい。種蒔きもせず、刈り入れもせず、納屋も倉もありません。それでも、神は養っていてくださいます。あなたがたには、その鳥よりも、どんなに大きな価値があることでしょう。'),
('JPN', '路加福音', 42, 12, 25, 'あなたがたのうちだれが、心配したからといって、少しでも自分のいのちを延ばすことができるでしょうか。'),
('JPN', '路加福音', 42, 12, 26, 'こんな小さなことさえできないのなら、なぜほかのことまで心配するのですか。'),
('JPN', '路加福音', 42, 12, 27, '草花がどのようにして育つのか、よく考えなさい。働きもせず、紡ぎもしません。しかし、わたしはあなたがたに言います。栄華を極めたソロモンでさえ、この花の一つほどにも装ってはいませんでした。'),
('JPN', '路加福音', 42, 12, 28, '今日は野にあって、明日は炉に投げ込まれる草さえ、神はこのように装ってくださるのなら、あなたがたには、どんなに良くしてくださることでしょう。信仰の薄い人たちよ。'),
('JPN', '路加福音', 42, 12, 29, '何を食べたらよいか、何を飲んだらよいかと、心配するのをやめ、気をもむのをやめなさい。'),
('JPN', '路加福音', 42, 12, 30, 'これらのものはすべて、この世の異邦人が切に求めているものです。これらのものがあなたがたに必要であることは、あなたがたの父が知っておられます。'),
('JPN', '路加福音', 42, 12, 31, 'むしろ、あなたがたは御国を求めなさい。そうすれば、これらのものはそれに加えて与えられます。'),
('JPN', '路加福音', 42, 12, 32, '小さな群れよ、恐れることはありません。あなたがたの父は、喜んであなたがたに御国を与えてくださるのです。'),
('JPN', '路加福音', 42, 12, 33, '自分の財産を売って施しをしなさい。自分のために、天に、すり切れない財布を作り、尽きることのない宝を積みなさい。天では盗人が近寄ることも、虫が食い荒らすこともありません。'),
('JPN', '路加福音', 42, 12, 34, 'あなたがたの宝のあるところ、そこにあなたがたの心もあるのです。'),
('JPN', '路加福音', 42, 12, 35, '腰に帯を締め、明かりをともしていなさい。'),
('JPN', '路加福音', 42, 12, 36, '主人が婚礼から帰って来て戸をたたいたら、すぐに戸を開けようと、その帰りを待っている人たちのようでありなさい。'),
('JPN', '路加福音', 42, 12, 37, '帰って来た主人に、目を覚ましているのを見てもらえるしもべたちは幸いです。まことに、あなたがたに言います。主人のほうが帯を締め、そのしもべたちを食卓に着かせ、そばに来て給仕してくれます。'),
('JPN', '路加福音', 42, 12, 38, '主人が真夜中に帰って来ても、夜明けに帰って来ても、そのようにしているのを見てもらえるなら、そのしもべたちは幸いです。'),
('JPN', '路加福音', 42, 12, 39, 'このことを知っておきなさい。もしも家の主人が、泥棒の来る時間を知っていたら、自分の家に押し入るのを許さないでしょう。'),
('JPN', '路加福音', 42, 12, 40, 'あなたがたも用心していなさい。人の子は、思いがけない時に来るのです。」'),
('JPN', '路加福音', 42, 12, 41, 'そこで、ペテロが言った。「主よ。このたとえを話されたのは私たちのためですか、皆のためですか。」'),
('JPN', '路加福音', 42, 12, 42, '主は言われた。「では、主人によって、その家の召使いたちの上に任命され、食事時には彼らに決められた分を与える、忠実で賢い管理人とは、いったいだれでしょうか。'),
('JPN', '路加福音', 42, 12, 43, '主人が帰って来たときに、そのようにしているのを見てもらえるしもべは幸いです。'),
('JPN', '路加福音', 42, 12, 44, 'まことに、あなたがたに言います。主人はその人に自分の全財産を任せるようになります。'),
('JPN', '路加福音', 42, 12, 45, 'もし、そのしもべが心の中で、『主人の帰りは遅くなる』と思い、男女の召使いたちを打ちたたき、食べたり飲んだり、酒に酔ったりし始めるなら、'),
('JPN', '路加福音', 42, 12, 46, 'そのしもべの主人は、予期していない日、思いがけない時に帰って来て、彼を厳しく罰し、不忠実な者たちと同じ報いを与えます。'),
('JPN', '路加福音', 42, 12, 47, '主人の思いを知りながら用意もせず、その思いどおりに働きもしなかったしもべは、むちでひどく打たれます。'),
('JPN', '路加福音', 42, 12, 48, 'しかし、主人の思いを知らずにいて、むち打たれるに値することをしたしもべは、少ししか打たれません。多く与えられた者はみな、多くを求められ、多く任された者は、さらに多くを要求されます。'),
('JPN', '路加福音', 42, 12, 49, 'わたしは、地上に火を投げ込むために来ました。火がすでに燃えていたらと、どんなに願っていることでしょう。'),
('JPN', '路加福音', 42, 12, 50, 'わたしには受けるべきバプテスマがあります。それが成し遂げられるまで、わたしはどれほど苦しむことでしょう。'),
('JPN', '路加福音', 42, 12, 51, 'あなたがたは、わたしが地上に平和をもたらすために来たと思っていますか。そうではありません。あなたがたに言いますが、むしろ分裂です。'),
('JPN', '路加福音', 42, 12, 52, '今から後、一つの家の中で五人が二つに分かれ、三人が二人に、二人が三人に対立するようになります。'),
('JPN', '路加福音', 42, 12, 53, '父は息子に、息子は父に対立し、母は娘に、娘は母に対立し、姑は嫁に、嫁は姑に対立して分かれるようになります。」'),
('JPN', '路加福音', 42, 12, 54, 'イエスは群衆にもこう言われた。「あなたがたは、西に雲が出るのを見るとすぐに、『にわか雨になる』と言います。そしてそのとおりになります。'),
('JPN', '路加福音', 42, 12, 55, 'また南風が吹くと、『暑くなるぞ』と言います。そしてそのとおりになります。'),
('JPN', '路加福音', 42, 12, 56, '偽善者たちよ。あなたがたは地と空の様子を見分けることを知っていながら、どうして今の時代を見分けようとしないのですか。'),
('JPN', '路加福音', 42, 12, 57, 'あなたがたは、何が正しいか、どうして自分で判断しないのですか。'),
('JPN', '路加福音', 42, 12, 58, 'あなたを訴える人と一緒に役人のところに行くときは、途中でその人と和解するように努めなさい。そうでないと、その人はあなたを裁判官のもとにひっぱって行き、裁判官はあなたを看守に引き渡し、看守はあなたを牢に投げ込みます。'),
('JPN', '路加福音', 42, 12, 59, 'あなたに言います。最後の一レプタを支払うまで、そこから出ることは決してできません。」'),
('JPN', '路加福音', 42, 13, 1, 'ちょうどそのとき、人々が何人かやって来て、ピラトがガリラヤ人たちの血を、ガリラヤ人たちが献げるいけにえに混ぜた、とイエスに報告した。'),
('JPN', '路加福音', 42, 13, 2, 'イエスは彼らに言われた。「そのガリラヤ人たちは、そのような災難にあったのだから、ほかのすべてのガリラヤ人よりも罪深い人たちだったと思いますか。'),
('JPN', '路加福音', 42, 13, 3, 'そんなことはありません。わたしはあなたがたに言います。あなたがたも悔い改めないなら、みな同じように滅びます。'),
('JPN', '路加福音', 42, 13, 4, 'また、シロアムの塔が倒れて死んだあの十八人は、エルサレムに住んでいるだれよりも多く、罪の負債があったと思いますか。'),
('JPN', '路加福音', 42, 13, 5, 'そんなことはありません。わたしはあなたがたに言います。あなたがたも悔い改めないなら、みな同じように滅びます。」'),
('JPN', '路加福音', 42, 13, 6, 'イエスはこのようなたとえを話された。「ある人が、ぶどう園にいちじくの木を植えておいた。そして、実を探しに来たが、見つからなかった。'),
('JPN', '路加福音', 42, 13, 7, 'そこで、ぶどう園の番人に言った。『見なさい。三年間、このいちじくの木に実を探しに来ているが、見つからない。だから、切り倒してしまいなさい。何のために土地まで無駄にしているのか。』'),
('JPN', '路加福音', 42, 13, 8, '番人は答えた。『ご主人様、どうか、今年もう一年そのままにしておいてください。木の周りを掘って、肥料をやってみます。'),
('JPN', '路加福音', 42, 13, 9, 'それで来年、実を結べばよいでしょう。それでもだめなら、切り倒してください。』」'),
('JPN', '路加福音', 42, 13, 10, 'イエスは安息日に、ある会堂で教えておられた。'),
('JPN', '路加福音', 42, 13, 11, 'すると、そこに十八年も病の霊につかれ、腰が曲がって、全く伸ばすことができない女の人がいた。'),
('JPN', '路加福音', 42, 13, 12, 'イエスは彼女を見ると、呼び寄せて、「女の方、あなたは病から解放されました」と言われた。'),
('JPN', '路加福音', 42, 13, 13, 'そして手を置かれると、彼女はただちに腰が伸びて、神をあがめた。'),
('JPN', '路加福音', 42, 13, 14, 'すると、会堂司はイエスが安息日に癒やしを行ったことに憤って、群衆に言った。「働くべき日は六日ある。だから、その間に来て治してもらいなさい。安息日にはいけない。」'),
('JPN', '路加福音', 42, 13, 15, 'しかし、主は彼に答えられた。「偽善者たち。あなたがたはそれぞれ、安息日に、自分の牛やろばを飼葉桶からほどき、連れて行って水を飲ませるではありませんか。'),
('JPN', '路加福音', 42, 13, 16, 'この人はアブラハムの娘です。それを十八年もの間サタンが縛っていたのです。安息日に、この束縛を解いてやるべきではありませんか。」'),
('JPN', '路加福音', 42, 13, 17, 'イエスがこう話されると、反対していた者たちはみな恥じ入り、群衆はみな、イエスがなさったすべての輝かしいみわざを喜んだ。'),
('JPN', '路加福音', 42, 13, 18, 'そこで、イエスはこう言われた。「神の国は何に似ているでしょうか。何にたとえたらよいでしょうか。'),
('JPN', '路加福音', 42, 13, 19, 'それはからし種に似ています。ある人がそれを取って自分の庭に蒔くと、生長して木になり、空の鳥が枝に巣を作りました。」'),
('JPN', '路加福音', 42, 13, 20, '再びイエスは言われた。「神の国を何にたとえたらよいでしょうか。'),
('JPN', '路加福音', 42, 13, 21, 'それはパン種に似ています。女の人がそれを取って三サトンの粉に混ぜると、全体がふくらみました。」'),
('JPN', '路加福音', 42, 13, 22, 'イエスは町や村を通りながら教え、エルサレムへの旅を続けておられた。'),
('JPN', '路加福音', 42, 13, 23, 'すると、ある人が言った。「主よ、救われる人は少ないのですか。」イエスは人々に言われた。'),
('JPN', '路加福音', 42, 13, 24, '「狭い門から入るように努めなさい。あなたがたに言いますが、多くの人が、入ろうとしても入れなくなるからです。'),
('JPN', '路加福音', 42, 13, 25, '家の主人が立ち上がって、戸を閉めてしまってから、あなたがたが外に立って戸をたたき始め、『ご主人様、開けてください』と言っても、主人は、『おまえたちがどこの者か、私は知らない』と答えるでしょう。'),
('JPN', '路加福音', 42, 13, 26, 'すると、あなたがたはこう言い始めるでしょう。『私たちは、あなたの面前で食べたり飲んだりいたしました。また、あなたは私たちの大通りでお教えくださいました。』'),
('JPN', '路加福音', 42, 13, 27, 'しかし、主人はあなたがたに言います。『おまえたちがどこの者か、私は知らない。不義を行う者たち、みな私から離れて行け。』'),
('JPN', '路加福音', 42, 13, 28, 'あなたがたは、アブラハムやイサクやヤコブ、またすべての預言者たちが神の国に入っているのに、自分たちは外に放り出されているのを知って、そこで泣いて歯ぎしりするのです。'),
('JPN', '路加福音', 42, 13, 29, '人々が東からも西からも、また南からも北からも来て、神の国で食卓に着きます。'),
('JPN', '路加福音', 42, 13, 30, 'いいですか、後にいる者が先になり、先にいる者が後になるのです。」'),
('JPN', '路加福音', 42, 13, 31, 'ちょうどそのとき、パリサイ人たちが何人か近寄って来て、イエスに言った。「ここから立ち去りなさい。ヘロデがあなたを殺そうとしています。」'),
('JPN', '路加福音', 42, 13, 32, 'イエスは彼らに言われた。「行って、あの狐にこう言いなさい。『見なさい。わたしは今日と明日、悪霊どもを追い出し、癒やしを行い、三日目に働きを完了する。'),
('JPN', '路加福音', 42, 13, 33, 'しかし、わたしは今日も明日も、その次の日も進んで行かなければならない。預言者がエルサレム以外のところで死ぬことはあり得ないのだ。』'),
('JPN', '路加福音', 42, 13, 34, 'エルサレム、エルサレム。預言者たちを殺し、自分に遣わされた人たちを石で打つ者よ。わたしは何度、めんどりがひなを翼の下に集めるように、おまえの子らを集めようとしたことか。それなのに、おまえたちはそれを望まなかった。'),
('JPN', '路加福音', 42, 13, 35, '見よ、おまえたちの家は見捨てられる。わたしはおまえたちに言う。おまえたちが『祝福あれ、主の御名によって来られる方に』と言う時が来るまで、決しておまえたちがわたしを見ることはない。」'),
('JPN', '路加福音', 42, 14, 1, 'ある安息日のこと、イエスは食事をするために、パリサイ派のある指導者の家に入られた。そのとき人々はじっとイエスを見つめていた。'),
('JPN', '路加福音', 42, 14, 2, '見よ、イエスの前には、水腫をわずらっている人がいた。'),
('JPN', '路加福音', 42, 14, 3, 'イエスは、律法の専門家たちやパリサイ人たちに対して、「安息日に癒やすのは律法にかなっているでしょうか、いないでしょうか」と言われた。'),
('JPN', '路加福音', 42, 14, 4, '彼らは黙っていた。それで、イエスはその人を抱いて癒やし、帰された。'),
('JPN', '路加福音', 42, 14, 5, 'それから、彼らに言われた。「自分の息子や牛が井戸に落ちたのに、安息日だからといって、すぐに引き上げてやらない者が、あなたがたのうちにいるでしょうか。」'),
('JPN', '路加福音', 42, 14, 6, '彼らはこれに答えることができなかった。'),
('JPN', '路加福音', 42, 14, 7, 'イエスは、客として招かれた人たちが上座を選んでいる様子に気がついて、彼らにたとえを話された。'),
('JPN', '路加福音', 42, 14, 8, '「結婚の披露宴に招かれたときには、上座に座ってはいけません。あなたより身分の高い人が招かれているかもしれません。'),
('JPN', '路加福音', 42, 14, 9, 'あなたやその人を招いた人が来て、『この人に席を譲ってください』と言うことになります。そのときあなたは恥をかいて、末席に着くことになります。'),
('JPN', '路加福音', 42, 14, 10, '招かれたなら、末席に行って座りなさい。そうすると、あなたを招いた人が来て、『友よ、もっと上席にお進みください』と言うでしょう。そのとき、ともに座っている皆の前で、あなたは誉れを得ることになります。'),
('JPN', '路加福音', 42, 14, 11, 'なぜなら、だれでも自分を高くする者は低くされ、自分を低くする者は高くされるからです。」'),
('JPN', '路加福音', 42, 14, 12, 'イエスはまた、ご自分を招いてくれた人にも、こう話された。「昼食や晩餐をふるまうのなら、友人、兄弟、親族、近所の金持ちなどを呼んではいけません。彼らがあなたを招いて、お返しをすることがないようにするためです。'),
('JPN', '路加福音', 42, 14, 13, '食事のふるまいをするときには、貧しい人たち、からだの不自由な人たち、足の不自由な人たち、目の見えない人たちを招きなさい。'),
('JPN', '路加福音', 42, 14, 14, 'その人たちはお返しができないので、あなたは幸いです。あなたは、義人の復活のときに、お返しを受けるのです。」'),
('JPN', '路加福音', 42, 14, 15, 'イエスとともに食卓に着いていた客の一人はこれを聞いて、イエスに言った。「神の国で食事をする人は、なんと幸いなことでしょう。」'),
('JPN', '路加福音', 42, 14, 16, 'するとイエスは彼にこう言われた。「ある人が盛大な宴会を催し、大勢の人を招いた。'),
('JPN', '路加福音', 42, 14, 17, '宴会の時刻になったのでしもべを遣わし、招いていた人たちに、『さあ、おいでください。もう用意ができましたから』と言った。'),
('JPN', '路加福音', 42, 14, 18, 'ところが、みな同じように断り始めた。最初の人はこう言った。『畑を買ったので、見に行かなければなりません。どうか、ご容赦ください。』'),
('JPN', '路加福音', 42, 14, 19, '別の人はこう言った。『五くびきの牛を買ったので、それを試しに行くところです。どうか、ご容赦ください。』'),
('JPN', '路加福音', 42, 14, 20, 'また、別の人はこう言った。『結婚したので、行くことができません。』'),
('JPN', '路加福音', 42, 14, 21, 'しもべは帰って来て、このことを主人に報告した。すると、家の主人は怒って、そのしもべに言った。『急いで町の大通りや路地に出て行って、貧しい人たち、からだの不自由な人たち、目の見えない人たち、足の不自由な人たちをここに連れて来なさい。』'),
('JPN', '路加福音', 42, 14, 22, 'しもべは言った。『ご主人様、お命じになったとおりにいたしました。でも、まだ席があります。』'),
('JPN', '路加福音', 42, 14, 23, 'すると主人はしもべに言った。『街道や垣根のところに出て行き、無理にでも人々を連れて来て、私の家をいっぱいにしなさい。'),
('JPN', '路加福音', 42, 14, 24, '言っておくが、あの招待されていた人たちの中で、私の食事を味わう者は一人もいません。』」'),
('JPN', '路加福音', 42, 14, 25, 'さて、大勢の群衆がイエスと一緒に歩いていたが、イエスは振り向いて彼らに言われた。'),
('JPN', '路加福音', 42, 14, 26, '「わたしのもとに来て、自分の父、母、妻、子、兄弟、姉妹、さらに自分のいのちまでも憎まないなら、わたしの弟子になることはできません。'),
('JPN', '路加福音', 42, 14, 27, '自分の十字架を負ってわたしについて来ない者は、わたしの弟子になることはできません。'),
('JPN', '路加福音', 42, 14, 28, 'あなたがたのうちに、塔を建てようとするとき、まず座って、完成させるのに十分な金があるかどうか、費用を計算しない人がいるでしょうか。'),
('JPN', '路加福音', 42, 14, 29, '計算しないと、土台を据えただけで完成できず、見ていた人たちはみなその人を嘲って、'),
('JPN', '路加福音', 42, 14, 30, '『この人は建て始めたのに、完成できなかった』と言うでしょう。'),
('JPN', '路加福音', 42, 14, 31, 'また、どんな王でも、ほかの王と戦いを交えようと出て行くときは、二万人を引き連れて向かって来る敵を、一万人で迎え撃つことができるかどうか、まず座ってよく考えないでしょうか。'),
('JPN', '路加福音', 42, 14, 32, 'もしできないと思えば、敵がまだ遠くに離れている間に、使者を送って講和の条件を尋ねるでしょう。'),
('JPN', '路加福音', 42, 14, 33, 'そういうわけで、自分の財産すべてを捨てなければ、あなたがたはだれも、わたしの弟子になることはできません。'),
('JPN', '路加福音', 42, 14, 34, '塩は良いものです。しかし、もし塩が塩気をなくしたら、何によってそれに味をつけるのでしょうか。'),
('JPN', '路加福音', 42, 14, 35, '土地にも肥やしにも役立たず、外に投げ捨てられます。聞く耳のある者は聞きなさい。」'),
('JPN', '路加福音', 42, 15, 1, 'さて、取税人たちや罪人たちがみな、話を聞こうとしてイエスの近くにやって来た。'),
('JPN', '路加福音', 42, 15, 2, 'すると、パリサイ人たち、律法学者たちが、「この人は罪人たちを受け入れて、一緒に食事をしている」と文句を言った。'),
('JPN', '路加福音', 42, 15, 3, 'そこでイエスは、彼らにこのようなたとえを話された。'),
('JPN', '路加福音', 42, 15, 4, '「あなたがたのうちのだれかが羊を百匹持っていて、そのうちの一匹をなくしたら、その人は九十九匹を野に残して、いなくなった一匹を見つけるまで捜し歩かないでしょうか。'),
('JPN', '路加福音', 42, 15, 5, '見つけたら、喜んで羊を肩に担ぎ、'),
('JPN', '路加福音', 42, 15, 6, '家に戻って、友だちや近所の人たちを呼び集め、『一緒に喜んでください。いなくなった羊を見つけましたから』と言うでしょう。'),
('JPN', '路加福音', 42, 15, 7, 'あなたがたに言います。それと同じように、一人の罪人が悔い改めるなら、悔い改める必要のない九十九人の正しい人のためよりも、大きな喜びが天にあるのです。'),
('JPN', '路加福音', 42, 15, 8, 'また、ドラクマ銀貨を十枚持っている女の人が、その一枚をなくしたら、明かりをつけ、家を掃いて、見つけるまで注意深く捜さないでしょうか。'),
('JPN', '路加福音', 42, 15, 9, '見つけたら、女友だちや近所の女たちを呼び集めて、『一緒に喜んでください。なくしたドラクマ銀貨を見つけましたから』と言うでしょう。'),
('JPN', '路加福音', 42, 15, 10, 'あなたがたに言います。それと同じように、一人の罪人が悔い改めるなら、神の御使いたちの前には喜びがあるのです。」'),
('JPN', '路加福音', 42, 15, 11, 'イエスはまた、こう話された。「ある人に二人の息子がいた。'),
('JPN', '路加福音', 42, 15, 12, '弟のほうが父に、『お父さん、財産のうち私がいただく分を下さい』と言った。それで、父は財産を二人に分けてやった。'),
('JPN', '路加福音', 42, 15, 13, 'それから何日もしないうちに、弟息子は、すべてのものをまとめて遠い国に旅立った。そして、そこで放蕩して、財産を湯水のように使ってしまった。'),
('JPN', '路加福音', 42, 15, 14, '何もかも使い果たした後、その地方全体に激しい飢饉が起こり、彼は食べることにも困り始めた。'),
('JPN', '路加福音', 42, 15, 15, 'それで、その地方に住むある人のところに身を寄せたところ、その人は彼を畑に送って、豚の世話をさせた。'),
('JPN', '路加福音', 42, 15, 16, '彼は、豚が食べているいなご豆で腹を満たしたいほどだったが、だれも彼に与えてはくれなかった。'),
('JPN', '路加福音', 42, 15, 17, 'しかし、彼は我に返って言った。『父のところには、パンのあり余っている雇い人が、なんと大勢いることか。それなのに、私はここで飢え死にしようとしている。'),
('JPN', '路加福音', 42, 15, 18, '立って、父のところに行こう。そしてこう言おう。「お父さん。私は天に対して罪を犯し、あなたの前に罪ある者です。'),
('JPN', '路加福音', 42, 15, 19, 'もう、息子と呼ばれる資格はありません。雇い人の一人にしてください。」』')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '路加福音', 42, 15, 20, 'こうして彼は立ち上がって、自分の父のもとへ向かった。ところが、まだ家までは遠かったのに、父親は彼を見つけて、かわいそうに思い、駆け寄って彼の首を抱き、口づけした。'),
('JPN', '路加福音', 42, 15, 21, '息子は父に言った。『お父さん。私は天に対して罪を犯し、あなたの前に罪ある者です。もう、息子と呼ばれる資格はありません。』'),
('JPN', '路加福音', 42, 15, 22, 'ところが父親は、しもべたちに言った。『急いで一番良い衣を持って来て、この子に着せなさい。手に指輪をはめ、足に履き物をはかせなさい。'),
('JPN', '路加福音', 42, 15, 23, 'そして肥えた子牛を引いて来て屠りなさい。食べて祝おう。'),
('JPN', '路加福音', 42, 15, 24, 'この息子は、死んでいたのに生き返り、いなくなっていたのに見つかったのだから。』こうして彼らは祝宴を始めた。'),
('JPN', '路加福音', 42, 15, 25, 'ところで、兄息子は畑にいたが、帰って来て家に近づくと、音楽や踊りの音が聞こえてきた。'),
('JPN', '路加福音', 42, 15, 26, 'それで、しもべの一人を呼んで、これはいったい何事かと尋ねた。'),
('JPN', '路加福音', 42, 15, 27, 'しもべは彼に言った。『あなたのご兄弟がお帰りになりました。無事な姿でお迎えしたので、お父様が、肥えた子牛を屠られたのです。』'),
('JPN', '路加福音', 42, 15, 28, 'すると兄は怒って、家に入ろうともしなかった。それで、父が出て来て彼をなだめた。'),
('JPN', '路加福音', 42, 15, 29, 'しかし、兄は父に答えた。『ご覧ください。長年の間、私はお父さんにお仕えし、あなたの戒めを破ったことは一度もありません。その私には、友だちと楽しむようにと、子やぎ一匹下さったこともありません。'),
('JPN', '路加福音', 42, 15, 30, 'それなのに、遊女と一緒にお父さんの財産を食いつぶした息子が帰って来ると、そんな息子のために肥えた子牛を屠られるとは。』'),
('JPN', '路加福音', 42, 15, 31, '父は彼に言った。『子よ、おまえはいつも私と一緒にいる。私のものは全部おまえのものだ。'),
('JPN', '路加福音', 42, 15, 32, 'だが、おまえの弟は死んでいたのに生き返り、いなくなっていたのに見つかったのだから、喜び祝うのは当然ではないか。』」'),
('JPN', '路加福音', 42, 16, 1, 'イエスは弟子たちに対しても、次のように語られた。「ある金持ちに一人の管理人がいた。この管理人が主人の財産を無駄遣いしている、という訴えが主人にあった。'),
('JPN', '路加福音', 42, 16, 2, '主人は彼を呼んで言った。『おまえについて聞いたこの話は何なのか。会計の報告を出しなさい。もうおまえに、管理を任せておくわけにはいかない。』'),
('JPN', '路加福音', 42, 16, 3, '管理人は心の中で考えた。『どうしよう。主人は私から管理の仕事を取り上げようとしている。土を掘る力はないし、物乞いをするのは恥ずかしい。'),
('JPN', '路加福音', 42, 16, 4, '分かった、こうしよう。管理の仕事をやめさせられても、人々が私を家に迎えてくれるようにすればよいのだ。』'),
('JPN', '路加福音', 42, 16, 5, 'そこで彼は、主人の債務者たちを一人ひとり呼んで、最初の人に、『私の主人に、いくら借りがありますか』と言った。'),
('JPN', '路加福音', 42, 16, 6, 'その人は『油百バテ』と答えた。すると彼は、『あなたの証文を受け取り、座ってすぐに五十と書きなさい』と言った。'),
('JPN', '路加福音', 42, 16, 7, 'それから別の人に、『あなたは、いくら借りがありますか』と言うと、その人は『小麦百コル』と答えた。彼は、『あなたの証文を受け取り、八十と書きなさい』と言った。'),
('JPN', '路加福音', 42, 16, 8, '主人は、不正な管理人が賢く行動したのをほめた。この世の子らは、自分と同じ時代の人々の扱いについては、光の子らよりも賢いのである。'),
('JPN', '路加福音', 42, 16, 9, 'わたしはあなたがたに言います。不正の富で、自分のために友をつくりなさい。そうすれば、富がなくなったとき、彼らがあなたがたを永遠の住まいに迎えてくれます。'),
('JPN', '路加福音', 42, 16, 10, '最も小さなことに忠実な人は、大きなことにも忠実であり、最も小さなことに不忠実な人は、大きなことにも不忠実です。'),
('JPN', '路加福音', 42, 16, 11, 'ですから、あなたがたが不正の富に忠実でなければ、だれがあなたがたに、まことの富を任せるでしょうか。'),
('JPN', '路加福音', 42, 16, 12, 'また、他人のものに忠実でなければ、だれがあなたがたに、あなたがた自身のものを持たせるでしょうか。'),
('JPN', '路加福音', 42, 16, 13, 'どんなしもべも二人の主人に仕えることはできません。一方を憎んで他方を愛することになるか、一方を重んじて他方を軽んじることになります。あなたがたは、神と富とに仕えることはできません。」'),
('JPN', '路加福音', 42, 16, 14, '金銭を好むパリサイ人たちは、これらすべてを聞いて、イエスをあざ笑っていた。'),
('JPN', '路加福音', 42, 16, 15, 'イエスは彼らに言われた。「あなたがたは、人々の前で自分を正しいとするが、神はあなたがたの心をご存じです。人々の間で尊ばれるものは、神の前では忌み嫌われるものなのです。'),
('JPN', '路加福音', 42, 16, 16, '律法と預言者はヨハネまでです。それ以来、神の国の福音が宣べ伝えられ、だれもが力ずくで、そこに入ろうとしています。'),
('JPN', '路加福音', 42, 16, 17, 'しかし、律法の一画が落ちるよりも、天地が滅びるほうが易しいのです。'),
('JPN', '路加福音', 42, 16, 18, 'だれでも妻を離縁して別の女と結婚する者は、姦淫を犯すことになり、夫から離縁された女と結婚する者も、姦淫を犯すことになります。'),
('JPN', '路加福音', 42, 16, 19, 'ある金持ちがいた。紫の衣や柔らかい亜麻布を着て、毎日ぜいたくに遊び暮らしていた。'),
('JPN', '路加福音', 42, 16, 20, 'その金持ちの門前には、ラザロという、できものだらけの貧しい人が寝ていた。'),
('JPN', '路加福音', 42, 16, 21, '彼は金持ちの食卓から落ちる物で、腹を満たしたいと思っていた。犬たちもやって来ては、彼のできものをなめていた。'),
('JPN', '路加福音', 42, 16, 22, 'しばらくして、この貧しい人は死に、御使いたちによってアブラハムの懐に連れて行かれた。金持ちもまた、死んで葬られた。'),
('JPN', '路加福音', 42, 16, 23, '金持ちが、よみで苦しみながら目を上げると、遠くにアブラハムと、その懐にいるラザロが見えた。'),
('JPN', '路加福音', 42, 16, 24, '金持ちは叫んで言った。『父アブラハムよ、私をあわれんでラザロをお送りください。ラザロが指先を水に浸して私の舌を冷やすようにしてください。私はこの炎の中で苦しくてたまりません。』'),
('JPN', '路加福音', 42, 16, 25, 'するとアブラハムは言った。『子よ、思い出しなさい。おまえは生きている間、良いものを受け、ラザロは生きている間、悪いものを受けた。しかし今は、彼はここで慰められ、おまえは苦しみもだえている。'),
('JPN', '路加福音', 42, 16, 26, 'そればかりか、私たちとおまえたちの間には大きな淵がある。ここからおまえたちのところへ渡ろうとしても渡れず、そこから私たちのところへ越えて来ることもできない。』'),
('JPN', '路加福音', 42, 16, 27, '金持ちは言った。『父よ。それではお願いですから、ラザロを私の家族に送ってください。'),
('JPN', '路加福音', 42, 16, 28, '私には兄弟が五人いますが、彼らまでこんな苦しい場所に来ることがないように、彼らに警告してください。』'),
('JPN', '路加福音', 42, 16, 29, 'しかし、アブラハムは言った。『彼らにはモーセと預言者がいる。その言うことを聞くがよい。』'),
('JPN', '路加福音', 42, 16, 30, '金持ちは言った。『いいえ、父アブラハムよ。もし、死んだ者たちの中から、だれかが彼らのところに行けば、彼らは悔い改めるでしょう。』'),
('JPN', '路加福音', 42, 16, 31, 'アブラハムは彼に言った。『モーセと預言者たちに耳を傾けないのなら、たとえ、だれかが死人の中から生き返っても、彼らは聞き入れはしない。』」'),
('JPN', '路加福音', 42, 17, 1, 'イエスは弟子たちに言われた。「つまずきが起こるのは避けられませんが、つまずきをもたらす者はわざわいです。'),
('JPN', '路加福音', 42, 17, 2, 'その者にとっては、これらの小さい者たちの一人をつまずかせるより、ひき臼を首に結び付けられて、海に投げ込まれるほうがましです。'),
('JPN', '路加福音', 42, 17, 3, 'あなたがたは、自分自身に気をつけなさい。兄弟が罪を犯したなら、戒めなさい。そして悔い改めるなら、赦しなさい。'),
('JPN', '路加福音', 42, 17, 4, '一日に七回あなたに対して罪を犯しても、七回あなたのところに来て『悔い改めます』と言うなら、赦しなさい。」'),
('JPN', '路加福音', 42, 17, 5, '使徒たちは主に言った。「私たちの信仰を増し加えてください。」'),
('JPN', '路加福音', 42, 17, 6, 'すると主は言われた。「もしあなたがたに、からし種ほどの信仰があれば、この桑の木に『根元から抜かれて、海の中に植われ』と言うなら、あなたがたに従います。'),
('JPN', '路加福音', 42, 17, 7, 'あなたがたのだれかのところに、畑を耕すか羊を飼うしもべがいて、そのしもべが野から帰って来たら、『さあ、こちらに来て、食事をしなさい』と言うでしょうか。'),
('JPN', '路加福音', 42, 17, 8, 'むしろ、『私の夕食の用意をし、私が食べたり飲んだりする間、帯を締めて給仕しなさい。おまえはその後で食べたり飲んだりしなさい』と言うのではないでしょうか。'),
('JPN', '路加福音', 42, 17, 9, 'しもべが命じられたことをしたからといって、主人はそのしもべに感謝するでしょうか。'),
('JPN', '路加福音', 42, 17, 10, '同じようにあなたがたも、自分に命じられたことをすべて行ったら、『私たちは取るに足りないしもべです。なすべきことをしただけです』と言いなさい。」'),
('JPN', '路加福音', 42, 17, 11, 'さて、イエスはエルサレムに向かう途中、サマリアとガリラヤの境を通られた。'),
('JPN', '路加福音', 42, 17, 12, 'ある村に入ると、ツァラアトに冒された十人の人がイエスを出迎えた。彼らは遠く離れたところに立ち、'),
('JPN', '路加福音', 42, 17, 13, '声を張り上げて、「イエス様、先生、私たちをあわれんでください」と言った。'),
('JPN', '路加福音', 42, 17, 14, 'イエスはこれを見て彼らに言われた。「行って、自分のからだを祭司に見せなさい。」すると彼らは行く途中できよめられた。'),
('JPN', '路加福音', 42, 17, 15, 'そのうちの一人は、自分が癒やされたことが分かると、大声で神をほめたたえながら引き返して来て、'),
('JPN', '路加福音', 42, 17, 16, 'イエスの足もとにひれ伏して感謝した。彼はサマリア人であった。'),
('JPN', '路加福音', 42, 17, 17, 'すると、イエスは言われた。「十人きよめられたのではなかったか。九人はどこにいるのか。'),
('JPN', '路加福音', 42, 17, 18, 'この他国人のほかに、神をあがめるために戻って来た者はいなかったのか。」'),
('JPN', '路加福音', 42, 17, 19, 'それからイエスはその人に言われた。「立ち上がって行きなさい。あなたの信仰があなたを救ったのです。」'),
('JPN', '路加福音', 42, 17, 20, 'パリサイ人たちが、神の国はいつ来るのかと尋ねたとき、イエスは彼らに答えられた。「神の国は、目に見える形で来るものではありません。'),
('JPN', '路加福音', 42, 17, 21, '『見よ、ここだ』とか、『あそこだ』とか言えるようなものではありません。見なさい。神の国はあなたがたのただ中にあるのです。」'),
('JPN', '路加福音', 42, 17, 22, 'イエスは弟子たちに言われた。「あなたがたが、人の子の日を一日でも見たいと願っても、見られない日が来ます。'),
('JPN', '路加福音', 42, 17, 23, '人々は『見よ、あそこだ』とか、『見よ、ここだ』とか言いますが、行ってはいけません。追いかけてもいけません。'),
('JPN', '路加福音', 42, 17, 24, '人の子の日、人の子は、稲妻がひらめいて天の端から天の端まで光るのと、ちょうど同じようになります。'),
('JPN', '路加福音', 42, 17, 25, 'しかし、まず人の子は多くの苦しみを受け、この時代の人々に捨てられなければなりません。'),
('JPN', '路加福音', 42, 17, 26, 'ちょうど、ノアの日に起こったのと同じことが、人の子の日にも起こります。'),
('JPN', '路加福音', 42, 17, 27, 'ノアが箱舟に入るその日まで、人々は食べたり飲んだり、めとったり嫁いだりしていましたが、洪水が来て、すべての人を滅ぼしてしまいました。'),
('JPN', '路加福音', 42, 17, 28, 'また、ロトの日に起こったことと同じようになります。人々は食べたり飲んだり、売ったり買ったり、植えたり建てたりしていましたが、'),
('JPN', '路加福音', 42, 17, 29, 'ロトがソドムから出て行ったその日に、火と硫黄が天から降って来て、すべての人を滅ぼしてしまいました。'),
('JPN', '路加福音', 42, 17, 30, '人の子が現れる日にも、同じことが起こります。'),
('JPN', '路加福音', 42, 17, 31, 'その日、屋上にいる人は、家に家財があっても、それを持ち出すために下に降りてはいけません。同じように、畑にいる人も戻ってはいけません。'),
('JPN', '路加福音', 42, 17, 32, 'ロトの妻のことを思い出しなさい。'),
('JPN', '路加福音', 42, 17, 33, '自分のいのちを救おうと努める者はそれを失い、それを失う者はいのちを保ちます。'),
('JPN', '路加福音', 42, 17, 34, 'あなたがたに言いますが、その夜、同じ寝床で人が二人寝ていると、一人は取られ、もう一人は残されます。'),
('JPN', '路加福音', 42, 17, 35, '同じところで臼をひいている女が二人いると、一人は取られ、もう一人は残されます。」'),
('JPN', '路加福音', 42, 17, 37, '弟子たちが、「主よ、それはどこで起こるのですか」と言うと、イエスは彼らに言われた。「死体のあるところ、そこには禿鷹が集まります。」'),
('JPN', '路加福音', 42, 18, 1, 'いつでも祈るべきで、失望してはいけないことを教えるために、イエスは弟子たちにたとえを話された。'),
('JPN', '路加福音', 42, 18, 2, '「ある町に、神を恐れず、人を人とも思わない裁判官がいた。'),
('JPN', '路加福音', 42, 18, 3, 'その町に一人のやもめがいたが、彼のところにやって来ては、『私を訴える人をさばいて、私を守ってください』と言っていた。'),
('JPN', '路加福音', 42, 18, 4, 'この裁判官はしばらく取り合わなかったが、後になって心の中で考えた。『私は神をも恐れず、人を人とも思わないが、'),
('JPN', '路加福音', 42, 18, 5, 'このやもめは、うるさくて仕方がないから、彼女のために裁判をしてやることにしよう。そうでないと、ひっきりなしにやって来て、私は疲れ果ててしまう。』」'),
('JPN', '路加福音', 42, 18, 6, '主は言われた。「不正な裁判官が言っていることを聞きなさい。'),
('JPN', '路加福音', 42, 18, 7, 'まして神は、昼も夜も神に叫び求めている、選ばれた者たちのためにさばきを行わないで、いつまでも放っておかれることがあるでしょうか。'),
('JPN', '路加福音', 42, 18, 8, 'あなたがたに言いますが、神は彼らのため、速やかにさばきを行ってくださいます。だが、人の子が来るとき、はたして地上に信仰が見られるでしょうか。」'),
('JPN', '路加福音', 42, 18, 9, '自分は正しいと確信していて、ほかの人々を見下している人たちに、イエスはこのようなたとえを話された。'),
('JPN', '路加福音', 42, 18, 10, '「二人の人が祈るために宮に上って行った。一人はパリサイ人で、もう一人は取税人であった。'),
('JPN', '路加福音', 42, 18, 11, 'パリサイ人は立って、心の中でこんな祈りをした。『神よ。私がほかの人たちのように、奪い取る者、不正な者、姦淫する者でないこと、あるいは、この取税人のようでないことを感謝します。'),
('JPN', '路加福音', 42, 18, 12, '私は週に二度断食し、自分が得ているすべてのものから、十分の一を献げております。』'),
('JPN', '路加福音', 42, 18, 13, '一方、取税人は遠く離れて立ち、目を天に向けようともせず、自分の胸をたたいて言った。『神様、罪人の私をあわれんでください。』'),
('JPN', '路加福音', 42, 18, 14, 'あなたがたに言いますが、義と認められて家に帰ったのは、あのパリサイ人ではなく、この人です。だれでも自分を高くする者は低くされ、自分を低くする者は高くされるのです。」'),
('JPN', '路加福音', 42, 18, 15, 'さて、イエスに触れていただこうと、人々は幼子たちまで連れて来た。ところが、弟子たちはそれを見て叱った。'),
('JPN', '路加福音', 42, 18, 16, 'しかし、イエスは幼子たちを呼び寄せて、こう言われた。「子どもたちを、わたしのところに来させなさい。邪魔してはいけません。神の国はこのような者たちのものなのです。'),
('JPN', '路加福音', 42, 18, 17, 'まことに、あなたがたに言います。子どものように神の国を受け入れる者でなければ、決してそこに入ることはできません。」'),
('JPN', '路加福音', 42, 18, 18, 'また、ある指導者がイエスに質問した。「良い先生。何をしたら、私は永遠のいのちを受け継ぐことができるでしょうか。」'),
('JPN', '路加福音', 42, 18, 19, 'イエスは彼に言われた。「なぜ、わたしを『良い』と言うのですか。良い方は神おひとりのほか、だれもいません。'),
('JPN', '路加福音', 42, 18, 20, '戒めはあなたも知っているはずです。『姦淫してはならない。殺してはならない。盗んではならない。偽りの証言をしてはならない。あなたの父と母を敬え。』」'),
('JPN', '路加福音', 42, 18, 21, 'するとその人は言った。「私は少年のころから、それらすべてを守ってきました。」'),
('JPN', '路加福音', 42, 18, 22, 'イエスはこれを聞いて、彼に言われた。「まだ一つ、あなたに欠けていることがあります。あなたが持っている物をすべて売り払い、貧しい人たちに分けてやりなさい。そうすれば、あなたは天に宝を持つことになります。そのうえで、わたしに従って来なさい。」'),
('JPN', '路加福音', 42, 18, 23, '彼はこれを聞いて、非常に悲しんだ。大変な金持ちだったからである。'),
('JPN', '路加福音', 42, 18, 24, 'イエスは彼が非常に悲しんだのを見て、こう言われた。「富を持つ者が神の国に入るのは、なんと難しいことでしょう。'),
('JPN', '路加福音', 42, 18, 25, '金持ちが神の国に入るよりは、らくだが針の穴を通るほうが易しいのです。」'),
('JPN', '路加福音', 42, 18, 26, 'それを聞いた人々は言った。「それでは、だれが救われることができるでしょう。」'),
('JPN', '路加福音', 42, 18, 27, 'イエスは言われた。「人にはできないことが、神にはできるのです。」'),
('JPN', '路加福音', 42, 18, 28, 'すると、ペテロが言った。「ご覧ください。私たちは自分のものを捨てて、あなたに従って来ました。」'),
('JPN', '路加福音', 42, 18, 29, 'イエスは彼らに言われた。「まことに、あなたがたに言います。だれでも、神の国のために、家、妻、兄弟、両親、子どもを捨てた者は、'),
('JPN', '路加福音', 42, 18, 30, '必ずこの世で、その何倍も受け、来たるべき世で、永遠のいのちを受けます。」'),
('JPN', '路加福音', 42, 18, 31, 'さて、イエスは十二人をそばに呼んで、彼らに話された。「ご覧なさい。わたしたちはエルサレムに上って行きます。人の子について、預言者たちを通して書き記されているすべてのことが実現するのです。'),
('JPN', '路加福音', 42, 18, 32, '人の子は異邦人に引き渡され、彼らに嘲られ、辱められ、唾をかけられます。'),
('JPN', '路加福音', 42, 18, 33, '彼らは人の子をむちで打ってから殺します。しかし、人の子は三日目によみがえります。」'),
('JPN', '路加福音', 42, 18, 34, '弟子たちには、これらのことが何一つ分からなかった。彼らにはこのことばが隠されていて、話されたことが理解できなかった。'),
('JPN', '路加福音', 42, 18, 35, 'イエスがエリコに近づいたとき、一人の目の見えない人が道端に座り、物乞いをしていた。'),
('JPN', '路加福音', 42, 18, 36, '彼は群衆が通って行くのを耳にして、これはいったい何事かと尋ねた。'),
('JPN', '路加福音', 42, 18, 37, 'ナザレ人イエスがお通りになるのだと人々が知らせると、'),
('JPN', '路加福音', 42, 18, 38, '彼は大声で、「ダビデの子のイエス様、私をあわれんでください」と言った。'),
('JPN', '路加福音', 42, 18, 39, '先を行く人たちが、黙らせようとしてたしなめたが、その人はますます激しく「ダビデの子よ、私をあわれんでください」と叫んだ。'),
('JPN', '路加福音', 42, 18, 40, 'イエスは立ち止まって、彼を連れて来るように命じられた。彼が近くに来ると、イエスはお尋ねになった。'),
('JPN', '路加福音', 42, 18, 41, '「わたしに何をしてほしいのですか。」するとその人は答えた。「主よ、目が見えるようにしてください。」'),
('JPN', '路加福音', 42, 18, 42, 'イエスは彼に言われた。「見えるようになれ。あなたの信仰があなたを救いました。」'),
('JPN', '路加福音', 42, 18, 43, 'その人はただちに見えるようになり、神をあがめながらイエスについて行った。これを見て、民はみな神を賛美した。'),
('JPN', '路加福音', 42, 19, 1, 'それからイエスはエリコに入り、町の中を通っておられた。'),
('JPN', '路加福音', 42, 19, 2, 'するとそこに、ザアカイという名の人がいた。彼は取税人のかしらで、金持ちであった。'),
('JPN', '路加福音', 42, 19, 3, '彼はイエスがどんな方かを見ようとしたが、背が低かったので、群衆のために見ることができなかった。'),
('JPN', '路加福音', 42, 19, 4, 'それで、先の方に走って行き、イエスを見ようとして、いちじく桑の木に登った。イエスがそこを通り過ぎようとしておられたからであった。'),
('JPN', '路加福音', 42, 19, 5, 'イエスはその場所に来ると、上を見上げて彼に言われた。「ザアカイ、急いで降りて来なさい。わたしは今日、あなたの家に泊まることにしているから。」'),
('JPN', '路加福音', 42, 19, 6, 'ザアカイは急いで降りて来て、喜んでイエスを迎えた。'),
('JPN', '路加福音', 42, 19, 7, '人々はみな、これを見て、「あの人は罪人のところに行って客となった」と文句を言った。'),
('JPN', '路加福音', 42, 19, 8, 'しかし、ザアカイは立ち上がり、主に言った。「主よ、ご覧ください。私は財産の半分を貧しい人たちに施します。だれかから脅し取った物があれば、四倍にして返します。」'),
('JPN', '路加福音', 42, 19, 9, 'イエスは彼に言われた。「今日、救いがこの家に来ました。この人もアブラハムの子なのですから。'),
('JPN', '路加福音', 42, 19, 10, '人の子は、失われた者を捜して救うために来たのです。」'),
('JPN', '路加福音', 42, 19, 11, '人々がこれらのことばに耳を傾けていたとき、イエスは続けて一つのたとえを話された。イエスがエルサレムの近くに来ていて、人々が神の国がすぐに現れると思っていたからである。'),
('JPN', '路加福音', 42, 19, 12, 'イエスはこう言われた。「ある身分の高い人が遠い国に行った。王位を授かって戻って来るためであった。'),
('JPN', '路加福音', 42, 19, 13, '彼はしもべを十人呼んで、彼らに十ミナを与え、『私が帰って来るまで、これで商売をしなさい』と言った。'),
('JPN', '路加福音', 42, 19, 14, '一方、その国の人々は彼を憎んでいたので、彼の後に使者を送り、『この人が私たちの王になるのを、私たちは望んでいません』と伝えた。'),
('JPN', '路加福音', 42, 19, 15, 'さて、彼は王位を授かって帰って来ると、金を与えておいたしもべたちを呼び出すように命じた。彼らがどんな商売をしたかを知ろうと思ったのである。'),
('JPN', '路加福音', 42, 19, 16, '最初のしもべが進み出て言った。『ご主人様、あなた様の一ミナで十ミナをもうけました。』'),
('JPN', '路加福音', 42, 19, 17, '主人は彼に言った。『よくやった。良いしもべだ。おまえはほんの小さなことにも忠実だったから、十の町を支配する者になりなさい。』'),
('JPN', '路加福音', 42, 19, 18, '二番目のしもべが来て言った。『ご主人様、あなた様の一ミナで五ミナをもうけました。』'),
('JPN', '路加福音', 42, 19, 19, '主人は彼にも言った。『おまえも五つの町を治めなさい。』'),
('JPN', '路加福音', 42, 19, 20, 'また別のしもべが来て言った。『ご主人様、ご覧ください。あなた様の一ミナがございます。私は布に包んで、しまっておきました。'),
('JPN', '路加福音', 42, 19, 21, 'あなた様は預けなかったものを取り立て、蒔かなかったものを刈り取られる厳しい方ですから、怖かったのです。』'),
('JPN', '路加福音', 42, 19, 22, '主人はそのしもべに言った。『悪いしもべだ。私はおまえのことばによって、おまえをさばこう。おまえは、私が厳しい人間で、預けなかったものを取り立て、蒔かなかったものを刈り取ると、分かっていたというのか。'),
('JPN', '路加福音', 42, 19, 23, 'それなら、どうして私の金を銀行に預けておかなかったのか。そうしておけば、私が帰って来たとき、それを利息と一緒に受け取れたのに。』'),
('JPN', '路加福音', 42, 19, 24, 'そして、そばに立っていた者たちに言った。『その一ミナをこの者から取り上げて、十ミナ持っている者に与えなさい。』'),
('JPN', '路加福音', 42, 19, 25, 'すると彼らは、『ご主人様、あの人はすでに十ミナ持っています』と言った。'),
('JPN', '路加福音', 42, 19, 26, '彼は言った。『おまえたちに言うが、だれでも持っている者はさらに与えられ、持っていない者からは、持っている物までも取り上げられるのだ。'),
('JPN', '路加福音', 42, 19, 27, 'またさらに、私が王になるのを望まなかったあの敵どもは、ここに連れて来て、私の目の前で打ち殺せ。』」'),
('JPN', '路加福音', 42, 19, 28, 'これらのことを話してから、イエスはさらに進んで、エルサレムへと上って行かれた。'),
('JPN', '路加福音', 42, 19, 29, 'オリーブという山のふもとのベテパゲとベタニアに近づいたとき、イエスはこう言って、二人の弟子を遣わされた。'),
('JPN', '路加福音', 42, 19, 30, '「向こうの村へ行きなさい。そこに入ると、まだだれも乗ったことのない子ろばが、つながれているのに気がつくでしょう。それをほどいて、連れて来なさい。'),
('JPN', '路加福音', 42, 19, 31, 'もし『どうして、ほどくのか』とだれかが尋ねたら、『主がお入り用なのです』と言いなさい。」'),
('JPN', '路加福音', 42, 19, 32, '使いに出された二人が行って見ると、イエスが言われたとおりであった。'),
('JPN', '路加福音', 42, 19, 33, '彼らが子ろばをほどいていると、持ち主たちが、「どうして、子ろばをほどくのか」と彼らに言った。'),
('JPN', '路加福音', 42, 19, 34, '弟子たちは、「主がお入り用なのです」と言った。'),
('JPN', '路加福音', 42, 19, 35, '二人はその子ろばをイエスのもとに連れて来た。そして、その上に自分たちの上着を掛けて、イエスをお乗せした。'),
('JPN', '路加福音', 42, 19, 36, 'イエスが進んで行かれると、人々は道に自分たちの上着を敷いた。'),
('JPN', '路加福音', 42, 19, 37, 'イエスがいよいよオリーブ山の下りにさしかかると、大勢の弟子たちはみな、自分たちが見たすべての力あるわざについて、喜びのあまりに大声で神を賛美し始めて、'),
('JPN', '路加福音', 42, 19, 38, 'こう言った。「祝福あれ、主の御名によって来られる方、王に。天には平和があるように。栄光がいと高き所にあるように。」'),
('JPN', '路加福音', 42, 19, 39, 'するとパリサイ人のうちの何人かが、群衆の中からイエスに向かって、「先生、あなたの弟子たちを叱ってください」と言った。'),
('JPN', '路加福音', 42, 19, 40, 'イエスは答えられた。「わたしは、あなたがたに言います。もしこの人たちが黙れば、石が叫びます。」'),
('JPN', '路加福音', 42, 19, 41, 'エルサレムに近づいて、都をご覧になったイエスは、この都のために泣いて、言われた。'),
('JPN', '路加福音', 42, 19, 42, '「もし、平和に向かう道を、この日おまえも知っていたら──。しかし今、それはおまえの目から隠されている。'),
('JPN', '路加福音', 42, 19, 43, 'やがて次のような時代がおまえに来る。敵はおまえに対して塁を築き、包囲し、四方から攻め寄せ、'),
('JPN', '路加福音', 42, 19, 44, 'そしておまえと、中にいるおまえの子どもたちを地にたたきつける。彼らはおまえの中で、一つの石も、ほかの石の上に積まれたまま残してはおかない。それは、神の訪れの時を、おまえが知らなかったからだ。」'),
('JPN', '路加福音', 42, 19, 45, 'それからイエスは宮に入って、商売人たちを追い出し始め、'),
('JPN', '路加福音', 42, 19, 46, '彼らに言われた。「『わたしの家は祈りの家でなければならない』と書いてある。それなのに、おまえたちはそれを『強盗の巣』にした。」'),
('JPN', '路加福音', 42, 19, 47, 'イエスは毎日、宮で教えておられた。祭司長たち、律法学者たち、そして民のおもだった者たちは、イエスを殺そうと狙っていたが、'),
('JPN', '路加福音', 42, 19, 48, '何をしたらよいのか分からなかった。人々がみな、イエスのことばに熱心に耳を傾けていたからである。'),
('JPN', '路加福音', 42, 20, 1, 'ある日、イエスが宮で人々を教え、福音を宣べ伝えておられると、祭司長たちと律法学者たちが長老たちと一緒にやって来て、'),
('JPN', '路加福音', 42, 20, 2, 'イエスに言った。「何の権威によって、これらのことをしているのか、あなたにその権威を授けたのはだれなのか、教えてくれませんか。」'),
('JPN', '路加福音', 42, 20, 3, 'イエスは彼らに答えられた。「わたしも一言尋ねましょう。それに答えなさい。'),
('JPN', '路加福音', 42, 20, 4, 'ヨハネのバプテスマは、天から来たのですか、それとも人から出たのですか。」'),
('JPN', '路加福音', 42, 20, 5, 'すると、彼らは論じ合った。「もし天からと言えば、どうしてヨハネを信じなかったのかと言うだろう。'),
('JPN', '路加福音', 42, 20, 6, 'だが、もし人からと言えば、民はみな私たちを石で打ち殺すだろう。ヨハネは預言者だと確信しているのだから。」'),
('JPN', '路加福音', 42, 20, 7, 'そこで、「どこから来たのか知りません」と答えた。'),
('JPN', '路加福音', 42, 20, 8, 'するとイエスは彼らに言われた。「わたしも、何の権威によってこれらのことをするのか、あなたがたに言いません。」'),
('JPN', '路加福音', 42, 20, 9, 'また、イエスは人々に対してこのようなたとえを話し始められた。「ある人がぶどう園を造り、それを農夫たちに貸して、長い旅に出た。'),
('JPN', '路加福音', 42, 20, 10, '収穫の時になったので、彼は農夫たちのところに一人のしもべを遣わした。ぶどう園の収穫の一部を納めさせるためであった。ところが農夫たちは、そのしもべを打ちたたき、何も持たせないで帰らせた。'),
('JPN', '路加福音', 42, 20, 11, 'そこで別のしもべを遣わしたが、彼らはそのしもべも打ちたたき、辱めたうえで、何も持たせないで帰らせた。'),
('JPN', '路加福音', 42, 20, 12, '彼はさらに三人目のしもべを遣わしたが、彼らはこのしもべにも傷を負わせて追い出した。'),
('JPN', '路加福音', 42, 20, 13, 'ぶどう園の主人は言った。『どうしようか。そうだ、私の愛する息子を送ろう。この子なら、きっと敬ってくれるだろう。』'),
('JPN', '路加福音', 42, 20, 14, 'ところが、農夫たちはその息子を見ると、互いに議論して『あれは跡取りだ。あれを殺してしまおう。そうすれば、相続財産は自分たちのものになる』と言った。'),
('JPN', '路加福音', 42, 20, 15, 'そして、彼をぶどう園の外に放り出して、殺してしまった。こうなったら、ぶどう園の主人は彼らをどうするでしょうか。'),
('JPN', '路加福音', 42, 20, 16, '主人はやって来て農夫たちを殺し、ぶどう園をほかの人たちに与えるでしょう。」これを聞いた人たちは、「そんなことが起こってはなりません」と言った。'),
('JPN', '路加福音', 42, 20, 17, 'イエスは彼らを見つめて言われた。「では、『家を建てる者たちが捨てた石、それが要の石となった』と書いてあるのは、どういうことなのですか。'),
('JPN', '路加福音', 42, 20, 18, 'だれでもこの石の上に落ちれば、粉々に砕かれ、またこの石が人の上に落ちれば、その人を押しつぶします。」'),
('JPN', '路加福音', 42, 20, 19, '律法学者たちと祭司長たちは、このたとえ話が自分たちを指して語られたことに気づいた。それでそのとき、イエスに手をかけて捕らえようとしたが、民を恐れた。'),
('JPN', '路加福音', 42, 20, 20, 'さて、機会を狙っていた彼らは、義人を装った回し者を遣わした。イエスのことばじりをとらえて、総督の支配と権威に引き渡すためであった。'),
('JPN', '路加福音', 42, 20, 21, '彼らはイエスにこう質問した。「先生。私たちは、あなたがお話しになること、お教えになることが正しく、またあなたが人を分け隔てせず、真理に基づいて神の道を教えておられることを知っています。'),
('JPN', '路加福音', 42, 20, 22, 'ところで、私たちがカエサルに税金を納めることは、律法にかなっているでしょうか、いないでしょうか。」'),
('JPN', '路加福音', 42, 20, 23, 'イエスは彼らの悪巧みを見抜いて言われた。'),
('JPN', '路加福音', 42, 20, 24, '「デナリ銀貨をわたしに見せなさい。だれの肖像と銘がありますか。」彼らは、「カエサルのです」と言った。'),
('JPN', '路加福音', 42, 20, 25, 'すると、イエスは彼らに言われた。「では、カエサルのものはカエサルに、神のものは神に返しなさい。」'),
('JPN', '路加福音', 42, 20, 26, '彼らは、民の前でイエスのことばじりをとらえることができず、答えに驚嘆して黙ってしまった。'),
('JPN', '路加福音', 42, 20, 27, '復活があることを否定しているサドカイ人たちが何人か、イエスのところに来て質問した。'),
('JPN', '路加福音', 42, 20, 28, '「先生、モーセは私たちのためにこう書いています。『もし、ある人の兄が妻を迎えて死に、子がいなかった場合、その弟が兄嫁を妻にして、兄のために子孫を起こさなければならない。』'),
('JPN', '路加福音', 42, 20, 29, 'ところで、七人の兄弟がいました。長男が妻を迎え、子がないままで死にました。'),
('JPN', '路加福音', 42, 20, 30, '次男も、'),
('JPN', '路加福音', 42, 20, 31, '三男もその兄嫁を妻とし、七人とも同じように、子を残さずに死にました。'),
('JPN', '路加福音', 42, 20, 32, '最後に、その妻も死にました。'),
('JPN', '路加福音', 42, 20, 33, 'では復活の際、彼女は彼らのうちのだれの妻になるのでしょうか。七人とも彼女を妻にしたのですが。」'),
('JPN', '路加福音', 42, 20, 34, 'イエスは彼らに言われた。「この世の子らは、めとったり嫁いだりするが、'),
('JPN', '路加福音', 42, 20, 35, '次の世に入るのにふさわしく、死んだ者の中から復活するのにふさわしいと認められた人たちは、めとることも嫁ぐこともありません。'),
('JPN', '路加福音', 42, 20, 36, '彼らが死ぬことは、もうあり得ないからです。彼らは御使いのようであり、復活の子として神の子なのです。'),
('JPN', '路加福音', 42, 20, 37, 'モーセも柴の箇所で、主を『アブラハムの神、イサクの神、ヤコブの神』と呼んで、死んだ者がよみがえることを明らかにしました。'),
('JPN', '路加福音', 42, 20, 38, '神は死んだ者の神ではなく、生きている者の神です。神にとっては、すべての者が生きているのです。」'),
('JPN', '路加福音', 42, 20, 39, '律法学者たちの何人かが、「先生、立派なお答えです」と答えた。'),
('JPN', '路加福音', 42, 20, 40, '彼らはそれ以上、何もあえて質問しようとはしなかった。'),
('JPN', '路加福音', 42, 20, 41, 'すると、イエスが彼らに言われた。「どうして人々は、キリストをダビデの子だと言うのですか。'),
('JPN', '路加福音', 42, 20, 42, 'ダビデ自身が詩篇の中で、こう言っています。『主は、私の主に言われた。「あなたは、わたしの右の座に着いていなさい。'),
('JPN', '路加福音', 42, 20, 43, 'わたしがあなたの敵をあなたの足台とするまで。」』'),
('JPN', '路加福音', 42, 20, 44, 'ですから、ダビデがキリストを主と呼んでいるのです。それなら、どうしてキリストがダビデの子なのでしょう。」'),
('JPN', '路加福音', 42, 20, 45, 'また、人々がみな耳を傾けているときに、イエスは弟子たちに言われた。'),
('JPN', '路加福音', 42, 20, 46, '「律法学者たちには用心しなさい。彼らは長い衣を着て歩き回ることが好きで、広場であいさつされることや会堂の上席、宴会の上座を好みます。'),
('JPN', '路加福音', 42, 20, 47, 'また、やもめの家を食い尽くし、見栄を張って長く祈ります。こういう人たちは、より厳しい罰を受けるのです。」'),
('JPN', '路加福音', 42, 21, 1, 'イエスは目を上げて、金持ちたちが献金箱に献金を投げ入れているのを見ておられた。'),
('JPN', '路加福音', 42, 21, 2, 'そして、ある貧しいやもめが、そこにレプタ銅貨を二枚投げ入れるのを見て、'),
('JPN', '路加福音', 42, 21, 3, 'こう言われた。「まことに、あなたがたに言います。この貧しいやもめは、だれよりも多くを投げ入れました。'),
('JPN', '路加福音', 42, 21, 4, 'あの人たちはみな、あり余る中から献金として投げ入れたのに、この人は乏しい中から、持っていた生きる手立てのすべてを投げ入れたのですから。」'),
('JPN', '路加福音', 42, 21, 5, 'さて、宮が美しい石や奉納物で飾られている、と何人かが話していたので、イエスは言われた。'),
('JPN', '路加福音', 42, 21, 6, '「あなたがたが見ているこれらの物ですが、どの石も崩されずに、ほかの石の上に残ることのない日が、やって来ます。」'),
('JPN', '路加福音', 42, 21, 7, 'そこで彼らはイエスに尋ねた。「先生、それでは、いつ、そのようなことが起こるのですか。それが起こるときのしるしは、どのようなものですか。」'),
('JPN', '路加福音', 42, 21, 8, 'イエスは言われた。「惑わされないように気をつけなさい。わたしの名を名乗る者が大勢現れて、『私こそ、その者だ』とか『時は近づいた』とか言います。そんな人たちの後について行ってはいけません。'),
('JPN', '路加福音', 42, 21, 9, '戦争や暴動のことを聞いても、恐れてはいけません。まず、それらのことが必ず起こりますが、終わりはすぐには来ないからです。」'),
('JPN', '路加福音', 42, 21, 10, 'それから、イエスは彼らに言われた。「民族は民族に、国は国に敵対して立ち上がり、'),
('JPN', '路加福音', 42, 21, 11, '大きな地震があり、方々に飢饉や疫病が起こり、恐ろしい光景や天からの大きなしるしが現れます。'),
('JPN', '路加福音', 42, 21, 12, 'しかし、これらのことすべてが起こる前に、人々はあなたがたに手をかけて迫害し、会堂や牢に引き渡し、わたしの名のために、あなたがたを王たちや総督たちの前に引き出します。'),
('JPN', '路加福音', 42, 21, 13, 'それは、あなたがたにとって証しをする機会となります。'),
('JPN', '路加福音', 42, 21, 14, 'ですから、どう弁明するかは、あらかじめ考えない、と心に決めておきなさい。'),
('JPN', '路加福音', 42, 21, 15, 'あなたがたに反対するどんな人も、対抗したり反論したりできないことばと知恵を、わたしが与えるからです。'),
('JPN', '路加福音', 42, 21, 16, 'あなたがたは、両親、兄弟、親族、友人たちにも裏切られます。中には殺される人もいます。'),
('JPN', '路加福音', 42, 21, 17, 'また、わたしの名のために、すべての人に憎まれます。'),
('JPN', '路加福音', 42, 21, 18, 'しかし、あなたがたの髪の毛一本も失われることはありません。'),
('JPN', '路加福音', 42, 21, 19, 'あなたがたは、忍耐することによって自分のいのちを勝ち取りなさい。'),
('JPN', '路加福音', 42, 21, 20, 'しかし、エルサレムが軍隊に囲まれるのを見たら、そのときには、その滅亡が近づいたことを悟りなさい。'),
('JPN', '路加福音', 42, 21, 21, 'そのとき、ユダヤにいる人たちは山へ逃げなさい。都の中にいる人たちはそこから出て行きなさい。田舎にいる人たちは都に入ってはいけません。'),
('JPN', '路加福音', 42, 21, 22, '書かれていることがすべて成就する、報復の日々だからです。'),
('JPN', '路加福音', 42, 21, 23, 'それらの日、身重の女たちと乳飲み子を持つ女たちは哀れです。この地に大きな苦難があり、この民に御怒りが臨むからです。'),
('JPN', '路加福音', 42, 21, 24, '人々は剣の刃に倒れ、捕虜となって、あらゆる国の人々のところに連れて行かれ、異邦人の時が満ちるまで、エルサレムは異邦人に踏み荒らされます。'),
('JPN', '路加福音', 42, 21, 25, 'それから、太陽と月と星にしるしが現れ、地上では海と波が荒れどよめいて、諸国の民が不安に陥って苦悩します。'),
('JPN', '路加福音', 42, 21, 26, '人々は、この世界に起ころうとしていることを予測して、恐ろしさのあまり気を失います。天のもろもろの力が揺り動かされるからです。'),
('JPN', '路加福音', 42, 21, 27, 'そのとき人々は、人の子が雲のうちに、偉大な力と栄光とともに来るのを見るのです。'),
('JPN', '路加福音', 42, 21, 28, 'これらのことが起こり始めたら、身を起こし、頭を上げなさい。あなたがたの贖いが近づいているからです。」'),
('JPN', '路加福音', 42, 21, 29, 'それからイエスは、人々にたとえを話された。「いちじくの木や、すべての木を見なさい。'),
('JPN', '路加福音', 42, 21, 30, '木の芽が出ると、それを見て、すでに夏が近いことが、おのずから分かります。'),
('JPN', '路加福音', 42, 21, 31, '同じように、これらのことが起こるのを見たら、あなたがたは神の国が近いことを知りなさい。'),
('JPN', '路加福音', 42, 21, 32, 'まことに、あなたがたに言います。すべてのことが起こるまで、この時代が過ぎ去ることは決してありません。'),
('JPN', '路加福音', 42, 21, 33, '天地は消え去ります。しかし、わたしのことばは決して消え去ることがありません。'),
('JPN', '路加福音', 42, 21, 34, 'あなたがたの心が、放蕩や深酒や生活の思い煩いで押しつぶされていて、その日が罠のように、突然あなたがたに臨むことにならないように、よく気をつけなさい。'),
('JPN', '路加福音', 42, 21, 35, 'その日は、全地の表に住むすべての人に突然臨むのです。'),
('JPN', '路加福音', 42, 21, 36, 'しかし、あなたがたは、必ず起こるこれらすべてのことから逃れて、人の子の前に立つことができるように、いつも目を覚まして祈っていなさい。」'),
('JPN', '路加福音', 42, 21, 37, 'こうしてイエスは、昼は宮で教え、夜は外に出てオリーブという山で過ごされた。'),
('JPN', '路加福音', 42, 21, 38, '人々はみな朝早く、教えを聞こうとして、宮におられるイエスのもとにやって来た。'),
('JPN', '路加福音', 42, 22, 1, 'さて、過越の祭りと言われる、種なしパンの祭りが近づいていた。'),
('JPN', '路加福音', 42, 22, 2, '祭司長、律法学者たちは、イエスを殺すための良い方法を探していた。彼らは民を恐れていたのである。'),
('JPN', '路加福音', 42, 22, 3, 'ところで、十二人の一人で、イスカリオテと呼ばれるユダに、サタンが入った。'),
('JPN', '路加福音', 42, 22, 4, 'ユダは行って、祭司長たちや宮の守衛長たちと、どのようにしてイエスを彼らに引き渡すか相談した。'),
('JPN', '路加福音', 42, 22, 5, '彼らは喜んで、ユダに金を与える約束をした。'),
('JPN', '路加福音', 42, 22, 6, 'ユダは承知し、群衆がいないときにイエスを彼らに引き渡そうと機会を狙っていた。'),
('JPN', '路加福音', 42, 22, 7, '過越の子羊が屠られる、種なしパンの祭りの日が来た。'),
('JPN', '路加福音', 42, 22, 8, 'イエスは、「過越の食事ができるように、行って用意をしなさい」と言って、ペテロとヨハネを遣わされた。'),
('JPN', '路加福音', 42, 22, 9, '彼らがイエスに、「どこに用意しましょうか」と言うと、'),
('JPN', '路加福音', 42, 22, 10, 'イエスは言われた。「いいですか。都に入ると、水がめを運んでいる人に会います。その人が入る家までついて行きなさい。'),
('JPN', '路加福音', 42, 22, 11, 'そして、その家の主人に、『弟子たちと一緒に過越の食事をする客間はどこか、と先生があなたに言っております』と言いなさい。'),
('JPN', '路加福音', 42, 22, 12, 'すると主人は、席が整っている二階の大広間を見せてくれます。そこに用意をしなさい。」'),
('JPN', '路加福音', 42, 22, 13, '彼らが行ってみると、イエスが言われたとおりであった。それで、彼らは過越の用意をした。'),
('JPN', '路加福音', 42, 22, 14, 'その時刻が来て、イエスは席に着かれ、使徒たちも一緒に座った。'),
('JPN', '路加福音', 42, 22, 15, 'イエスは彼らに言われた。「わたしは、苦しみを受ける前に、あなたがたと一緒にこの過越の食事をすることを、切に願っていました。'),
('JPN', '路加福音', 42, 22, 16, 'あなたがたに言います。過越が神の国において成就するまで、わたしが過越の食事をすることは、決してありません。」'),
('JPN', '路加福音', 42, 22, 17, 'そしてイエスは杯を取り、感謝の祈りをささげてから言われた。「これを取り、互いの間で分けて飲みなさい。'),
('JPN', '路加福音', 42, 22, 18, 'あなたがたに言います。今から神の国が来る時まで、わたしがぶどうの実からできた物を飲むことは、決してありません。」'),
('JPN', '路加福音', 42, 22, 19, 'それからパンを取り、感謝の祈りをささげた後これを裂き、弟子たちに与えて言われた。「これは、あなたがたのために与えられる、わたしのからだです。わたしを覚えて、これを行いなさい。」'),
('JPN', '路加福音', 42, 22, 20, '食事の後、杯も同じようにして言われた。「この杯は、あなたがたのために流される、わたしの血による、新しい契約です。'),
('JPN', '路加福音', 42, 22, 21, 'しかし見なさい。わたしを裏切る者の手が、わたしとともに食卓の上にあります。'),
('JPN', '路加福音', 42, 22, 22, '人の子は、定められたとおり去って行きます。しかし、人の子を裏切るその人はわざわいです。」'),
('JPN', '路加福音', 42, 22, 23, 'そこで弟子たちは、自分たちのうちのだれが、そんなことをしようとしているのかと、互いに議論をし始めた。'),
('JPN', '路加福音', 42, 22, 24, 'また、彼らの間で、自分たちのうちでだれが一番偉いのだろうか、という議論も起こった。'),
('JPN', '路加福音', 42, 22, 25, 'すると、イエスは彼らに言われた。「異邦人の王たちは人々を支配し、また人々に対し権威を持つ者は守護者と呼ばれています。'),
('JPN', '路加福音', 42, 22, 26, 'しかし、あなたがたは、そうであってはいけません。あなたがたの間で一番偉い人は、一番若い者のようになりなさい。上に立つ人は、給仕する者のようになりなさい。'),
('JPN', '路加福音', 42, 22, 27, '食卓に着く人と給仕する者と、どちらが偉いでしょうか。食卓に着く人ではありませんか。しかし、わたしはあなたがたの間で、給仕する者のようにしています。'),
('JPN', '路加福音', 42, 22, 28, 'あなたがたは、わたしの様々な試練の時に、一緒に踏みとどまってくれた人たちです。'),
('JPN', '路加福音', 42, 22, 29, 'わたしの父がわたしに王権を委ねてくださったように、わたしもあなたがたに王権を委ねます。'),
('JPN', '路加福音', 42, 22, 30, 'そうしてあなたがたは、わたしの国でわたしの食卓に着いて食べたり飲んだりし、王座に着いて、イスラエルの十二の部族を治めるのです。'),
('JPN', '路加福音', 42, 22, 31, 'シモン、シモン。見なさい。サタンがあなたがたを麦のようにふるいにかけることを願って、聞き届けられました。'),
('JPN', '路加福音', 42, 22, 32, 'しかし、わたしはあなたのために、あなたの信仰がなくならないように祈りました。ですから、あなたは立ち直ったら、兄弟たちを力づけてやりなさい。」'),
('JPN', '路加福音', 42, 22, 33, 'シモンはイエスに言った。「主よ。あなたとご一緒なら、牢であろうと、死であろうと、覚悟はできております。」'),
('JPN', '路加福音', 42, 22, 34, 'しかし、イエスは言われた。「ペテロ、あなたに言っておきます。今日、鶏が鳴くまでに、あなたは三度わたしを知らないと言います。」'),
('JPN', '路加福音', 42, 22, 35, 'それから、イエスは弟子たちに言われた。「わたしがあなたがたを、財布も袋も履き物も持たせずに遣わしたとき、何か足りない物がありましたか。」彼らは、「いいえ、何もありませんでした」と答えた。'),
('JPN', '路加福音', 42, 22, 36, 'すると言われた。「しかし今は、財布のある者は財布を持ち、同じように袋も持ちなさい。剣のない者は上着を売って剣を買いなさい。'),
('JPN', '路加福音', 42, 22, 37, 'あなたがたに言いますが、『彼は不法な者たちとともに数えられた』と書かれていること、それがわたしに必ず実現します。わたしに関わることは実現するのです。」'),
('JPN', '路加福音', 42, 22, 38, '彼らが、「主よ、ご覧ください。ここに剣が二本あります」と言うと、イエスは、「それで十分」と答えられた。'),
('JPN', '路加福音', 42, 22, 39, 'それからイエスは出て行き、いつものようにオリーブ山に行かれた。弟子たちもイエスに従った。'),
('JPN', '路加福音', 42, 22, 40, 'いつもの場所に来ると、イエスは彼らに、「誘惑に陥らないように祈っていなさい」と言われた。'),
('JPN', '路加福音', 42, 22, 41, 'そして、ご自分は弟子たちから離れて、石を投げて届くほどのところに行き、ひざまずいて祈られた。'),
('JPN', '路加福音', 42, 22, 42, '「父よ、みこころなら、この杯をわたしから取り去ってください。しかし、わたしの願いではなく、みこころがなりますように。」'),
('JPN', '路加福音', 42, 22, 43, '〔すると、御使いが天から現れて、イエスを力づけた。'),
('JPN', '路加福音', 42, 22, 44, 'イエスは苦しみもだえて、いよいよ切に祈られた。汗が血のしずくのように地に落ちた。〕'),
('JPN', '路加福音', 42, 22, 45, 'イエスが祈り終わって立ち上がり、弟子たちのところに行ってご覧になると、彼らは悲しみの果てに眠り込んでいた。'),
('JPN', '路加福音', 42, 22, 46, 'そこで、彼らに言われた。「どうして眠っているのか。誘惑に陥らないように、起きて祈っていなさい。」'),
('JPN', '路加福音', 42, 22, 47, 'イエスがまだ話をしておられるうちに、見よ、群衆がやって来た。十二人の一人で、ユダという者が先頭に立っていた。ユダはイエスに口づけしようとして近づいた。'),
('JPN', '路加福音', 42, 22, 48, 'しかし、イエスは彼に言われた。「ユダ、あなたは口づけで人の子を裏切るのか。」'),
('JPN', '路加福音', 42, 22, 49, 'イエスの周りにいた者たちは、事の成り行きを見て、「主よ、剣で切りつけましょうか」と言った。'),
('JPN', '路加福音', 42, 22, 50, 'そして、そのうちの一人が大祭司のしもべに切りかかり、右の耳を切り落とした。'),
('JPN', '路加福音', 42, 22, 51, 'するとイエスは、「やめなさい。そこまでにしなさい」と言われた。そして、耳にさわって彼を癒やされた。'),
('JPN', '路加福音', 42, 22, 52, 'それからイエスは、押しかけて来た祭司長たち、宮の守衛長たち、長老たちに言われた。「まるで強盗にでも向かうように、剣や棒を持って出て来たのですか。'),
('JPN', '路加福音', 42, 22, 53, 'わたしが毎日、宮で一緒にいる間、あなたがたはわたしに手をかけませんでした。しかし、今はあなたがたの時、暗闇の力です。」'),
('JPN', '路加福音', 42, 22, 54, '彼らはイエスを捕らえ、引いて行き、大祭司の家に連れて入った。ペテロは遠く離れてついて行った。'),
('JPN', '路加福音', 42, 22, 55, '人々が中庭の真ん中に火をたいて、座り込んでいたので、ペテロも中に交じって腰を下ろした。'),
('JPN', '路加福音', 42, 22, 56, 'すると、ある召使いの女が、明かりの近くに座っているペテロを目にし、じっと見つめて言った。「この人も、イエスと一緒にいました。」'),
('JPN', '路加福音', 42, 22, 57, 'しかし、ペテロはそれを否定して、「いや、私はその人を知らない」と言った。'),
('JPN', '路加福音', 42, 22, 58, 'しばらくして、ほかの男が彼を見て言った。「あなたも彼らの仲間だ。」しかし、ペテロは「いや、違う」と言った。'),
('JPN', '路加福音', 42, 22, 59, 'それから一時間ほどたつと、また別の男が強く主張した。「確かにこの人も彼と一緒だった。ガリラヤ人だから。」'),
('JPN', '路加福音', 42, 22, 60, 'しかしペテロは、「あなたの言っていることは分からない」と言った。するとすぐ、彼がまだ話しているうちに、鶏が鳴いた。'),
('JPN', '路加福音', 42, 22, 61, '主は振り向いてペテロを見つめられた。ペテロは、「今日、鶏が鳴く前に、あなたは三度わたしを知らないと言います」と言われた主のことばを思い出した。'),
('JPN', '路加福音', 42, 22, 62, 'そして、外に出て行って、激しく泣いた。'),
('JPN', '路加福音', 42, 22, 63, 'さて、イエスを監視していた者たちは、イエスをからかい、むちでたたいた。'),
('JPN', '路加福音', 42, 22, 64, 'そして目隠しをして、「当ててみろ、おまえを打ったのはだれだ」と聞いた。'),
('JPN', '路加福音', 42, 22, 65, 'また、ほかにも多くの冒瀆のことばをイエスに浴びせた。'),
('JPN', '路加福音', 42, 22, 66, '夜が明けると、民の長老会、祭司長たちや律法学者たちが集まり、イエスを彼らの最高法院に連れ出して、こう言った。'),
('JPN', '路加福音', 42, 22, 67, '「おまえがキリストなら、そうだと言え。」しかしイエスは言われた。「わたしが言っても、あなたがたは決して信じないでしょう。'),
('JPN', '路加福音', 42, 22, 68, 'わたしが尋ねても、あなたがたは決して答えないでしょう。'),
('JPN', '路加福音', 42, 22, 69, 'だが今から後、人の子は力ある神の右の座に着きます。」'),
('JPN', '路加福音', 42, 22, 70, '彼らはみな言った。「では、おまえは神の子なのか。」イエスは彼らに答えられた。「あなたがたの言うとおり、わたしはそれです。」'),
('JPN', '路加福音', 42, 22, 71, 'そこで彼らは「どうして、これ以上証言が必要だろうか。私たち自身が彼の口から聞いたのだ」と言った。'),
('JPN', '路加福音', 42, 23, 1, '集まっていた彼ら全員は立ち上がり、イエスをピラトのもとに連れて行った。'),
('JPN', '路加福音', 42, 23, 2, 'そしてイエスを訴え始めて、こう言った。「この者はわが民を惑わし、カエサルに税金を納めることを禁じ、自分は王キリストだと言っていることが分かりました。」'),
('JPN', '路加福音', 42, 23, 3, 'そこでピラトはイエスに尋ねた。「あなたはユダヤ人の王なのか。」イエスは答えられた。「あなたがそう言っています。」'),
('JPN', '路加福音', 42, 23, 4, 'ピラトは祭司長たちや群衆に、「この人には、訴える理由が何も見つからない」と言った。'),
('JPN', '路加福音', 42, 23, 5, 'しかし彼らは、「この者は、ガリラヤから始めてここまで、ユダヤ全土で教えながら民衆を扇動しているのです」と言い張った。'),
('JPN', '路加福音', 42, 23, 6, 'それを聞いたピラトは、この人はガリラヤ人かと尋ね、'),
('JPN', '路加福音', 42, 23, 7, 'ヘロデの支配下にあると分かると、イエスをヘロデのところに送った。ヘロデもそのころ、エルサレムにいたのである。'),
('JPN', '路加福音', 42, 23, 8, 'ヘロデはイエスを見ると、非常に喜んだ。イエスのことを聞いていて、ずっと前から会いたいと思い、またイエスが行うしるしを何か見たいと望んでいたからである。'),
('JPN', '路加福音', 42, 23, 9, 'それで、いろいろと質問したが、イエスは何もお答えにならなかった。'),
('JPN', '路加福音', 42, 23, 10, '祭司長たちと律法学者たちはその場にいて、イエスを激しく訴えていた。'),
('JPN', '路加福音', 42, 23, 11, 'ヘロデもまた、自分の兵士たちと一緒にイエスを侮辱したり、からかったりしてから、はでな衣を着せてピラトに送り返した。'),
('JPN', '路加福音', 42, 23, 12, 'この日、ヘロデとピラトは親しくなった。それまでは互いに敵対していたのである。'),
('JPN', '路加福音', 42, 23, 13, 'ピラトは、祭司長たちと議員たち、そして民衆を呼び集め、'),
('JPN', '路加福音', 42, 23, 14, 'こう言った。「おまえたちはこの人を、民衆を惑わす者として私のところに連れて来た。私がおまえたちの前で取り調べたところ、おまえたちが訴えているような罪は何も見つからなかった。'),
('JPN', '路加福音', 42, 23, 15, 'ヘロデも同様だった。私たちにこの人を送り返して来たのだから。見なさい。この人は死に値することを何もしていない。'),
('JPN', '路加福音', 42, 23, 16, 'だから私は、むちで懲らしめたうえで釈放する。」'),
('JPN', '路加福音', 42, 23, 18, 'しかし彼らは一斉に叫んだ。「その男を殺せ。バラバを釈放しろ。」'),
('JPN', '路加福音', 42, 23, 19, 'バラバは、都に起こった暴動と人殺しのかどで、牢に入れられていた者であった。'),
('JPN', '路加福音', 42, 23, 20, 'ピラトはイエスを釈放しようと思って、再び彼らに呼びかけた。'),
('JPN', '路加福音', 42, 23, 21, 'しかし彼らは、「十字架だ。十字架につけろ」と叫び続けた。'),
('JPN', '路加福音', 42, 23, 22, 'ピラトは彼らに三度目に言った。「この人がどんな悪いことをしたというのか。彼には、死に値する罪が何も見つからなかった。だから私は、むちで懲らしめたうえで釈放する。」'),
('JPN', '路加福音', 42, 23, 23, 'けれども、彼らはイエスを十字架につけるように、しつこく大声で要求し続けた。そして、その声がいよいよ強くなっていった。'),
('JPN', '路加福音', 42, 23, 24, 'それでピラトは、彼らの要求どおりにすることに決めた。'),
('JPN', '路加福音', 42, 23, 25, 'すなわち、暴動と人殺しのかどで牢に入れられていた男を願いどおりに釈放し、他方イエスを彼らに引き渡して好きなようにさせた。'),
('JPN', '路加福音', 42, 23, 26, '彼らはイエスを引いて行く途中、田舎から出て来たシモンというクレネ人を捕まえ、この人に十字架を負わせてイエスの後から運ばせた。'),
('JPN', '路加福音', 42, 23, 27, '民衆や、イエスのことを嘆き悲しむ女たちが大きな一群をなして、イエスの後について行った。'),
('JPN', '路加福音', 42, 23, 28, 'イエスは彼女たちの方を振り向いて言われた。「エルサレムの娘たち、わたしのために泣いてはいけません。むしろ自分自身と、自分の子どもたちのために泣きなさい。'),
('JPN', '路加福音', 42, 23, 29, 'なぜなら人々が、『不妊の女、子を産んだことのない胎、飲ませたことのない乳房は幸いだ』と言う日が来るのですから。'),
('JPN', '路加福音', 42, 23, 30, 'そのとき、人々は山々に向かって『私たちの上に崩れ落ちよ』と言い、丘に向かって『私たちをおおえ』と言い始めます。'),
('JPN', '路加福音', 42, 23, 31, '生木にこのようなことが行われるなら、枯れ木には、いったい何が起こるでしょうか。」'),
('JPN', '路加福音', 42, 23, 32, 'ほかにも二人の犯罪人が、イエスとともに死刑にされるために引かれて行った。'),
('JPN', '路加福音', 42, 23, 33, '「どくろ」と呼ばれている場所に来ると、そこで彼らはイエスを十字架につけた。また犯罪人たちを、一人は右に、もう一人は左に十字架につけた。'),
('JPN', '路加福音', 42, 23, 34, 'そのとき、イエスはこう言われた。「父よ、彼らをお赦しください。彼らは、自分が何をしているのかが分かっていないのです。」彼らはイエスの衣を分けるために、くじを引いた。'),
('JPN', '路加福音', 42, 23, 35, '民衆は立って眺めていた。議員たちもあざ笑って言った。「あれは他人を救った。もし神のキリストで、選ばれた者なら、自分を救ったらよい。」'),
('JPN', '路加福音', 42, 23, 36, '兵士たちも近くに来て、酸いぶどう酒を差し出し、'),
('JPN', '路加福音', 42, 23, 37, '「おまえがユダヤ人の王なら、自分を救ってみろ」と言ってイエスを嘲った。'),
('JPN', '路加福音', 42, 23, 38, '「これはユダヤ人の王」と書いた札も、イエスの頭の上に掲げてあった。'),
('JPN', '路加福音', 42, 23, 39, '十字架にかけられていた犯罪人の一人は、イエスをののしり、「おまえはキリストではないか。自分とおれたちを救え」と言った。'),
('JPN', '路加福音', 42, 23, 40, 'すると、もう一人が彼をたしなめて言った。「おまえは神を恐れないのか。おまえも同じ刑罰を受けているではないか。'),
('JPN', '路加福音', 42, 23, 41, 'おれたちは、自分のしたことの報いを受けているのだから当たり前だ。だがこの方は、悪いことを何もしていない。」'),
('JPN', '路加福音', 42, 23, 42, 'そして言った。「イエス様。あなたが御国に入られるときには、私を思い出してください。」'),
('JPN', '路加福音', 42, 23, 43, 'イエスは彼に言われた。「まことに、あなたに言います。あなたは今日、わたしとともにパラダイスにいます。」'),
('JPN', '路加福音', 42, 23, 44, 'さて、時はすでに十二時ごろであった。全地が暗くなり、午後三時まで続いた。'),
('JPN', '路加福音', 42, 23, 45, '太陽は光を失っていた。すると神殿の幕が真ん中から裂けた。'),
('JPN', '路加福音', 42, 23, 46, 'イエスは大声で叫ばれた。「父よ、わたしの霊をあなたの御手にゆだねます。」こう言って、息を引き取られた。'),
('JPN', '路加福音', 42, 23, 47, '百人隊長はこの出来事を見て、神をほめたたえ、「本当にこの方は正しい人であった」と言った。'),
('JPN', '路加福音', 42, 23, 48, 'また、この光景を見に集まっていた群衆もみな、これらの出来事を見て、悲しみのあまり胸をたたきながら帰って行った。'),
('JPN', '路加福音', 42, 23, 49, 'しかし、イエスの知人たちや、ガリラヤからイエスについて来ていた女たちはみな、離れたところに立ち、これらのことを見ていた。'),
('JPN', '路加福音', 42, 23, 50, 'さて、ここにヨセフという人がいたが、議員の一人で、善良で正しい人であった。'),
('JPN', '路加福音', 42, 23, 51, 'ユダヤ人の町アリマタヤの出身で、神の国を待ち望んでいた彼は、議員たちの計画や行動には同意していなかった。'),
('JPN', '路加福音', 42, 23, 52, 'この人がピラトのところに行って、イエスのからだの下げ渡しを願い出た。'),
('JPN', '路加福音', 42, 23, 53, '彼はからだを降ろして亜麻布で包み、まだだれも葬られていない、岩に掘った墓に納めた。'),
('JPN', '路加福音', 42, 23, 54, 'この日は備え日で、安息日が始まろうとしていた。'),
('JPN', '路加福音', 42, 23, 55, 'イエスとともにガリラヤから来ていた女たちは、ヨセフの後について行き、墓と、イエスのからだが納められる様子を見届けた。'),
('JPN', '路加福音', 42, 23, 56, 'それから、戻って香料と香油を用意した。そして安息日には、戒めにしたがって休んだ。'),
('JPN', '路加福音', 42, 24, 1, '週の初めの日の明け方早く、彼女たちは準備しておいた香料を持って墓に来た。'),
('JPN', '路加福音', 42, 24, 2, '見ると、石が墓からわきに転がされていた。'),
('JPN', '路加福音', 42, 24, 3, 'そこで中に入ると、主イエスのからだは見当たらなかった。'),
('JPN', '路加福音', 42, 24, 4, 'そのため途方に暮れていると、見よ、まばゆいばかりの衣を着た人が二人、近くに来た。'),
('JPN', '路加福音', 42, 24, 5, '彼女たちは恐ろしくなって、地面に顔を伏せた。すると、その人たちはこう言った。「あなたがたは、どうして生きている方を死人の中に捜すのですか。'),
('JPN', '路加福音', 42, 24, 6, 'ここにはおられません。よみがえられたのです。まだガリラヤにおられたころ、主がお話しになったことを思い出しなさい。'),
('JPN', '路加福音', 42, 24, 7, '人の子は必ず罪人たちの手に引き渡され、十字架につけられ、三日目によみがえると言われたでしょう。」'),
('JPN', '路加福音', 42, 24, 8, '彼女たちはイエスのことばを思い出した。'),
('JPN', '路加福音', 42, 24, 9, 'そして墓から戻って、十一人とほかの人たち全員に、これらのことをすべて報告した。'),
('JPN', '路加福音', 42, 24, 10, 'それは、マグダラのマリア、ヨハンナ、ヤコブの母マリア、そして彼女たちとともにいた、ほかの女たちであった。彼女たちはこれらのことを使徒たちに話したが、'),
('JPN', '路加福音', 42, 24, 11, 'この話はたわごとのように思えたので、使徒たちは彼女たちを信じなかった。'),
('JPN', '路加福音', 42, 24, 12, 'しかしペテロは立ち上がり、走って墓に行った。そして、かがんでのぞき込むと、亜麻布だけが見えた。それで、この出来事に驚きながら自分のところに帰った。'),
('JPN', '路加福音', 42, 24, 13, 'ところで、ちょうどこの日、弟子たちのうちの二人が、エルサレムから六十スタディオン余り離れた、エマオという村に向かっていた。'),
('JPN', '路加福音', 42, 24, 14, '彼らは、これらの出来事すべてについて話し合っていた。'),
('JPN', '路加福音', 42, 24, 15, '話し合ったり論じ合ったりしているところに、イエスご自身が近づいて来て、彼らとともに歩き始められた。'),
('JPN', '路加福音', 42, 24, 16, 'しかし、二人の目はさえぎられていて、イエスであることが分からなかった。'),
('JPN', '路加福音', 42, 24, 17, 'イエスは彼らに言われた。「歩きながら語り合っているその話は何のことですか。」すると、二人は暗い顔をして立ち止まった。'),
('JPN', '路加福音', 42, 24, 18, 'そして、その一人、クレオパという人がイエスに答えた。「エルサレムに滞在していながら、近ごろそこで起こったことを、あなただけがご存じないのですか。」')
on conflict (version, book, chapter, verse) do nothing;
